/// What storage-api execute and query load before they decide: nothing beyond what every load holds (the schema, members and counters, load-tenant CT-012). The decision asks for the rest (the insufficient-state loop of execute-intent, execute-read, mutate-record and read-view), because the needs of an intent or a read follow from the schema, which only a load gives.
///
/// Specification function `header-needs`.
pub fn header_needs() -> Vec<types::Need> {
    Vec::<types::Need>::new()
}

/// The first need a snapshot does not cover (state.rs Coverage::covers), which a derivation asks for next.
///
/// Specification function `first-missing`.
pub fn first_missing(coverage: &types::Coverage, wanted: &Vec<types::Need>) -> Option<types::Need> {
    wanted.iter().find(|&n| !covers(coverage, n)).cloned()
}

/// backend ops.rs mutate, the reply of an accepted transition that changed a record: its object, id and new version (none after a delete), the revision (the delta's new revision, which the commit's receipt repeats), the tenant event sequence after it, and the number of checks of its evidence. Any other output has no reply.
///
/// Specification function `mutation-reply-of`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn mutation_reply_of(
    t: &types::TransitionResult,
) -> Result<Option<types::MutationReply>, Fault> {
    let checks: i64 = {
        let mut n: i64 = 0;
        for _ in t.evidence.iter() {
            n = n.checked_add(1).ok_or(Fault { op: "+" })?;
        }
        n
    };
    Ok(match &t.output {
        types::Output::Record {
            object,
            id,
            version,
        } => Some(types::MutationReply {
            object: object.clone().0,
            id: id.clone().0,
            version: Some(*version),
            revision: t.delta.new_revision.clone().0,
            event_seq: t.delta.event_seq,
            checks_passed: u64::try_from(checks).map_err(|_| Fault { op: "as" })?,
        }),
        types::Output::Deleted { object, id } => Some(types::MutationReply {
            object: object.clone().0,
            id: id.clone().0,
            version: None,
            revision: t.delta.new_revision.clone().0,
            event_seq: t.delta.event_seq,
            checks_passed: u64::try_from(checks).map_err(|_| Fault { op: "as" })?,
        }),
        _ => None,
    })
}

/// crates/storage-api/src/lib.rs execute, one decision, the decide of contract execute-intent (CT-031): the needs plan-intent-needs names for the snapshot's schema are asked for first, one at a time (storage-api loads them together after a header load); then the kernel decides (intent-decision). An InsufficientState rejection naming a need asks for it; any other rejection is the contract's domain error. An accepted transition is handed to the commit with its intent and its record reply.
///
/// Specification function `execute-decide`; fails with `execute-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn execute_decide(
    state: &types::State,
    intent: &types::Intent,
    context: &types::Context,
) -> Result<types::AcceptedIntent, Failure<types::ExecuteFailure>> {
    Ok(
        match first_missing(
            &state.coverage,
            &needs(
                &(match &state.tenant {
                    Some(t) => Some(<types::TenantSchema as Clone>::clone(&t.schema)),
                    None => None,
                }),
                intent,
            )
            .map_err(Failure::Fault)?,
        ) {
            Some(n) => {
                return Err(Failure::Error(types::ExecuteFailure::InsufficientState(
                    n.clone(),
                )));
            }
            None => {
                match match intent_decision(state, intent, context) {
                    Ok(value_) => Ok(value_),
                    Err(Failure::Error(error_)) => Err(error_),
                    Err(Failure::Fault(fault_)) => return Err(Failure::Fault(fault_)),
                } {
                    Ok(tr) => types::AcceptedIntent {
                        intent: intent.clone(),
                        transition: tr.clone(),
                        reply: mutation_reply_of(&tr).map_err(Failure::Fault)?,
                    },
                    Err(e) => match &e {
                        types::Rejection::Rejected(d) => match &d.missing {
                            Some(n) => {
                                if d.kind == types::ErrorKind::InsufficientState {
                                    return Err(Failure::Error(
                                        types::ExecuteFailure::InsufficientState(n.clone()),
                                    ));
                                } else {
                                    return Err(Failure::Error(types::ExecuteFailure::Domain(
                                        d.clone(),
                                    )));
                                }
                            }
                            None => {
                                return Err(Failure::Error(types::ExecuteFailure::Domain(
                                    d.clone(),
                                )));
                            }
                        },
                    },
                }
            }
        },
    )
}

/// backend ops.rs mutate, the field a coercion problem names: problem.split(':').next().trim(), which is the field of "<field>: <error>" and the whole text of "<object> has no field <name>". Read here as the given field whose name and a colon begin the problem, else the whole problem; the two differ only for an unknown field whose name holds a colon (no string operations, WG-4957).
///
/// Specification function `problem-field`.
pub fn problem_field(
    problem: &String,
    fields: &std::collections::BTreeMap<String, types::PlainJson>,
) -> String {
    match fields
        .keys()
        .find(|&n| text_starts_with(problem, &format!("{n}:")))
    {
        Some(n) => n.clone(),
        None => problem.clone(),
    }
}

/// backend ops.rs mutate, fields_of: the object type of the tenant's schema (not_found "no object type <object>" without one) and its fields coerced from plain JSON (coerce-fields, with no symbolic references: the resolver gives none); a problem is invalid with the problem as message and one failed check input:<object>.<field> (problem-field). times holds the milliseconds of each string a time field may take (parse_time, a stand-in until string operations exist, WG-4957).
///
/// Specification function `mutation-fields`; fails with `api-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn mutation_fields(
    tenant: &types::TenantState,
    object: &String,
    fields: &std::collections::BTreeMap<String, types::PlainJson>,
    context: &types::Context,
    times: &std::collections::BTreeMap<String, i64>,
) -> Result<std::collections::BTreeMap<types::FieldId, types::Value>, Failure<types::ApiFailure>> {
    Ok(
        match tenant
            .schema
            .objects
            .get(&types::ObjectTypeId(object.clone()))
        {
            None => {
                return Err(Failure::Error(types::ApiFailure::Refused(
                    types::ApiError {
                        code: types::ErrorCode::NotFound,
                        message: format!("no object type {object}"),
                        kind: None,
                        failed: Some(Vec::<types::Check>::new()),
                        correlation: context.correlation.clone(),
                    },
                )));
            }
            Some(def) => {
                match match coerce_fields(
                    def,
                    fields,
                    &std::collections::BTreeMap::<String, types::RecordId>::new(),
                    times,
                ) {
                    Ok(value_) => Ok(value_),
                    Err(Failure::Error(error_)) => Err(error_),
                    Err(Failure::Fault(fault_)) => return Err(Failure::Fault(fault_)),
                } {
                    Ok(m) => m.clone(),
                    Err(e) => match &e {
                        types::PlainError::Message(p) => {
                            return Err(Failure::Error(types::ApiFailure::Refused(
                                types::ApiError {
                                    code: types::ErrorCode::Invalid,
                                    message: p.clone(),
                                    kind: None,
                                    failed: Some(vec![types::Check {
                                        rule: format!(
                                            "input:{object}.{}",
                                            problem_field(p, fields)
                                        ),
                                        passed: false,
                                        detail: p.clone(),
                                    }]),
                                    correlation: context.correlation.clone(),
                                },
                            )));
                        }
                    },
                }
            }
        },
    )
}

/// backend ops.rs mutate up to the intent: the tenant must exist (header: not_found "no site <tenant>"); a create or an update coerces its fields (mutation-fields) and becomes CreateRecord or UpdateRecord, a delete DeleteRecord. An object name that is not a valid ObjectTypeId is not checked here (the backend answers not_found "no object type <name>" before the kernel; here the kernel answers UnknownObject), a gap of the missing string operations (WG-4957).
///
/// Specification function `coerce-mutation`; fails with `api-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn coerce_mutation(
    mutation: &types::Mutation,
    state: &types::State,
    context: &types::Context,
    times: &std::collections::BTreeMap<String, i64>,
) -> Result<types::Intent, Failure<types::ApiFailure>> {
    let site = match &state.tenant {
        Some(t) => t.clone(),
        None => {
            return Err(Failure::Error(types::ApiFailure::Refused(
                types::ApiError {
                    code: types::ErrorCode::NotFound,
                    message: format!("no site {}", context.tenant.0),
                    kind: None,
                    failed: Some(Vec::<types::Check>::new()),
                    correlation: context.correlation.clone(),
                },
            )));
        }
    };
    Ok(match mutation {
        types::Mutation::Create { object, fields } => types::Intent::CreateRecord {
            object: types::ObjectTypeId::new(object.clone())
                .map_err(|_| Failure::Fault(Fault { op: "new" }))?,
            fields: mutation_fields(
                std::sync::Arc::as_ref(&site),
                object,
                fields,
                context,
                times,
            )?,
        },
        types::Mutation::Update {
            object,
            id,
            fields,
            expected_version,
        } => types::Intent::UpdateRecord {
            object: types::ObjectTypeId::new(object.clone())
                .map_err(|_| Failure::Fault(Fault { op: "new" }))?,
            id: types::RecordId(*id),
            fields: mutation_fields(
                std::sync::Arc::as_ref(&site),
                object,
                fields,
                context,
                times,
            )?,
            expected_version: *expected_version,
        },
        types::Mutation::Delete {
            object,
            id,
            expected_version,
        } => types::Intent::DeleteRecord {
            object: types::ObjectTypeId::new(object.clone())
                .map_err(|_| Failure::Fault(Fault { op: "new" }))?,
            id: types::RecordId(*id),
            expected_version: *expected_version,
        },
    })
}

/// backend ops.rs hide_unreadable (WG-4918): a refused change to a record the caller cannot read answers as the kernel answers a record that is not there, UnknownRecord "no <object> <id>" with a failed intent:unknown_record check; a record the caller may read (visible) keeps the refusal. A record the snapshot does not hold, or does not cover, is not readable. The backend reads the record again with a fresh load and the current time; here it is the snapshot the decision was made on, at the context's time.
///
/// Specification function `unreadable-as-missing`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn unreadable_as_missing(
    d: &types::DomainError,
    tenant: &types::TenantState,
    coverage: &types::Coverage,
    object: &types::ObjectTypeId,
    id: &types::RecordId,
    context: &types::Context,
) -> Result<types::DomainError, Fault> {
    let readable = match lookup_record(tenant, coverage, object, id) {
        Ok(found) => match &found {
            Some(r) => visible(tenant, &context.principal, r, context.now)?,
            None => false,
        },
        Err(_) => false,
    };
    let message = format!("no {} {}", object.0, id.0);
    Ok(if readable {
        d.clone()
    } else {
        types::DomainError {
            kind: types::ErrorKind::UnknownRecord,
            message: message.clone(),
            evidence: vec![types::Check {
                rule: "intent:unknown_record".to_string(),
                passed: false,
                detail: message.clone(),
            }],
            missing: None,
        }
    })
}

/// backend ops.rs mutate, the Unauthorized refusal of an update or a delete passed through hide_unreadable (unreadable-as-missing); every other rejection stands.
///
/// Specification function `hide-unreadable`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn hide_unreadable(
    d: &types::DomainError,
    state: &types::State,
    intent: &types::Intent,
    context: &types::Context,
) -> Result<types::DomainError, Fault> {
    Ok(if d.kind != types::ErrorKind::Unauthorized {
        d.clone()
    } else {
        match &state.tenant {
            None => d.clone(),
            Some(t) => match intent {
                types::Intent::UpdateRecord { object, id, .. } => unreadable_as_missing(
                    d,
                    std::sync::Arc::as_ref(t),
                    &state.coverage,
                    object,
                    id,
                    context,
                )?,
                types::Intent::DeleteRecord { object, id, .. } => unreadable_as_missing(
                    d,
                    std::sync::Arc::as_ref(t),
                    &state.coverage,
                    object,
                    id,
                    context,
                )?,
                _ => d.clone(),
            },
        }
    })
}

/// backend ops.rs mutate, one decision, the decide of contract mutate-record (CT-263): the mutation as an intent (coerce-mutation), its needs asked for first, then the kernel's decision (intent-decision). An InsufficientState rejection naming a need asks for it; any other rejection is answered as the error body (api-error-of, after hide-unreadable). An accepted transition is handed to the commit with its intent and the record reply.
///
/// Specification function `decide-mutation`; fails with `api-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn decide_mutation(
    mutation: &types::Mutation,
    context: &types::Context,
    state: &types::State,
    times: &std::collections::BTreeMap<String, i64>,
) -> Result<types::AcceptedIntent, Failure<types::ApiFailure>> {
    let intent = coerce_mutation(mutation, state, context, times)?;
    Ok(
        match first_missing(
            &state.coverage,
            &needs(
                &(match &state.tenant {
                    Some(t) => Some(<types::TenantSchema as Clone>::clone(&t.schema)),
                    None => None,
                }),
                &intent,
            )
            .map_err(Failure::Fault)?,
        ) {
            Some(n) => {
                return Err(Failure::Error(types::ApiFailure::InsufficientState(
                    n.clone(),
                )));
            }
            None => {
                match match intent_decision(state, &intent, context) {
                    Ok(value_) => Ok(value_),
                    Err(Failure::Error(error_)) => Err(error_),
                    Err(Failure::Fault(fault_)) => return Err(Failure::Fault(fault_)),
                } {
                    Ok(tr) => types::AcceptedIntent {
                        intent: intent.clone(),
                        transition: tr.clone(),
                        reply: mutation_reply_of(&tr).map_err(Failure::Fault)?,
                    },
                    Err(e) => match &e {
                        types::Rejection::Rejected(d) => match &d.missing {
                            Some(n) => {
                                if d.kind == types::ErrorKind::InsufficientState {
                                    return Err(Failure::Error(
                                        types::ApiFailure::InsufficientState(n.clone()),
                                    ));
                                } else {
                                    return Err(Failure::Error(types::ApiFailure::Refused(
                                        api_error_of(
                                            &hide_unreadable(d, state, &intent, context)
                                                .map_err(Failure::Fault)?,
                                            context,
                                        ),
                                    )));
                                }
                            }
                            None => {
                                return Err(Failure::Error(types::ApiFailure::Refused(
                                    api_error_of(
                                        &hide_unreadable(d, state, &intent, context)
                                            .map_err(Failure::Fault)?,
                                        context,
                                    ),
                                )));
                            }
                        },
                    },
                }
            }
        },
    )
}

/// crates/storage-api/src/lib.rs query, the decide of contract execute-read (CT-032): the needs read-needs names for the snapshot's schema (none without a tenant) are asked for first, then the kernel answers (kernel-read); a rejection is the contract's domain error.
///
/// Specification function `execute-read-decide`; fails with `execute-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn execute_read_decide(
    state: &types::State,
    request: &types::ReadRequest,
    context: &types::Context,
) -> Result<types::ReadResult, Failure<types::ExecuteFailure>> {
    Ok(
        match first_missing(
            &state.coverage,
            &(match &state.tenant {
                Some(t) => read_needs(std::sync::Arc::as_ref(&t.schema), request),
                None => Vec::<types::Need>::new(),
            }),
        ) {
            Some(n) => {
                return Err(Failure::Error(types::ExecuteFailure::InsufficientState(
                    n.clone(),
                )));
            }
            None => {
                match match kernel_read(state, request, context) {
                    Ok(value_) => Ok(value_),
                    Err(Failure::Error(error_)) => Err(error_),
                    Err(Failure::Fault(fault_)) => return Err(Failure::Fault(fault_)),
                } {
                    Ok(r) => r.clone(),
                    Err(e) => match &e {
                        types::Rejection::Rejected(d) => match &d.missing {
                            Some(n) => {
                                if d.kind == types::ErrorKind::InsufficientState {
                                    return Err(Failure::Error(
                                        types::ExecuteFailure::InsufficientState(n.clone()),
                                    ));
                                } else {
                                    return Err(Failure::Error(types::ExecuteFailure::Domain(
                                        d.clone(),
                                    )));
                                }
                            }
                            None => {
                                return Err(Failure::Error(types::ExecuteFailure::Domain(
                                    d.clone(),
                                )));
                            }
                        },
                    },
                }
            }
        },
    )
}

/// crates/substrate/src/project.rs match_route: the view (in id order) whose route has as many segments as the path and matches it segment by segment, a literal exactly and a :name taking the path's segment as its parameter; of several, the first with the most literal segments. wanted is the path split at / without empty segments, and routes each view's route so split and read (route-segment): stand-ins until the function language has string operations (WG-4957).
///
/// Specification function `match-route`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn match_route(
    schema: &types::TenantSchema,
    wanted: &Vec<String>,
    routes: &std::collections::BTreeMap<types::ViewId, Vec<types::RouteSegment>>,
) -> Result<Option<types::RouteMatch>, Fault> {
    let picked = {
        let mut best: types::RoutePick = types::RoutePick {
            literal: 0,
            found: None,
        };
        for v in schema.views.values() {
            best = {
                let pattern = match routes.get(&v.id) {
                    Some(p) => p.clone(),
                    None => Vec::<types::RouteSegment>::new(),
                };
                if ({
                    let mut n: i64 = 0;
                    for _ in pattern.iter() {
                        n = n.checked_add(1).ok_or(Fault { op: "+" })?;
                    }
                    n
                }) != ({
                    let mut n: i64 = 0;
                    for _ in wanted.iter() {
                        n = n.checked_add(1).ok_or(Fault { op: "+" })?;
                    }
                    n
                }) {
                    best.clone()
                } else {
                    {
                        let tried = {
                            let mut acc: types::RouteTry = types::RouteTry {
                                at: 0,
                                ok: true,
                                literal: 0,
                                params: std::collections::BTreeMap::<String, String>::new(),
                            };
                            for seg in pattern.iter() {
                                acc = match seg {
                                    types::RouteSegment::Param(name) => types::RouteTry {
                                        at: acc.at.checked_add(1).ok_or(Fault { op: "+" })?,
                                        ok: acc.ok,
                                        literal: acc.literal,
                                        params: if acc.ok {
                                            {
                                                let mut map_ = acc.params.clone();
                                                map_.insert(
                                                    name.clone(),
                                                    match match usize::try_from(acc.at) {
                                                        Ok(index_) => wanted.get(index_).cloned(),
                                                        Err(_) => None,
                                                    } {
                                                        Some(w) => w.clone(),
                                                        None => "".to_string(),
                                                    },
                                                );
                                                map_
                                            }
                                        } else {
                                            acc.params.clone()
                                        },
                                    },
                                    types::RouteSegment::Literal(text) => types::RouteTry {
                                        at: acc.at.checked_add(1).ok_or(Fault { op: "+" })?,
                                        ok: acc.ok
                                            && (match usize::try_from(acc.at) {
                                                Ok(index_) => wanted.get(index_).cloned(),
                                                Err(_) => None,
                                            })
                                            .as_ref()
                                                == Some(text),
                                        literal: if acc.ok {
                                            acc.literal.checked_add(1).ok_or(Fault { op: "+" })?
                                        } else {
                                            acc.literal
                                        },
                                        params: acc.params.clone(),
                                    },
                                };
                            }
                            acc
                        };
                        if tried.ok && (best.found.is_none() || tried.literal > best.literal) {
                            types::RoutePick {
                                literal: tried.literal,
                                found: Some(types::RouteMatch {
                                    view: v.clone(),
                                    params: tried.params.clone(),
                                }),
                            }
                        } else {
                            best.clone()
                        }
                    }
                }
            };
        }
        best
    };
    Ok(picked.found.clone())
}

/// project.rs section_order, depends: whether a section reads an attribute of another section's row.
///
/// Specification function `section-depends`.
pub fn section_depends(section: &types::ViewSection) -> bool {
    section.args.values().any(|a| match a {
        types::ArgSource::Section { .. } => true,
        _ => false,
    })
}

/// crates/substrate/src/project.rs section_order: the section names in evaluation order, those that read no other section first, each group in name order. A section may read only a section that reads none (schema-problems).
///
/// Specification function `section-order`.
pub fn section_order(view: &types::ViewDef) -> Vec<String> {
    support::concat(
        &view
            .sections
            .keys()
            .filter(|&n| match view.sections.get(n) {
                Some(s) => !section_depends(s),
                None => false,
            })
            .cloned()
            .collect::<Vec<_>>(),
        &view
            .sections
            .keys()
            .filter(|&n| match view.sections.get(n) {
                Some(s) => section_depends(s),
                None => false,
            })
            .cloned()
            .collect::<Vec<_>>(),
    )
}

/// project.rs section_request, text: a route or request parameter as a string value, null when absent.
///
/// Specification function `text-value`.
pub fn text_value(text: &Option<String>) -> types::Value {
    match text {
        Some(s) => types::Value::Str(s.clone()),
        None => null_value(),
    }
}

/// crates/substrate/src/project.rs section_request: the named read of a section, each argument (in name order) from a route parameter, a request parameter (each a string, null when absent), a constant, or an attribute of the single row of a section already evaluated (record-attribute; null when that section had no row). An argument that comes from a setting (setting) is null here: the hand-written section_request_with resolves it for the reader.
///
/// Specification function `section-request`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn section_request(
    section: &types::ViewSection,
    route: &std::collections::BTreeMap<String, String>,
    request: &std::collections::BTreeMap<String, String>,
    done: &std::collections::BTreeMap<String, Option<types::Record>>,
) -> Result<types::ReadRequest, Fault> {
    Ok(types::ReadRequest::Named {
        query: section.query.clone(),
        params: {
            let mut m: std::collections::BTreeMap<String, types::Value> =
                std::collections::BTreeMap::<String, types::Value>::new();
            for k in section.args.keys() {
                m = match section.args.get(k) {
                    None => m.clone(),
                    Some(src) => {
                        let mut map_ = m.clone();
                        map_.insert(
                            k.clone(),
                            match src {
                                types::ArgSource::Route(key) => {
                                    text_value(&route.get(key).cloned())
                                }
                                types::ArgSource::Request(key) => {
                                    text_value(&request.get(key).cloned())
                                }
                                types::ArgSource::Const(x) => x.clone(),
                                types::ArgSource::Setting(_) => null_value(),
                                types::ArgSource::Section {
                                    section: from,
                                    attribute,
                                } => match done.get(from) {
                                    Some(row) => match row {
                                        Some(r) => record_attribute(r, attribute)?,
                                        None => null_value(),
                                    },
                                    None => null_value(),
                                },
                            },
                        );
                        map_
                    }
                };
            }
            m
        },
        page_size: None,
        cursor: None,
    })
}

/// state.rs Record::get: a field's value, null when unset.
///
/// Specification function `field-value`.
pub fn field_value(r: &types::Record, field: &types::FieldId) -> types::Value {
    match r.fields.get(field) {
        Some(x) => x.clone(),
        None => null_value(),
    }
}

/// A BTreeSet<RecordId> collected into a list: each id once, in order.
///
/// Specification function `id-set`.
pub fn id_set(ids: &Vec<types::RecordId>) -> Vec<types::RecordId> {
    support::sorted_by(ids.iter(), |i| i128::from(i.clone().0))
        .iter()
        .fold(Vec::<types::RecordId>::new(), |acc, i| {
            if acc.iter().any(|a| a.clone().0 == i.clone().0) {
                acc.clone()
            } else {
                support::concat(&acc, &[i.clone()])
            }
        })
}

/// crates/substrate/src/project.rs included_refs: for each included field of the section that refers to an object type, the record ids the rows name in it (a reference, or the references of a list), each once, in order.
///
/// Specification function `included-refs`.
pub fn included_refs(
    schema: &types::TenantSchema,
    object: &types::ObjectTypeId,
    section: &types::ViewSection,
    rows: &Vec<types::Record>,
) -> std::collections::BTreeMap<types::FieldId, types::IncludedTarget> {
    match schema.objects.get(object) {
        None => std::collections::BTreeMap::<types::FieldId, types::IncludedTarget>::new(),
        Some(def) => section.include.iter().fold(
            std::collections::BTreeMap::<types::FieldId, types::IncludedTarget>::new(),
            |out, f| match def.fields.get(f) {
                None => out.clone(),
                Some(fd) => match ref_target(&fd.ty) {
                    None => out.clone(),
                    Some(target) => {
                        let mut map_ = out.clone();
                        map_.insert(
                            f.clone(),
                            types::IncludedTarget {
                                object: target.clone(),
                                ids: id_set(
                                    &rows.iter().fold(Vec::<types::RecordId>::new(), |ids, r| {
                                        support::concat(&ids, &refs_in(&field_value(r, f)))
                                    }),
                                ),
                            },
                        );
                        map_
                    }
                },
            },
        ),
    }
}

/// crates/backend/src/ops.rs view, depends_on: the object types whose changes can alter a view, every record of which it loads: the object type of each section's query (a section of an unknown query adds nothing) and the target of each of its included reference fields.
///
/// Specification function `view-needs`.
pub fn view_needs(
    schema: &types::TenantSchema,
    view: &types::ViewDef,
) -> std::collections::BTreeSet<types::ObjectTypeId> {
    let found =
        view.sections
            .values()
            .fold(Vec::<types::ObjectTypeId>::new(), |acc, s| {
                match schema.queries.get(&s.query) {
                    None => acc.clone(),
                    Some(q) => {
                        support::concat(
                            &support::concat(&acc, &[q.object.clone()]),
                            &(match schema.objects.get(&q.object) {
                                None => Vec::<types::ObjectTypeId>::new(),
                                Some(o) => s.include.iter().fold(
                                    Vec::<types::ObjectTypeId>::new(),
                                    |xs, f| match o.fields.get(f) {
                                        None => xs.clone(),
                                        Some(fd) => match ref_target(&fd.ty) {
                                            Some(target) => support::concat(&xs, &[target.clone()]),
                                            None => xs.clone(),
                                        },
                                    },
                                ),
                            }),
                        )
                    }
                }
            });
    support::sorted_by(found.iter(), |o| o.clone().0)
        .iter()
        .fold(Vec::<types::ObjectTypeId>::new(), |acc, o| {
            if acc.iter().any(|a| *a == *o) {
                acc.clone()
            } else {
                support::concat(&acc, &[o.clone()])
            }
        })
        .into_iter()
        .collect::<std::collections::BTreeSet<_>>()
}

/// crates/backend/src/ops.rs without_others_authorship (WG-4918): who created a record is told only to its creator; anyone else gets the record without created_by.
///
/// Specification function `without-others-authorship`.
pub fn without_others_authorship(principal: &types::Principal, r: &types::Record) -> types::Record {
    let own = match principal {
        types::Principal::User(id) => r.created_by.as_ref() == Some(id),
        _ => false,
    };
    if own || r.created_by.is_none() {
        r.clone()
    } else {
        types::Record {
            id: r.id.clone(),
            object: r.object.clone(),
            version: r.version,
            created_by: None,
            created_at: r.created_at,
            updated_at: r.updated_at,
            fields: r.fields.clone(),
        }
    }
}

/// backend ops.rs view, one read of the kernel (kernel-read): a rejection is answered as the error body (api-error-of); InsufficientState naming a need asks for it.
///
/// Specification function `view-read`; fails with `api-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn view_read(
    state: &types::State,
    request: &types::ReadRequest,
    context: &types::Context,
) -> Result<types::ReadResult, Failure<types::ApiFailure>> {
    Ok(
        match match kernel_read(state, request, context) {
            Ok(value_) => Ok(value_),
            Err(Failure::Error(error_)) => Err(error_),
            Err(Failure::Fault(fault_)) => return Err(Failure::Fault(fault_)),
        } {
            Ok(r) => r.clone(),
            Err(e) => match &e {
                types::Rejection::Rejected(d) => match &d.missing {
                    Some(n) => {
                        if d.kind == types::ErrorKind::InsufficientState {
                            return Err(Failure::Error(types::ApiFailure::InsufficientState(
                                n.clone(),
                            )));
                        } else {
                            return Err(Failure::Error(types::ApiFailure::Refused(api_error_of(
                                d, context,
                            ))));
                        }
                    }
                    None => {
                        return Err(Failure::Error(types::ApiFailure::Refused(api_error_of(
                            d, context,
                        ))));
                    }
                },
            },
        },
    )
}

/// crates/backend/src/ops.rs view, one section: its named read (section-request), then for each included field the records it names that the principal may read (included-refs, a records read). The rows and included records sent lose another principal's authorship (without-others-authorship); a single section's first row, authorship included, is kept for the sections that read it.
///
/// Specification function `view-section-step`; fails with `api-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn view_section_step(
    tenant: &types::TenantState,
    state: &types::State,
    context: &types::Context,
    route: &std::collections::BTreeMap<String, String>,
    request: &std::collections::BTreeMap<String, String>,
    name: &String,
    section: &types::ViewSection,
    acc: &types::ViewProgress,
) -> Result<types::ViewProgress, Failure<types::ApiFailure>> {
    let result = view_read(
        state,
        &section_request(section, route, request, &acc.done).map_err(Failure::Fault)?,
        context,
    )?;
    let refs = match tenant.schema.queries.get(&section.query) {
        Some(q) => included_refs(
            std::sync::Arc::as_ref(&tenant.schema),
            &q.object,
            section,
            &result
                .rows
                .clone()
                .into_iter()
                .map(|item_| <types::Record as Clone>::clone(&item_))
                .collect::<Vec<_>>(),
        ),
        None => std::collections::BTreeMap::<types::FieldId, types::IncludedTarget>::new(),
    };
    let included = {
        let mut m: std::collections::BTreeMap<
            types::FieldId,
            std::collections::BTreeMap<types::RecordId, types::Record>,
        > = std::collections::BTreeMap::<
            types::FieldId,
            std::collections::BTreeMap<types::RecordId, types::Record>,
        >::new();
        for f in refs.keys() {
            m = match refs.get(f) {
                None => m.clone(),
                Some(tg) => {
                    let mut map_ = m.clone();
                    map_.insert(
                        f.clone(),
                        view_read(
                            state,
                            &types::ReadRequest::Records {
                                object: tg.object.clone(),
                                ids: tg.ids.clone(),
                            },
                            context,
                        )?
                        .rows
                        .iter()
                        .fold(
                            std::collections::BTreeMap::<types::RecordId, types::Record>::new(),
                            |rs, r| {
                                let mut map_ = rs.clone();
                                map_.insert(
                                    r.id.clone(),
                                    without_others_authorship(
                                        &context.principal,
                                        std::sync::Arc::as_ref(r),
                                    ),
                                );
                                map_
                            },
                        ),
                    );
                    map_
                }
            };
        }
        m
    };
    Ok(types::ViewProgress {
        done: if section.single {
            {
                let mut map_ = acc.done.clone();
                map_.insert(
                    name.clone(),
                    result
                        .rows
                        .get(0)
                        .cloned()
                        .map(|item_| <types::Record as Clone>::clone(&item_)),
                );
                map_
            }
        } else {
            acc.done.clone()
        },
        sections: {
            let mut map_ = acc.sections.clone();
            map_.insert(
                name.clone(),
                types::SectionData {
                    single: section.single,
                    rows: result
                        .rows
                        .iter()
                        .map(|r| {
                            without_others_authorship(&context.principal, std::sync::Arc::as_ref(r))
                        })
                        .collect::<Vec<_>>(),
                    included: included.clone(),
                    markdown: section.markdown.clone(),
                    aggregate: None,
                },
            );
            map_
        },
        revision: result.revision.clone(),
    })
}

/// crates/backend/src/ops.rs view, the decide of contract read-view (CT-264): the tenant (not_found "no site <tenant>"), the view whose route matches the path (match-route; not_found "nothing at <path>"), every record of the object types it depends on (view-needs) asked for first, then each section in evaluation order (section-order, view-section-step) read from the one snapshot. segments and routes are the path and the routes split (stand-ins of WG-4957).
///
/// Specification function `assemble-view`; fails with `api-failure` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn assemble_view(
    path: &String,
    request: &std::collections::BTreeMap<String, String>,
    context: &types::Context,
    state: &types::State,
    segments: &Vec<String>,
    routes: &std::collections::BTreeMap<types::ViewId, Vec<types::RouteSegment>>,
) -> Result<types::ViewData, Failure<types::ApiFailure>> {
    let site = match &state.tenant {
        Some(t) => t.clone(),
        None => {
            return Err(Failure::Error(types::ApiFailure::Refused(
                types::ApiError {
                    code: types::ErrorCode::NotFound,
                    message: format!("no site {}", context.tenant.0),
                    kind: None,
                    failed: Some(Vec::<types::Check>::new()),
                    correlation: context.correlation.clone(),
                },
            )));
        }
    };
    let found = match match_route(std::sync::Arc::as_ref(&site.schema), segments, routes)
        .map_err(Failure::Fault)?
    {
        Some(m) => m.clone(),
        None => {
            return Err(Failure::Error(types::ApiFailure::Refused(
                types::ApiError {
                    code: types::ErrorCode::NotFound,
                    message: format!("nothing at {path}"),
                    kind: None,
                    failed: Some(Vec::<types::Check>::new()),
                    correlation: context.correlation.clone(),
                },
            )));
        }
    };
    let depends = view_needs(std::sync::Arc::as_ref(&site.schema), &found.view);
    let progress = match first_missing(
        &state.coverage,
        &depends
            .iter()
            .map(|o| types::Need::AllOf(o.clone()))
            .collect::<Vec<_>>(),
    ) {
        Some(n) => {
            return Err(Failure::Error(types::ApiFailure::InsufficientState(
                n.clone(),
            )));
        }
        None => {
            let mut acc: types::ViewProgress = types::ViewProgress {
                done: std::collections::BTreeMap::<String, Option<types::Record>>::new(),
                sections: std::collections::BTreeMap::<String, types::SectionData>::new(),
                revision: site.revision.clone(),
            };
            for name in section_order(&found.view).iter() {
                acc = match found.view.sections.get(name) {
                    None => acc.clone(),
                    Some(s) => view_section_step(
                        std::sync::Arc::as_ref(&site),
                        state,
                        context,
                        &found.params,
                        request,
                        name,
                        s,
                        &acc,
                    )?,
                };
            }
            acc
        }
    };
    Ok(types::ViewData {
        view: found.view.id.clone(),
        title: found.view.title.clone(),
        params: found.params.clone(),
        sections: progress.sections.clone(),
        people: None,
        depends_on: depends.clone(),
        revision: progress.revision.clone(),
        schema_version: site.schema.version.clone(),
    })
}

/// serde_json json!(i64): a negative integer is a NegInt, any other a PosInt.
///
/// Specification function `json-int`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn json_int(i: i64) -> Result<types::PlainJson, Fault> {
    Ok(if i < 0 {
        types::PlainJson::Number(types::JsonNumber::NegInt(i))
    } else {
        types::PlainJson::Number(types::JsonNumber::PosInt(
            u64::try_from(i).map_err(|_| Fault { op: "as" })?,
        ))
    })
}

/// substrate plain.rs to_plain of a value that is not a list (a list of lists, which schema-problems refuse, is null here). none is the JSON null, which a body cannot write yet (the keyword-named variant gap of WG-4957): callers pass null.
///
/// Specification function `to-plain-leaf`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn to_plain_leaf(x: &types::Value, none: &types::PlainJson) -> Result<types::PlainJson, Fault> {
    Ok(match x {
        types::Value::Bool(b) => types::PlainJson::Bool(*b),
        types::Value::Int(i) => json_int(*i)?,
        types::Value::Str(s) => types::PlainJson::String(s.clone()),
        types::Value::Time(t) => json_int(*t)?,
        types::Value::Ref(r) => types::PlainJson::Number(types::JsonNumber::PosInt(r.clone().0)),
        _ => none.clone(),
    })
}

/// crates/substrate/src/plain.rs to_plain: a value as plain JSON (a reference and a time as their numbers, a list item by item). none is the JSON null (see to-plain-leaf).
///
/// Specification function `to-plain`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn to_plain(x: &types::Value, none: &types::PlainJson) -> Result<types::PlainJson, Fault> {
    Ok(match x {
        types::Value::List(items) => types::PlainJson::Array({
            let mut out_ = Vec::new();
            for i in items.iter() {
                out_.push(to_plain_leaf(i, none)?);
            }
            out_
        }),
        _ => to_plain_leaf(x, none)?,
    })
}

/// crates/substrate/src/project.rs project_record: a record as the object id, object, version, created_at, updated_at, created_by (null when not told) and fields (to-plain). none is the JSON null (see to-plain-leaf).
///
/// Specification function `project-record`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn project_record(
    r: &types::Record,
    none: &types::PlainJson,
) -> Result<std::collections::BTreeMap<String, types::PlainJson>, Fault> {
    Ok({
        let mut map_ = {
            let mut map_ = {
                let mut map_ = {
                    let mut map_ = {
                        let mut map_ = {
                            let mut map_ = {
                                let mut map_ =
                                    std::collections::BTreeMap::<String, types::PlainJson>::new();
                                map_.insert(
                                    "id".to_string(),
                                    types::PlainJson::Number(types::JsonNumber::PosInt(
                                        r.id.clone().0,
                                    )),
                                );
                                map_
                            };
                            map_.insert(
                                "object".to_string(),
                                types::PlainJson::String(r.object.clone().0),
                            );
                            map_
                        };
                        map_.insert(
                            "version".to_string(),
                            types::PlainJson::Number(types::JsonNumber::PosInt(r.version)),
                        );
                        map_
                    };
                    map_.insert("created_at".to_string(), json_int(r.created_at.0)?);
                    map_
                };
                map_.insert("updated_at".to_string(), json_int(r.updated_at.0)?);
                map_
            };
            map_.insert(
                "created_by".to_string(),
                match &r.created_by {
                    Some(p) => types::PlainJson::String(p.clone().0),
                    None => none.clone(),
                },
            );
            map_
        };
        map_.insert(
            "fields".to_string(),
            types::PlainJson::Object(
                ({
                    let mut m: std::collections::BTreeMap<types::FieldId, types::PlainJson> =
                        std::collections::BTreeMap::<types::FieldId, types::PlainJson>::new();
                    for k in r.fields.keys() {
                        m = match r.fields.get(k) {
                            Some(x) => {
                                let mut map_ = m.clone();
                                map_.insert(k.clone(), to_plain(x, none)?);
                                map_
                            }
                            None => m.clone(),
                        };
                    }
                    m
                })
                .into_iter()
                .map(|(key_, item_)| (key_.0, item_))
                .collect::<std::collections::BTreeMap<_, _>>(),
            ),
        );
        map_
    })
}

/// crates/substrate/src/project.rs project_row (lines 211-212): reading time at 230 words a minute, rounded up, never less than one minute.
///
/// Specification function `reading-minutes`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn reading_minutes(words: u64) -> Result<u64, Fault> {
    Ok(if words == 0 {
        1
    } else {
        words
            .checked_add(229)
            .ok_or(Fault { op: "+" })?
            .checked_div(230)
            .ok_or(Fault { op: "/" })?
    })
}

/// crates/substrate/src/project.rs project_row: the record (project-record) with refs, each included field's referenced record projected (null when not included; a list keeps the included ones), and, when the section names markdown fields, the blocks of each string one and reading_minutes over their words. markdown holds the parsed blocks and word count of each Markdown source (markdown.rs parse and word_count, a stand-in until the function language has string operations, WG-4957); a source it does not hold is left out. none is the JSON null (see to-plain-leaf).
///
/// Specification function `project-row`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn project_row(
    r: &types::Record,
    section: &types::SectionData,
    markdown: &std::collections::BTreeMap<String, types::MarkdownSummary>,
    none: &types::PlainJson,
) -> Result<types::PlainJson, Fault> {
    let base = project_record(r, none)?;
    let refs = {
        let mut m: std::collections::BTreeMap<types::FieldId, types::PlainJson> =
            std::collections::BTreeMap::<types::FieldId, types::PlainJson>::new();
        for f in section.included.keys() {
            m = match section.included.get(f) {
                None => m.clone(),
                Some(inc) => match field_value(r, f) {
                    types::Value::Ref(id) => {
                        let mut map_ = m.clone();
                        map_.insert(
                            f.clone(),
                            match inc.get(&id) {
                                Some(t) => types::PlainJson::Object(project_record(t, none)?),
                                None => none.clone(),
                            },
                        );
                        map_
                    }
                    types::Value::List(items) => {
                        let mut map_ = m.clone();
                        map_.insert(
                            f.clone(),
                            types::PlainJson::Array({
                                let mut xs: Vec<types::PlainJson> = Vec::<types::PlainJson>::new();
                                for i in items.iter() {
                                    xs = match i {
                                        types::Value::Ref(id) => match inc.get(id) {
                                            Some(t) => support::concat(
                                                &xs,
                                                &[types::PlainJson::Object(project_record(
                                                    t, none,
                                                )?)],
                                            ),
                                            None => xs.clone(),
                                        },
                                        _ => xs.clone(),
                                    };
                                }
                                xs
                            }),
                        );
                        map_
                    }
                    _ => m.clone(),
                },
            };
        }
        m
    };
    let summary = {
        let mut acc: types::MarkdownFold = types::MarkdownFold {
            blocks: std::collections::BTreeMap::<String, types::PlainJson>::new(),
            words: 0,
        };
        for f in section.markdown.iter() {
            acc = match field_value(r, f) {
                types::Value::Str(source) => match markdown.get(&source) {
                    Some(md) => types::MarkdownFold {
                        blocks: {
                            let mut map_ = acc.blocks.clone();
                            map_.insert(f.clone().0, md.blocks.clone());
                            map_
                        },
                        words: acc.words.checked_add(md.words).ok_or(Fault { op: "+" })?,
                    },
                    None => acc.clone(),
                },
                _ => acc.clone(),
            };
        }
        acc
    };
    Ok(types::PlainJson::Object(if section.markdown.is_empty() {
        {
            let mut map_ = base.clone();
            map_.insert(
                "refs".to_string(),
                types::PlainJson::Object(
                    refs.clone()
                        .into_iter()
                        .map(|(key_, item_)| (key_.0, item_))
                        .collect::<std::collections::BTreeMap<_, _>>(),
                ),
            );
            map_
        }
    } else {
        {
            let mut map_ = {
                let mut map_ = {
                    let mut map_ = base.clone();
                    map_.insert(
                        "refs".to_string(),
                        types::PlainJson::Object(
                            refs.clone()
                                .into_iter()
                                .map(|(key_, item_)| (key_.0, item_))
                                .collect::<std::collections::BTreeMap<_, _>>(),
                        ),
                    );
                    map_
                };
                map_.insert(
                    "blocks".to_string(),
                    types::PlainJson::Object(summary.blocks.clone()),
                );
                map_
            };
            map_.insert(
                "reading_minutes".to_string(),
                json_int(
                    i64::try_from(reading_minutes(summary.words)?)
                        .map_err(|_| Fault { op: "as" })?,
                )?,
            );
            map_
        }
    }))
}

/// crates/substrate/src/project.rs project: raw view data as the plain view model the browser renders: view, title, params, data (a single section one row or null, any other an array of rows, project-row), depends_on, revision and schema_version. The BFF adds the path and the publication template's fields (theme and the desk's, WG-4942). none is the JSON null (see to-plain-leaf).
///
/// Specification function `project-view`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn project_view(
    data: &types::ViewData,
    markdown: &std::collections::BTreeMap<String, types::MarkdownSummary>,
    none: &types::PlainJson,
) -> Result<types::PlainJson, Fault> {
    Ok(types::PlainJson::Object({
        let mut map_ = {
            let mut map_ = {
                let mut map_ = {
                    let mut map_ = {
                        let mut map_ = {
                            let mut map_ = {
                                let mut map_ =
                                    std::collections::BTreeMap::<String, types::PlainJson>::new();
                                map_.insert(
                                    "view".to_string(),
                                    types::PlainJson::String(data.view.clone().0),
                                );
                                map_
                            };
                            map_.insert(
                                "title".to_string(),
                                types::PlainJson::String(data.title.clone()),
                            );
                            map_
                        };
                        map_.insert(
                            "params".to_string(),
                            types::PlainJson::Object(data.params.keys().fold(
                                std::collections::BTreeMap::<String, types::PlainJson>::new(),
                                |m, k| match data.params.get(k) {
                                    Some(x) => {
                                        let mut map_ = m.clone();
                                        map_.insert(k.clone(), types::PlainJson::String(x.clone()));
                                        map_
                                    }
                                    None => m.clone(),
                                },
                            )),
                        );
                        map_
                    };
                    map_.insert(
                        "data".to_string(),
                        types::PlainJson::Object({
                            let mut m: std::collections::BTreeMap<String, types::PlainJson> =
                                std::collections::BTreeMap::<String, types::PlainJson>::new();
                            for k in data.sections.keys() {
                                m = match data.sections.get(k) {
                                    None => m.clone(),
                                    Some(s) => {
                                        let mut map_ = m.clone();
                                        map_.insert(
                                            k.clone(),
                                            if s.single {
                                                match s.rows.get(0) {
                                                    Some(r) => project_row(r, s, markdown, none)?,
                                                    None => none.clone(),
                                                }
                                            } else {
                                                types::PlainJson::Array({
                                                    let mut out_ = Vec::new();
                                                    for r in s.rows.iter() {
                                                        out_.push(project_row(
                                                            r, s, markdown, none,
                                                        )?);
                                                    }
                                                    out_
                                                })
                                            },
                                        );
                                        map_
                                    }
                                };
                            }
                            m
                        }),
                    );
                    map_
                };
                map_.insert(
                    "depends_on".to_string(),
                    types::PlainJson::Array(
                        data.depends_on
                            .iter()
                            .map(|o| types::PlainJson::String(o.clone().0))
                            .collect::<Vec<_>>(),
                    ),
                );
                map_
            };
            map_.insert(
                "revision".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(data.revision.clone().0)),
            );
            map_
        };
        map_.insert(
            "schema_version".to_string(),
            types::PlainJson::Number(types::JsonNumber::PosInt(data.schema_version.clone().0)),
        );
        map_
    }))
}

/// transition.rs object_def, for an intent that does action on the object type: the object type of the tenant's schema, or, when there is none, the action authorised on the object type with no record to test (require), so that a caller whom no policy could allow it gets Unauthorized whether or not the type exists, and only a caller who could learns UnknownObject.
///
/// Specification function `object-def`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn object_def(
    d: &types::Draft,
    object: &types::ObjectTypeId,
    action: &types::Action,
) -> Result<types::ObjectTypeDef, Failure<types::Rejection>> {
    let d1 = match d.tenant.schema.objects.get(object) {
        Some(_) => d.clone(),
        None => require(
            d,
            action,
            &types::Resource::Object(object.clone()),
            &types::Subject {
                old: None,
                new: None,
            },
        )?,
    };
    Ok(match d.tenant.schema.objects.get(object) {
        Some(o) => o.clone(),
        None => {
            return Err(Failure::Error(draft_reject(
                &d1.evidence,
                &types::ErrorKind::UnknownObject,
                &format!("no object type {}", object.0),
            )));
        }
    })
}

/// Rust str::to_ascii_lowercase: A to Z become a to z, every other character stays.
///
/// Specification function `ascii-lowercase`.
pub fn ascii_lowercase(s: &String) -> String {
    s.as_str()
        .chars()
        .map(String::from)
        .collect::<Vec<_>>()
        .iter()
        .fold("".to_string(), |acc, c| {
            format!(
                "{acc}{}",
                if *c == "A" {
                    "a".to_string()
                } else if *c == "B" {
                    "b".to_string()
                } else if *c == "C" {
                    "c".to_string()
                } else if *c == "D" {
                    "d".to_string()
                } else if *c == "E" {
                    "e".to_string()
                } else if *c == "F" {
                    "f".to_string()
                } else if *c == "G" {
                    "g".to_string()
                } else if *c == "H" {
                    "h".to_string()
                } else if *c == "I" {
                    "i".to_string()
                } else if *c == "J" {
                    "j".to_string()
                } else if *c == "K" {
                    "k".to_string()
                } else if *c == "L" {
                    "l".to_string()
                } else if *c == "M" {
                    "m".to_string()
                } else if *c == "N" {
                    "n".to_string()
                } else if *c == "O" {
                    "o".to_string()
                } else if *c == "P" {
                    "p".to_string()
                } else if *c == "Q" {
                    "q".to_string()
                } else if *c == "R" {
                    "r".to_string()
                } else if *c == "S" {
                    "s".to_string()
                } else if *c == "T" {
                    "t".to_string()
                } else if *c == "U" {
                    "u".to_string()
                } else if *c == "V" {
                    "v".to_string()
                } else if *c == "W" {
                    "w".to_string()
                } else if *c == "X" {
                    "x".to_string()
                } else if *c == "Y" {
                    "y".to_string()
                } else if *c == "Z" {
                    "z".to_string()
                } else {
                    c.clone()
                }
            )
        })
}

/// schema.rs normalise_address: the form in which an address is compared, trimmed and in ASCII lower case.
///
/// Specification function `normalise-address`.
pub fn normalise_address(address: &String) -> String {
    ascii_lowercase(&address.as_str().trim().to_string())
}

/// A BTreeSet<PrincipalId> as the body language holds it: the items sorted by Unicode scalar values, each once.
///
/// Specification function `principal-set-of`.
pub fn principal_set_of(
    items: &Vec<types::PrincipalId>,
) -> std::collections::BTreeSet<types::PrincipalId> {
    support::sorted_by(items.iter(), |p| p.clone().0)
        .iter()
        .fold(Vec::<types::PrincipalId>::new(), |acc, p| {
            if acc.iter().any(|a| *a == *p) {
                acc.clone()
            } else {
                support::concat(&acc, &[p.clone()])
            }
        })
        .into_iter()
        .collect::<std::collections::BTreeSet<_>>()
}

/// TenantSchema::all_teams as a map: the teams of a schema by id, none when it holds no table of teams.
///
/// Specification function `teams-of`.
pub fn teams_of(
    schema: &types::TenantSchema,
) -> std::collections::BTreeMap<types::TeamId, types::TeamDef> {
    match &schema.teams {
        Some(ts) => ts.clone(),
        None => std::collections::BTreeMap::<types::TeamId, types::TeamDef>::new(),
    }
}

/// TenantSchema::all_invitations as a map: the invitations of a schema by id, none when it holds no table of invitations.
///
/// Specification function `invitations-of`.
pub fn invitations_of(
    schema: &types::TenantSchema,
) -> std::collections::BTreeMap<types::InvitationId, types::InvitationDef> {
    match &schema.invitations {
        Some(xs) => xs.clone(),
        None => std::collections::BTreeMap::<types::InvitationId, types::InvitationDef>::new(),
    }
}

/// rules.rs assigned_roles: the roles a person holds through the table of members and the teams of a schema: those assigned to it directly and those of each team it belongs to, and no other.
///
/// Specification function `assigned-roles`.
pub fn assigned_roles(
    members: &std::collections::BTreeMap<
        types::PrincipalId,
        std::collections::BTreeSet<types::RoleId>,
    >,
    schema: &types::TenantSchema,
    id: &types::PrincipalId,
) -> std::collections::BTreeSet<types::RoleId> {
    let direct = match members.get(id) {
        Some(rs) => rs.clone(),
        None => std::collections::BTreeSet::<types::RoleId>::new(),
    };
    set_of(&teams_of(schema).values().fold(
        direct.clone().into_iter().collect::<Vec<_>>(),
        |acc, t| {
            if t.members.iter().any(|m| *m == *id) {
                support::concat(&acc, &t.roles.clone().into_iter().collect::<Vec<_>>())
            } else {
                acc.clone()
            }
        },
    ))
}

/// The order of strata_kernel::Grant as a text key: a capability before an object grant, capabilities by name, object grants by object type and then by ObjectAction in its declared order.
///
/// Specification function `grant-key`.
pub fn grant_key(g: &types::Grant) -> String {
    match g {
        types::Grant::Capability(name) => format!("0{name}"),
        types::Grant::Object(object, action) => {
            format!(
                "1{} {}",
                object.0,
                match action {
                    types::ObjectAction::Read => "0".to_string(),
                    types::ObjectAction::Create => "1".to_string(),
                    types::ObjectAction::Update => "2".to_string(),
                    types::ObjectAction::Delete => "3".to_string(),
                }
            )
        }
    }
}

/// A BTreeSet<Grant> as the body language holds it: the grants in the kernel order (grant-key), each once.
///
/// Specification function `grant-set`.
pub fn grant_set(items: &Vec<types::Grant>) -> Vec<types::Grant> {
    support::sorted_by(items.iter(), |g| grant_key(g))
        .iter()
        .fold(Vec::<types::Grant>::new(), |acc, g| {
            if acc.iter().any(|x| *x == *g) {
                acc.clone()
            } else {
                support::concat(&acc, &[g.clone()])
            }
        })
}

/// schema.rs TenantSchemaExt::grants_of: every grant of a role, from its permissions (PermissionExt::grants); a role without permissions grants none.
///
/// Specification function `grants-of`.
pub fn grants_of(schema: &types::TenantSchema, role: &types::RoleId) -> Vec<types::Grant> {
    let permissions = match &schema.role_permissions {
        Some(t) => match t.get(role) {
            Some(ps) => ps.clone(),
            None => Vec::<types::Permission>::new(),
        },
        None => Vec::<types::Permission>::new(),
    };
    grant_set(
        &permissions
            .iter()
            .fold(Vec::<types::Grant>::new(), |acc, p| {
                support::concat(
                    &acc,
                    &(match p {
                        types::Permission::Capability(name) => {
                            vec![types::Grant::Capability(name.clone())]
                        }
                        types::Permission::Object { object, actions } => actions
                            .iter()
                            .map(|a| types::Grant::Object(object.clone(), a.clone()))
                            .collect::<Vec<_>>(),
                    }),
                )
            }),
    )
}

/// rules.rs effective_permissions (ADM-151): the union of the grants of every role in roles-of, directly or through a team. The owner holds every permission, which may-confer decides, not this.
///
/// Specification function `effective-permissions`.
pub fn effective_permissions(
    tenant: &types::TenantState,
    principal: &types::Principal,
) -> Vec<types::Grant> {
    grant_set(
        &roles_of(tenant, principal)
            .iter()
            .fold(Vec::<types::Grant>::new(), |acc, r| {
                support::concat(&acc, &grants_of(std::sync::Arc::as_ref(&tenant.schema), r))
            }),
    )
}

/// rules.rs describe_grant: a grant as a sentence fragment, capability <name> or <object>:<verb>.
///
/// Specification function `grant-text`.
pub fn grant_text(g: &types::Grant) -> String {
    match g {
        types::Grant::Capability(name) => format!("capability {name}"),
        types::Grant::Object(object, action) => {
            format!(
                "{}:{}",
                object.0,
                match action {
                    types::ObjectAction::Read => "read".to_string(),
                    types::ObjectAction::Create => "create".to_string(),
                    types::ObjectAction::Update => "update".to_string(),
                    types::ObjectAction::Delete => "delete".to_string(),
                }
            )
        }
    }
}

/// rules.rs may_confer (ADM-152, ADM-1080): whether a principal may confer a role, which it may only when it holds every permission and capability the role grants, whether through its permissions or through a policy of the schema (a policy grants one power per action it names: holds-policy-power). A role that grants nothing, by permissions or policies, may be conferred, except owner, which only an owner confers. The check names the rule and the role; a refusal names what the principal lacks, the permissions first and then the policy powers. Taking a role away asks the same.
///
/// Specification function `may-confer`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn may_confer(
    tenant: &types::TenantState,
    principal: &types::Principal,
    role: &types::RoleId,
) -> Result<types::Check, Fault> {
    let rule = format!("permission:confer:{}", role.0);
    let owner = roles_of(tenant, principal).iter().any(|r| r.0 == "owner");
    let grants = grants_of(std::sync::Arc::as_ref(&tenant.schema), role);
    let held = effective_permissions(tenant, principal);
    let missing = if owner {
        Vec::<types::Grant>::new()
    } else {
        grants
            .iter()
            .filter(|&g| !held.iter().any(|h| *h == *g))
            .cloned()
            .collect::<Vec<_>>()
    };
    let powers = tenant
        .schema
        .policies
        .values()
        .fold(Vec::<String>::new(), |acc, p| {
            if p.role != *role {
                acc.clone()
            } else {
                support::concat(
                    &acc,
                    &p.actions
                        .iter()
                        .map(|a| {
                            if holds_policy_power(tenant, principal, a, &p.resource, &p.condition) {
                                "".to_string()
                            } else {
                                format!(
                                    "policy {}: {} on {}",
                                    p.id.0,
                                    action_debug(a),
                                    resource_debug(&p.resource)
                                )
                            }
                        })
                        .collect::<Vec<_>>(),
                )
            }
        });
    let lacking = support::concat(
        &missing.iter().map(|g| grant_text(g)).collect::<Vec<_>>(),
        &powers
            .iter()
            .filter(|&s| *s != "")
            .cloned()
            .collect::<Vec<_>>(),
    );
    Ok(if role.0 == "owner" {
        if owner {
            types::Check {
                rule: rule.clone(),
                passed: true,
                detail: "an owner confers owner".to_string(),
            }
        } else {
            types::Check {
                rule: rule.clone(),
                passed: false,
                detail: "only an owner confers the owner role".to_string(),
            }
        }
    } else if grants.is_empty() && powers.is_empty() {
        types::Check {
            rule: rule.clone(),
            passed: true,
            detail: format!("role {} grants no permission", role.0),
        }
    } else if lacking.is_empty() {
        types::Check {
            rule: rule.clone(),
            passed: true,
            detail: format!("holds every permission that role {} grants", role.0),
        }
    } else {
        types::Check {
            rule: rule.clone(),
            passed: false,
            detail: format!(
                "lacks {} of the {} permissions that role {} grants: {}",
                u64::try_from(lacking.len()).unwrap_or(u64::MAX),
                u64::try_from(grants.len())
                    .unwrap_or(u64::MAX)
                    .checked_add(u64::try_from(powers.len()).unwrap_or(u64::MAX))
                    .ok_or(Fault { op: "+" })?,
                role.0,
                lacking.iter().fold("".to_string(), |acc, s| if acc == "" {
                    s.clone()
                } else {
                    format!("{}{s}", format!("{acc}, "))
                })
            ),
        }
    })
}

/// transition.rs require_conferrable (ADM-152): every role must be one the acting principal may confer (may-confer). Each check is evidence, in the order of the roles; the first role it may not confer refuses the intent as Unauthorized.
///
/// Specification function `require-conferrable`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn require_conferrable(
    d: &types::Draft,
    roles: &Vec<types::RoleId>,
) -> Result<types::Draft, Failure<types::Rejection>> {
    let added = {
        let mut acc: Vec<types::Check> = Vec::<types::Check>::new();
        for r in roles.iter() {
            acc = if acc.iter().any(|c| !c.passed) {
                acc.clone()
            } else {
                support::concat(
                    &acc,
                    &[may_confer(&d.tenant, &d.ctx.principal, r).map_err(Failure::Fault)?],
                )
            };
        }
        acc
    };
    let evidence = support::concat(&d.evidence, &added);
    let refused = {
        let mut found_ = None;
        for r in roles.iter() {
            if !may_confer(&d.tenant, &d.ctx.principal, r)
                .map_err(Failure::Fault)?
                .passed
            {
                found_ = Some(r.clone());
                break;
            }
        }
        found_
    };
    Ok(match &refused {
        Some(r) => {
            return Err(Failure::Error(draft_reject(
                &evidence,
                &types::ErrorKind::Unauthorized,
                &format!(
                    "may not confer role {}: {}",
                    r.0,
                    may_confer(&d.tenant, &d.ctx.principal, r)
                        .map_err(Failure::Fault)?
                        .detail
                ),
            )));
        }
        None => types::Draft {
            tenant: d.tenant.clone(),
            ctx: d.ctx.clone(),
            coverage: d.coverage.clone(),
            ops: d.ops.clone(),
            events: d.events.clone(),
            effects: d.effects.clone(),
            evidence: evidence.clone(),
            next_record: d.next_record,
        },
    })
}

/// transition.rs team_principal: the id under which a team appears in events, team:<id>; a team is assigned roles like a principal.
///
/// Specification function `team-principal`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn team_principal(team: &types::TeamId) -> Result<types::PrincipalId, Fault> {
    Ok(types::PrincipalId::new(format!("team:{}", team.0)).map_err(|_| Fault { op: "new" })?)
}

/// TenantSchemaExt::put_team: the schema with a team defined or replaced. A team changes through its own intents, not ChangeSchema, and does not raise the schema version.
///
/// Specification function `schema-with-team`.
pub fn schema_with_team(
    schema: &types::TenantSchema,
    team: &types::TeamDef,
) -> types::TenantSchema {
    types::TenantSchema {
        version: schema.version.clone(),
        objects: schema.objects.clone(),
        roles: schema.roles.clone(),
        role_permissions: schema.role_permissions.clone(),
        teams: Some({
            let mut map_ = teams_of(schema);
            map_.insert(team.id.clone(), team.clone());
            map_
        }),
        invitations: schema.invitations.clone(),
        policies: schema.policies.clone(),
        workflows: schema.workflows.clone(),
        queries: schema.queries.clone(),
        views: schema.views.clone(),
        triggers: schema.triggers.clone(),
        automations: schema.automations.clone(),
        operations: schema.operations.clone(),
        settings: schema.settings.clone(),
        capabilities: schema.capabilities.clone(),
        ledger: schema.ledger.clone(),
        mail_templates: schema.mail_templates.clone(),
        notice_templates: schema.notice_templates.clone(),
        tokens: schema.tokens.clone(),
        products: schema.products.clone(),
        ui: schema.ui.clone(),
    }
}

/// TenantSchemaExt::put_invitation: the schema with an invitation recorded or replaced.
///
/// Specification function `schema-with-invitation`.
pub fn schema_with_invitation(
    schema: &types::TenantSchema,
    invitation: &types::InvitationDef,
) -> types::TenantSchema {
    types::TenantSchema {
        version: schema.version.clone(),
        objects: schema.objects.clone(),
        roles: schema.roles.clone(),
        role_permissions: schema.role_permissions.clone(),
        teams: schema.teams.clone(),
        invitations: Some({
            let mut map_ = invitations_of(schema);
            map_.insert(invitation.id.clone(), invitation.clone());
            map_
        }),
        policies: schema.policies.clone(),
        workflows: schema.workflows.clone(),
        queries: schema.queries.clone(),
        views: schema.views.clone(),
        triggers: schema.triggers.clone(),
        automations: schema.automations.clone(),
        operations: schema.operations.clone(),
        settings: schema.settings.clone(),
        capabilities: schema.capabilities.clone(),
        ledger: schema.ledger.clone(),
        mail_templates: schema.mail_templates.clone(),
        notice_templates: schema.notice_templates.clone(),
        tokens: schema.tokens.clone(),
        products: schema.products.clone(),
        ui: schema.ui.clone(),
    }
}

/// transition.rs team_of: a team of the tenant, or InvalidIntent "no team <id>".
///
/// Specification function `team-of`; fails with `rejection`.
pub fn team_of(d: &types::Draft, team: &types::TeamId) -> Result<types::TeamDef, types::Rejection> {
    Ok(
        match teams_of(std::sync::Arc::as_ref(&d.tenant.schema)).get(team) {
            Some(t) => t.clone(),
            None => {
                return Err(draft_reject(
                    &d.evidence,
                    &types::ErrorKind::InvalidIntent,
                    &format!("no team {}", team.0),
                ));
            }
        },
    )
}

/// transition.rs put_team: record a changed team: an event for the team (team-principal), the schema with the team, and an event for each of its members with the roles it now holds (assigned-roles).
///
/// Specification function `put-team`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn put_team(
    d: &types::Draft,
    schema: &types::TenantSchema,
    team: &types::TeamDef,
) -> Result<types::Draft, Fault> {
    let after = schema_with_team(schema, team);
    Ok(types::Draft {
        tenant: d.tenant.clone(),
        ctx: d.ctx.clone(),
        coverage: d.coverage.clone(),
        ops: support::concat(
            &d.ops,
            &[types::DeltaOp::PutSchema(std::sync::Arc::new(
                after.clone(),
            ))],
        ),
        events: support::concat(
            &support::concat(
                &d.events,
                &[types::EventBody::MemberChanged {
                    principal: team_principal(&team.id)?,
                    roles: team.roles.clone(),
                }],
            ),
            &team
                .members
                .iter()
                .map(|m| types::EventBody::MemberChanged {
                    principal: m.clone(),
                    roles: assigned_roles(&d.tenant.members, &after, m),
                })
                .collect::<Vec<_>>(),
        ),
        effects: d.effects.clone(),
        evidence: d.evidence.clone(),
        next_record: d.next_record,
    })
}

/// transition.rs define_team: define a team, or relabel one and keep its members and roles. Managing members is authorised (Manage on Members); a blank label is InvalidIntent.
///
/// Specification function `define-team`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn define_team(
    d: &types::Draft,
    team: &types::TeamId,
    label: &String,
) -> Result<types::Decided, Failure<types::Rejection>> {
    let d1 = require(
        d,
        &types::Action::Manage,
        &types::Resource::Members,
        &types::Subject {
            old: None,
            new: None,
        },
    )?;
    Ok(if label.as_str().trim().to_string() == "" {
        return Err(Failure::Error(draft_reject(
            &d1.evidence,
            &types::ErrorKind::InvalidIntent,
            &"a team needs a label".to_string(),
        )));
    } else {
        types::Decided {
            draft: put_team(
                &d1,
                std::sync::Arc::as_ref(&d1.tenant.schema),
                &(match teams_of(std::sync::Arc::as_ref(&d1.tenant.schema)).get(team) {
                    Some(t) => types::TeamDef {
                        id: t.id.clone(),
                        label: label.clone(),
                        members: t.members.clone(),
                        roles: t.roles.clone(),
                    },
                    None => types::TeamDef {
                        id: team.clone(),
                        label: label.clone(),
                        members: std::collections::BTreeSet::<types::PrincipalId>::new(),
                        roles: std::collections::BTreeSet::<types::RoleId>::new(),
                    },
                }),
            )
            .map_err(Failure::Fault)?,
            output: types::Output::Member,
        }
    })
}

/// transition.rs team_role: assign a role to a team or revoke it. Authorised as Manage on Members; the team must exist, the role must exist and not be public, and the role must be one the principal may confer, granted or revoked (require-conferrable). A revocation must leave the tenant an owner, counting the owners through teams (owner-lost). A member left with no role at all by a revocation has its sessions revoked.
///
/// Specification function `team-role`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn team_role(
    d: &types::Draft,
    team: &types::TeamId,
    role: &types::RoleId,
    grant: bool,
) -> Result<types::Decided, Failure<types::Rejection>> {
    let d1 = require(
        d,
        &types::Action::Manage,
        &types::Resource::Members,
        &types::Subject {
            old: None,
            new: None,
        },
    )?;
    let def0 = team_of(&d1, team).map_err(Failure::Error)?;
    Ok(if d1.tenant.schema.roles.get(role).is_none() {
        return Err(Failure::Error(draft_reject(
            &d1.evidence,
            &types::ErrorKind::UnknownRole,
            &format!("no role {}", role.0),
        )));
    } else if role.0 == "public" {
        return Err(Failure::Error(draft_reject(
            &d1.evidence,
            &types::ErrorKind::InvalidIntent,
            &"everyone already holds public".to_string(),
        )));
    } else {
        {
            let d2 = require_conferrable(&d1, &vec![role.clone()])?;
            {
                let def = types::TeamDef {
                    id: def0.id.clone(),
                    label: def0.label.clone(),
                    members: def0.members.clone(),
                    roles: (if grant {
                        set_of(&support::concat(
                            &def0.roles.clone().into_iter().collect::<Vec<_>>(),
                            &[role.clone()],
                        ))
                        .into_iter()
                        .collect::<Vec<_>>()
                    } else {
                        def0.roles
                            .iter()
                            .filter(|&r| *r != *role)
                            .cloned()
                            .collect::<Vec<_>>()
                    })
                    .into_iter()
                    .collect::<std::collections::BTreeSet<_>>(),
                };
                {
                    let after = schema_with_team(std::sync::Arc::as_ref(&d2.tenant.schema), &def);
                    {
                        let lost = if grant {
                            Vec::<types::PrincipalId>::new()
                        } else {
                            def.members
                                .iter()
                                .filter(|&m| {
                                    (match d2.tenant.members.get(m) {
                                        Some(rs) => rs.is_empty(),
                                        None => true,
                                    }) && assigned_roles(
                                        &std::collections::BTreeMap::<
                                            types::PrincipalId,
                                            std::collections::BTreeSet<types::RoleId>,
                                        >::new(),
                                        &after,
                                        m,
                                    )
                                    .is_empty()
                                })
                                .cloned()
                                .collect::<Vec<_>>()
                        };
                        if !grant
                            && owner_lost(
                                &d2.tenant.members,
                                std::sync::Arc::as_ref(&d2.tenant.schema),
                                &d2.tenant.members,
                                &after,
                            )
                        {
                            return Err(Failure::Error(draft_reject(
                                &d2.evidence,
                                &types::ErrorKind::InvalidIntent,
                                &"a tenant keeps at least one owner".to_string(),
                            )));
                        } else {
                            types::Decided {
                                draft: put_team(
                                    &types::Draft {
                                        tenant: d2.tenant.clone(),
                                        ctx: d2.ctx.clone(),
                                        coverage: d2.coverage.clone(),
                                        ops: d2.ops.clone(),
                                        events: d2.events.clone(),
                                        effects: support::concat(
                                            &d2.effects,
                                            &lost
                                                .iter()
                                                .map(|p| types::Effect::RevokeSessions {
                                                    principal: p.clone(),
                                                })
                                                .collect::<Vec<_>>(),
                                        ),
                                        evidence: d2.evidence.clone(),
                                        next_record: d2.next_record,
                                    },
                                    std::sync::Arc::as_ref(&d2.tenant.schema),
                                    &def,
                                )
                                .map_err(Failure::Fault)?,
                                output: types::Output::Member,
                            }
                        }
                    }
                }
            }
        }
    })
}

/// transition.rs team_member: add a principal to a team or remove it. Authorised as Manage on Members; every role of the team must be one the principal may confer, whether adding or removing (require-conferrable), and a removal must leave the tenant an owner, counting the owners through teams (owner-lost). A removed member gets its own event with the roles it keeps, and its sessions are revoked when it keeps none.
///
/// Specification function `team-member`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn team_member(
    d: &types::Draft,
    team: &types::TeamId,
    principal: &types::PrincipalId,
    add: bool,
) -> Result<types::Decided, Failure<types::Rejection>> {
    let d1 = require(
        d,
        &types::Action::Manage,
        &types::Resource::Members,
        &types::Subject {
            old: None,
            new: None,
        },
    )?;
    let def0 = team_of(&d1, team).map_err(Failure::Error)?;
    let d2 = require_conferrable(&d1, &def0.roles.clone().into_iter().collect::<Vec<_>>())?;
    let def = types::TeamDef {
        id: def0.id.clone(),
        label: def0.label.clone(),
        members: (if add {
            principal_set_of(&support::concat(
                &def0.members.clone().into_iter().collect::<Vec<_>>(),
                &[principal.clone()],
            ))
            .into_iter()
            .collect::<Vec<_>>()
        } else {
            def0.members
                .iter()
                .filter(|&m| *m != *principal)
                .cloned()
                .collect::<Vec<_>>()
        })
        .into_iter()
        .collect::<std::collections::BTreeSet<_>>(),
        roles: def0.roles.clone(),
    };
    let roles = assigned_roles(
        &d2.tenant.members,
        &schema_with_team(std::sync::Arc::as_ref(&d2.tenant.schema), &def),
        principal,
    );
    Ok(
        if !add
            && owner_lost(
                &d2.tenant.members,
                std::sync::Arc::as_ref(&d2.tenant.schema),
                &d2.tenant.members,
                &schema_with_team(std::sync::Arc::as_ref(&d2.tenant.schema), &def),
            )
        {
            return Err(Failure::Error(draft_reject(
                &d2.evidence,
                &types::ErrorKind::InvalidIntent,
                &"a tenant keeps at least one owner".to_string(),
            )));
        } else {
            types::Decided {
                draft: put_team(
                    &types::Draft {
                        tenant: d2.tenant.clone(),
                        ctx: d2.ctx.clone(),
                        coverage: d2.coverage.clone(),
                        ops: d2.ops.clone(),
                        events: if add {
                            d2.events.clone()
                        } else {
                            support::concat(
                                &d2.events,
                                &[types::EventBody::MemberChanged {
                                    principal: principal.clone(),
                                    roles: roles.clone(),
                                }],
                            )
                        },
                        effects: if !add && roles.is_empty() {
                            support::concat(
                                &d2.effects,
                                &[types::Effect::RevokeSessions {
                                    principal: principal.clone(),
                                }],
                            )
                        } else {
                            d2.effects.clone()
                        },
                        evidence: d2.evidence.clone(),
                        next_record: d2.next_record,
                    },
                    std::sync::Arc::as_ref(&d2.tenant.schema),
                    &def,
                )
                .map_err(Failure::Fault)?,
                output: types::Output::Member,
            }
        },
    )
}

/// transition.rs create_invitation (ADM-153): a person issues an invitation to an address for roles. Authorised as Manage on Members; the address is kept normalised (normalise-address) and must hold an @; it grants at least one role, every one existing and not public and one the person may confer; an invitation id is used once. The invitation expires fourteen days after it is issued and starts unrevoked (ADM-1082).
///
/// Specification function `create-invitation`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn create_invitation(
    d: &types::Draft,
    invitation: &types::InvitationId,
    address: &String,
    roles: &std::collections::BTreeSet<types::RoleId>,
) -> Result<types::Decided, Failure<types::Rejection>> {
    let d1 = require(
        d,
        &types::Action::Manage,
        &types::Resource::Members,
        &types::Subject {
            old: None,
            new: None,
        },
    )?;
    let addr = normalise_address(address);
    let bad = roles
        .iter()
        .find(|&r| d1.tenant.schema.roles.get(r).is_none() || r.0 == "public")
        .cloned();
    Ok(match &d1.ctx.principal {
        types::Principal::User(creator) => {
            if !addr
                .as_str()
                .chars()
                .map(String::from)
                .collect::<Vec<_>>()
                .iter()
                .any(|c| *c == "@")
            {
                return Err(Failure::Error(draft_reject(
                    &d1.evidence,
                    &types::ErrorKind::InvalidIntent,
                    &"an invitation names an address".to_string(),
                )));
            } else if roles.is_empty() {
                return Err(Failure::Error(draft_reject(
                    &d1.evidence,
                    &types::ErrorKind::InvalidIntent,
                    &"an invitation grants a role".to_string(),
                )));
            } else if invitations_of(std::sync::Arc::as_ref(&d1.tenant.schema))
                .get(invitation)
                .is_some()
            {
                return Err(Failure::Error(draft_reject(
                    &d1.evidence,
                    &types::ErrorKind::InvalidIntent,
                    &format!("invitation {} already exists", invitation.0),
                )));
            } else {
                match &bad {
                    Some(r) => {
                        if d1.tenant.schema.roles.get(r).is_none() {
                            return Err(Failure::Error(draft_reject(
                                &d1.evidence,
                                &types::ErrorKind::UnknownRole,
                                &format!("no role {}", r.0),
                            )));
                        } else {
                            return Err(Failure::Error(draft_reject(
                                &d1.evidence,
                                &types::ErrorKind::InvalidIntent,
                                &"everyone already holds public".to_string(),
                            )));
                        }
                    }
                    None => {
                        let d2 = require_conferrable(
                            &d1,
                            &roles.clone().into_iter().collect::<Vec<_>>(),
                        )?;
                        types::Decided {
                            draft: types::Draft {
                                tenant: d2.tenant.clone(),
                                ctx: d2.ctx.clone(),
                                coverage: d2.coverage.clone(),
                                ops: support::concat(
                                    &d2.ops,
                                    &[types::DeltaOp::PutSchema(std::sync::Arc::new(
                                        schema_with_invitation(
                                            std::sync::Arc::as_ref(&d2.tenant.schema),
                                            &types::InvitationDef {
                                                id: invitation.clone(),
                                                address: addr.clone(),
                                                roles: roles.clone(),
                                                created_by: creator.clone(),
                                                redeemed_by: None,
                                                expires_at: Some(crate::prelude::Timestamp(
                                                    d1.ctx
                                                        .now
                                                        .0
                                                        .checked_add(1209600000)
                                                        .ok_or(Failure::Fault(Fault { op: "+" }))?,
                                                )),
                                                revoked_by: None,
                                            },
                                        ),
                                    ))],
                                ),
                                events: d2.events.clone(),
                                effects: d2.effects.clone(),
                                evidence: d2.evidence.clone(),
                                next_record: d2.next_record,
                            },
                            output: types::Output::Member,
                        }
                    }
                }
            }
        }
        _ => {
            return Err(Failure::Error(draft_reject(
                &d1.evidence,
                &types::ErrorKind::InvalidIntent,
                &"a person issues an invitation".to_string(),
            )));
        }
    })
}

/// transition.rs redeem_invitation (ADM-153): the roles of an invitation go to the one signed-in person who redeems it with the address it names, once. The address is the one the shell verified for that person (context verified-address); the intent carries none, and a refusal for a wrong address does not say which address the invitation names. No policy is consulted for the redeemer: the invitation is the authority, and it stands only while it is unrevoked and unexpired (ADM-1082, ADM-1083) and its issuer still manages members and could confer every role it offers (ADM-1084).
///
/// Specification function `redeem-invitation-intent`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn redeem_invitation_intent(
    d: &types::Draft,
    invitation: &types::InvitationId,
) -> Result<types::Decided, Failure<types::Rejection>> {
    Ok(match &d.ctx.principal {
        types::Principal::User(redeemer) => {
            match invitations_of(std::sync::Arc::as_ref(&d.tenant.schema)).get(invitation) {
                None => {
                    return Err(Failure::Error(draft_reject(
                        &d.evidence,
                        &types::ErrorKind::InvalidIntent,
                        &format!("no invitation {}", invitation.0),
                    )));
                }
                Some(offer) => match &d.ctx.verified_address {
                    None => {
                        return Err(Failure::Error(draft_reject(
                            &support::concat(
                                &d.evidence,
                                &[types::Check {
                                    rule: "invitation:address_matches".to_string(),
                                    passed: false,
                                    detail: "the redeemer has no verified address".to_string(),
                                }],
                            ),
                            &types::ErrorKind::Unauthorized,
                            &"the invitation needs a verified address".to_string(),
                        )));
                    }
                    Some(verified) => {
                        if normalise_address(verified) != offer.address {
                            return Err(
                                        Failure::Error(
                                            draft_reject(
                                                &support::concat(
                                                    &d.evidence,
                                                    &[
                                                        types::Check {
                                                            rule: "invitation:address_matches".to_string(),
                                                            passed: false,
                                                            detail: "the redeemer's verified address is not the address the invitation names"
                                                                .to_string(),
                                                        },
                                                    ],
                                                ),
                                                &types::ErrorKind::Unauthorized,
                                                &"the invitation names another address".to_string(),
                                            ),
                                        ),
                                    );
                        } else {
                            {
                                let ev1 = support::concat(
                                    &d.evidence,
                                    &[types::Check {
                                        rule: "invitation:address_matches".to_string(),
                                        passed: true,
                                        detail:
                                            "the verified address is the one the invitation names"
                                                .to_string(),
                                    }],
                                );
                                match &offer.redeemed_by {
                                    Some(by) => {
                                        return Err(Failure::Error(draft_reject(
                                            &support::concat(
                                                &ev1,
                                                &[types::Check {
                                                    rule: "invitation:redeemed_once".to_string(),
                                                    passed: false,
                                                    detail: format!("already redeemed by {}", by.0),
                                                }],
                                            ),
                                            &types::ErrorKind::InvalidIntent,
                                            &"the invitation was already redeemed".to_string(),
                                        )));
                                    }
                                    None => {
                                        let ev2 = support::concat(
                                            &ev1,
                                            &[types::Check {
                                                rule: "invitation:redeemed_once".to_string(),
                                                passed: true,
                                                detail: "not redeemed before".to_string(),
                                            }],
                                        );
                                        match &offer.revoked_by {
                                            Some(by) => {
                                                return Err(Failure::Error(draft_reject(
                                                    &support::concat(
                                                        &ev2,
                                                        &[types::Check {
                                                            rule: "invitation:not_revoked"
                                                                .to_string(),
                                                            passed: false,
                                                            detail: format!("revoked by {}", by.0),
                                                        }],
                                                    ),
                                                    &types::ErrorKind::InvalidIntent,
                                                    &"the invitation was revoked".to_string(),
                                                )));
                                            }
                                            None => {
                                                let ev3 = support::concat(
                                                    &ev2,
                                                    &[types::Check {
                                                        rule: "invitation:not_revoked".to_string(),
                                                        passed: true,
                                                        detail: "not revoked".to_string(),
                                                    }],
                                                );
                                                {
                                                    let live = match offer.expires_at {
                                                        Some(at) => d.ctx.now.0 < at.0,
                                                        None => false,
                                                    };
                                                    if !live {
                                                        return Err(Failure::Error(draft_reject(
                                                            &support::concat(
                                                                &ev3,
                                                                &[types::Check {
                                                                    rule: "invitation:not_expired"
                                                                        .to_string(),
                                                                    passed: false,
                                                                    detail:
                                                                        "the invitation has expired"
                                                                            .to_string(),
                                                                }],
                                                            ),
                                                            &types::ErrorKind::InvalidIntent,
                                                            &"the invitation has expired"
                                                                .to_string(),
                                                        )));
                                                    } else {
                                                        {
                                                            let ev4 = support::concat(
                                                                &ev3,
                                                                &[types::Check {
                                                                    rule: "invitation:not_expired"
                                                                        .to_string(),
                                                                    passed: true,
                                                                    detail: "not expired"
                                                                        .to_string(),
                                                                }],
                                                            );
                                                            {
                                                                let issuer = types::Principal::User(
                                                                    offer.created_by.clone(),
                                                                );
                                                                if !authorize(
                                                                    &d.tenant,
                                                                    std::sync::Arc::as_ref(
                                                                        &d.tenant.schema,
                                                                    ),
                                                                    &issuer,
                                                                    d.ctx.now,
                                                                    &types::Action::Manage,
                                                                    &types::Resource::Members,
                                                                    &types::Subject {
                                                                        old: None,
                                                                        new: None,
                                                                    },
                                                                )
                                                                .map_err(Failure::Fault)?
                                                                .allowed
                                                                {
                                                                    return Err(
                                                                                Failure::Error(
                                                                                    draft_reject(
                                                                                        &support::concat(
                                                                                            &ev4,
                                                                                            &[
                                                                                                types::Check {
                                                                                                    rule: "invitation:issuer_authority".to_string(),
                                                                                                    passed: false,
                                                                                                    detail: "the issuer may no longer manage members"
                                                                                                        .to_string(),
                                                                                                },
                                                                                            ],
                                                                                        ),
                                                                                        &types::ErrorKind::Unauthorized,
                                                                                        &"the invitation's issuer no longer holds the authority to issue it"
                                                                                            .to_string(),
                                                                                    ),
                                                                                ),
                                                                            );
                                                                } else {
                                                                    match {
                                                                        let mut found_ = None;
                                                                        for r in offer.roles.iter()
                                                                        {
                                                                            if !may_confer(
                                                                                &d.tenant, &issuer,
                                                                                r,
                                                                            )
                                                                            .map_err(
                                                                                Failure::Fault,
                                                                            )?
                                                                            .passed
                                                                            {
                                                                                found_ =
                                                                                    Some(r.clone());
                                                                                break;
                                                                            }
                                                                        }
                                                                        found_
                                                                    } {
                                                                        Some(r) => {
                                                                            return Err(
                                                                                        Failure::Error(
                                                                                            draft_reject(
                                                                                                &support::concat(
                                                                                                    &ev4,
                                                                                                    &[
                                                                                                        may_confer(&d.tenant, &issuer, &r).map_err(Failure::Fault)?,
                                                                                                        types::Check {
                                                                                                            rule: "invitation:issuer_authority".to_string(),
                                                                                                            passed: false,
                                                                                                            detail: format!("the issuer may no longer confer {}", r.0),
                                                                                                        },
                                                                                                    ],
                                                                                                ),
                                                                                                &types::ErrorKind::Unauthorized,
                                                                                                &"the invitation's issuer no longer holds the authority to issue it"
                                                                                                    .to_string(),
                                                                                            ),
                                                                                        ),
                                                                                    );
                                                                        }
                                                                        None => {
                                                                            let ev5 = support::concat(
                                                                                        &ev4,
                                                                                        &[
                                                                                            types::Check {
                                                                                                rule: "invitation:issuer_authority".to_string(),
                                                                                                passed: true,
                                                                                                detail: "the issuer still holds the authority to issue it"
                                                                                                    .to_string(),
                                                                                            },
                                                                                        ],
                                                                                    );
                                                                            {
                                                                                let roles = set_of(
                                                                                            &support::concat(
                                                                                                &(match d.tenant.members.get(redeemer) {
                                                                                                    Some(rs) => rs.clone(),
                                                                                                    None => std::collections::BTreeSet::<types::RoleId>::new(),
                                                                                                })
                                                                                                    .into_iter()
                                                                                                    .collect::<Vec<_>>(),
                                                                                                &offer.roles.clone().into_iter().collect::<Vec<_>>(),
                                                                                            ),
                                                                                        );
                                                                                {
                                                                                    let schema = schema_with_invitation(
                                                                                                std::sync::Arc::as_ref(&d.tenant.schema),
                                                                                                &types::InvitationDef {
                                                                                                    id: offer.id.clone(),
                                                                                                    address: offer.address.clone(),
                                                                                                    roles: offer.roles.clone(),
                                                                                                    created_by: offer.created_by.clone(),
                                                                                                    redeemed_by: Some(redeemer.clone()),
                                                                                                    expires_at: offer.expires_at,
                                                                                                    revoked_by: offer.revoked_by.clone(),
                                                                                                },
                                                                                            );
                                                                                    types::Decided {
                                                                                                draft: types::Draft {
                                                                                                    tenant: d.tenant.clone(),
                                                                                                    ctx: d.ctx.clone(),
                                                                                                    coverage: d.coverage.clone(),
                                                                                                    ops: support::concat(
                                                                                                        &d.ops,
                                                                                                        &[
                                                                                                            types::DeltaOp::PutSchema(
                                                                                                                std::sync::Arc::new(schema.clone()),
                                                                                                            ),
                                                                                                            types::DeltaOp::PutMember {
                                                                                                                principal: redeemer.clone(),
                                                                                                                roles: roles.clone(),
                                                                                                            },
                                                                                                        ],
                                                                                                    ),
                                                                                                    events: support::concat(
                                                                                                        &d.events,
                                                                                                        &[
                                                                                                            types::EventBody::MemberChanged {
                                                                                                                principal: redeemer.clone(),
                                                                                                                roles: assigned_roles(
                                                                                                                    &({
                                                                                                                        let mut map_ = d.tenant.members.clone();
                                                                                                                        map_.insert(redeemer.clone(), roles.clone());
                                                                                                                        map_
                                                                                                                    }),
                                                                                                                    &schema,
                                                                                                                    redeemer,
                                                                                                                ),
                                                                                                            },
                                                                                                        ],
                                                                                                    ),
                                                                                                    effects: d.effects.clone(),
                                                                                                    evidence: ev5.clone(),
                                                                                                    next_record: d.next_record,
                                                                                                },
                                                                                                output: types::Output::Member,
                                                                                            }
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
            }
        }
        _ => {
            return Err(Failure::Error(draft_reject(
                &support::concat(
                    &d.evidence,
                    &[types::Check {
                        rule: "invitation:redeemer_is_person".to_string(),
                        passed: false,
                        detail: "only a signed-in person redeems an invitation".to_string(),
                    }],
                ),
                &types::ErrorKind::Unauthorized,
                &"only a signed-in person redeems an invitation".to_string(),
            )));
        }
    })
}

/// TenantSchemaExt::set_role_permissions: the table of permissions with those of one role replaced; none removes the role's entry, and a table left empty is none, as the genesis schema holds it.
///
/// Specification function `role-permissions-with`.
pub fn role_permissions_with(
    schema: &types::TenantSchema,
    role: &types::RoleId,
    permissions: &Vec<types::Permission>,
) -> Option<std::collections::BTreeMap<types::RoleId, Vec<types::Permission>>> {
    let table = match &schema.role_permissions {
        Some(t) => t.clone(),
        None => std::collections::BTreeMap::<types::RoleId, Vec<types::Permission>>::new(),
    };
    let next = if permissions.is_empty() {
        {
            let mut map_ = table.clone();
            map_.remove(role);
            map_
        }
    } else {
        {
            let mut map_ = table.clone();
            map_.insert(role.clone(), permissions.clone());
            map_
        }
    };
    if next.keys().cloned().collect::<Vec<_>>().is_empty() {
        None
    } else {
        Some(next.clone())
    }
}

/// transition.rs revoke_invitation (ADM-1083): a person withdraws an invitation that was not redeemed. Authorised as Manage on Members; the invitation must exist, be unredeemed and unrevoked, and offer only roles the person may confer (require-conferrable). The invitation stays in the schema, marked with who revoked it, and is never redeemable again.
///
/// Specification function `revoke-invitation`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn revoke_invitation(
    d: &types::Draft,
    invitation: &types::InvitationId,
) -> Result<types::Decided, Failure<types::Rejection>> {
    let d1 = require(
        d,
        &types::Action::Manage,
        &types::Resource::Members,
        &types::Subject {
            old: None,
            new: None,
        },
    )?;
    Ok(match &d1.ctx.principal {
        types::Principal::User(actor) => {
            match invitations_of(std::sync::Arc::as_ref(&d1.tenant.schema)).get(invitation) {
                None => {
                    return Err(Failure::Error(draft_reject(
                        &d1.evidence,
                        &types::ErrorKind::InvalidIntent,
                        &format!("no invitation {}", invitation.0),
                    )));
                }
                Some(offer) => match &offer.redeemed_by {
                    Some(_) => {
                        return Err(Failure::Error(draft_reject(
                            &d1.evidence,
                            &types::ErrorKind::InvalidIntent,
                            &"the invitation was already redeemed".to_string(),
                        )));
                    }
                    None => match &offer.revoked_by {
                        Some(_) => {
                            return Err(Failure::Error(draft_reject(
                                &d1.evidence,
                                &types::ErrorKind::InvalidIntent,
                                &"the invitation was already revoked".to_string(),
                            )));
                        }
                        None => {
                            let d2 = require_conferrable(
                                &d1,
                                &offer.roles.clone().into_iter().collect::<Vec<_>>(),
                            )?;
                            types::Decided {
                                draft: types::Draft {
                                    tenant: d2.tenant.clone(),
                                    ctx: d2.ctx.clone(),
                                    coverage: d2.coverage.clone(),
                                    ops: support::concat(
                                        &d2.ops,
                                        &[types::DeltaOp::PutSchema(std::sync::Arc::new(
                                            schema_with_invitation(
                                                std::sync::Arc::as_ref(&d2.tenant.schema),
                                                &types::InvitationDef {
                                                    id: offer.id.clone(),
                                                    address: offer.address.clone(),
                                                    roles: offer.roles.clone(),
                                                    created_by: offer.created_by.clone(),
                                                    redeemed_by: offer.redeemed_by.clone(),
                                                    expires_at: offer.expires_at,
                                                    revoked_by: Some(actor.clone()),
                                                },
                                            ),
                                        ))],
                                    ),
                                    events: d2.events.clone(),
                                    effects: d2.effects.clone(),
                                    evidence: d2.evidence.clone(),
                                    next_record: d2.next_record,
                                },
                                output: types::Output::Member,
                            }
                        }
                    },
                },
            }
        }
        _ => {
            return Err(Failure::Error(draft_reject(
                &d1.evidence,
                &types::ErrorKind::InvalidIntent,
                &"a person revokes an invitation".to_string(),
            )));
        }
    })
}

/// read.rs page_size, before its checks: the page size of a named query read is the one the read names, else the limit the query declares, else 50 (KRN-1285).
///
/// Specification function `query-page-size`.
pub fn query_page_size(def: &types::QueryDef, asked: Option<u32>) -> u32 {
    match asked {
        Some(n) => n,
        None => match def.limit {
            Some(l) => l,
            None => 50,
        },
    }
}

/// read.rs is_windowed: a named query is served by a window of its object type in id order when it has no filter and orders by nothing or by the record id ascending (KRN-1287); any other query is served by a sorted scan.
///
/// Specification function `query-windowed`.
pub fn query_windowed(def: &types::QueryDef) -> bool {
    match &def.filter {
        Some(_) => false,
        None => {
            u64::try_from(def.order.len()).unwrap_or(u64::MAX) == 0
                || u64::try_from(def.order.len()).unwrap_or(u64::MAX) == 1
                    && def.order.iter().any(|k| k.field == "$id" && !k.descending)
        }
    }
}

/// read.rs plan: the record id a cursor continues after; none for no cursor, for an offset cursor and for an index position.
///
/// Specification function `cursor-after`.
pub fn cursor_after(cursor: &Option<types::PageCursor>) -> Option<types::RecordId> {
    match cursor {
        Some(c) => match c {
            types::PageCursor::After(a) => Some(a.clone()),
            types::PageCursor::Offset(_) => None,
            types::PageCursor::At(_) => None,
        },
        None => None,
    }
}

/// read.rs plan: the number of rows an offset cursor skips; none for no cursor, for an after cursor and for an index position.
///
/// Specification function `cursor-offset`.
pub fn cursor_offset(cursor: &Option<types::PageCursor>) -> u32 {
    match cursor {
        Some(c) => match c {
            types::PageCursor::Offset(n) => *n,
            types::PageCursor::After(_) => 0,
            types::PageCursor::At(_) => 0,
        },
        None => 0,
    }
}

/// read.rs plan: why a named query read's page size or cursor is refused, as no error or one. A page size of 0 is invalid-intent, one above 200 is limit-exceeded (KRN-1285), and a cursor of the other kind than the query is served by is invalid-intent. An at cursor, which only a query planned on an index issues (KRN-2521), is refused here: the functions of the specification do not plan queries yet (difference 11 of generated_differential.rs).
///
/// Specification function `query-page-errors`.
pub fn query_page_errors(
    def: &types::QueryDef,
    asked: Option<u32>,
    cursor: &Option<types::PageCursor>,
) -> Vec<types::DomainError> {
    let size = query_page_size(def, asked);
    let windowed = query_windowed(def);
    if size == 0 {
        vec![types::DomainError {
            kind: types::ErrorKind::InvalidIntent,
            message: "a page size is at least 1".to_string(),
            evidence: Vec::<types::Check>::new(),
            missing: None,
        }]
    } else if size > 200 {
        vec![types::DomainError {
            kind: types::ErrorKind::LimitExceeded,
            message: format!("a page size of {size} is more than the maximum of 200"),
            evidence: Vec::<types::Check>::new(),
            missing: None,
        }]
    } else {
        match cursor {
            None => Vec::<types::DomainError>::new(),
            Some(c) => match c {
                types::PageCursor::After(_) => {
                    if windowed {
                        Vec::<types::DomainError>::new()
                    } else {
                        vec![types::DomainError {
                            kind: types::ErrorKind::InvalidIntent,
                            message: "the cursor is not one this query issued".to_string(),
                            evidence: Vec::<types::Check>::new(),
                            missing: None,
                        }]
                    }
                }
                types::PageCursor::Offset(_) => {
                    if windowed {
                        vec![types::DomainError {
                            kind: types::ErrorKind::InvalidIntent,
                            message: "the cursor is not one this query issued".to_string(),
                            evidence: Vec::<types::Check>::new(),
                            missing: None,
                        }]
                    } else {
                        Vec::<types::DomainError>::new()
                    }
                }
                types::PageCursor::At(_) => {
                    vec![types::DomainError {
                        kind: types::ErrorKind::InvalidIntent,
                        message: "the cursor is not one this query issued".to_string(),
                        evidence: Vec::<types::Check>::new(),
                        missing: None,
                    }]
                }
            },
        }
    }
}

/// rules.rs Lookup::page_of: at most limit records of an object type with an id above after (all when after is none), in id order; refused when the snapshot does not cover them.
///
/// Specification function `lookup-page`; fails with `rejection`.
pub fn lookup_page(
    tenant: &types::TenantState,
    coverage: &types::Coverage,
    object: &types::ObjectTypeId,
    after: &Option<types::RecordId>,
    limit: u32,
) -> Result<Vec<types::Record>, types::Rejection> {
    let wanted = types::Need::PageOf {
        object: object.clone(),
        after: after.clone(),
        limit,
    };
    Ok((if covers(coverage, &wanted) {
        match tenant.records.get(object) {
            Some(rs) => rs
                .values()
                .filter(|&r| match after {
                    Some(a) => r.id.clone().0 > a.clone().0,
                    None => true,
                })
                .cloned()
                .collect::<Vec<_>>()
                .iter()
                .take(support::count(i128::from(limit)))
                .cloned()
                .collect::<Vec<_>>(),
            None => Vec::<std::sync::Arc<types::Record>>::new(),
        }
    } else {
        return Err(types::Rejection::Rejected(insufficient(&wanted)));
    })
    .into_iter()
    .map(|item_| <types::Record as Clone>::clone(&item_))
    .collect::<Vec<_>>())
}

/// crates/kernel/src/read.rs read and query_plan.rs read_named, the named branch of kernel-read: refuses an unknown query (UnknownQuery), a parameter it does not declare and a page size or cursor it refuses (query-page-errors), then answers one page. A query served by a window (query-windowed) examines at most 200 records after the cursor, keeps those the principal may read (visible-in), and returns the first page-size of them as the reader receives them (redact) with a cursor after the last one it returned, or after the last record of the window when the window was full. Any other query examines at most 10001 records of its object type and is refused with limit-exceeded above 10000; each record the principal may read is taken as the reader receives it (redact) and kept when the filter holds of it (KRN-2522; a record the filter cannot be evaluated on is left out of the answer); the rows are sorted by the order keys and then by id, and the cursor is an offset. Read policies, the filter and the field read conditions follow a reference through the snapshot's lookup (rule-lookup), and a record one of them needs that the snapshot does not cover is InsufficientState naming it, in the order the records are examined (WG-5096). A page is not padded: a reader who may read few of the records examined gets a short page and a cursor.
///
/// Specification function `named-read`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn named_read(
    t: &types::TenantState,
    coverage: &types::Coverage,
    context: &types::Context,
    query: &types::QueryId,
    params: &std::collections::BTreeMap<String, types::Value>,
    page_size: Option<u32>,
    cursor: &Option<types::PageCursor>,
) -> Result<types::ReadResult, Failure<types::Rejection>> {
    Ok(match t.schema.queries.get(query) {
        None => {
            return Err(Failure::Error(types::Rejection::Rejected(
                types::DomainError {
                    kind: types::ErrorKind::UnknownQuery,
                    message: format!("no query {}", query.0),
                    evidence: Vec::<types::Check>::new(),
                    missing: None,
                },
            )));
        }
        Some(def) => {
            match params
                .keys()
                .find(|&k| !def.params.iter().any(|p| *p == *k))
            {
                Some(extra) => {
                    return Err(Failure::Error(types::Rejection::Rejected(
                        types::DomainError {
                            kind: types::ErrorKind::InvalidIntent,
                            message: format!("query {} has no parameter {extra}", query.0),
                            evidence: Vec::<types::Check>::new(),
                            missing: None,
                        },
                    )));
                }
                None => {
                    match query_page_errors(def, page_size, cursor).get(0) {
                        Some(e) => {
                            return Err(Failure::Error(types::Rejection::Rejected(e.clone())));
                        }
                        None => {
                            let windowed = query_windowed(def);
                            {
                                let size = query_page_size(def, page_size);
                                {
                                    let window = lookup_page(
                                        t,
                                        coverage,
                                        &def.object,
                                        &cursor_after(cursor),
                                        if windowed { 200 } else { 10001 },
                                    )
                                    .map_err(Failure::Error)?;
                                    if !windowed
                                        && u64::try_from(window.len()).unwrap_or(u64::MAX) > 10000
                                    {
                                        return Err(
                                                Failure::Error(
                                                    types::Rejection::Rejected(types::DomainError {
                                                        kind: types::ErrorKind::LimitExceeded,
                                                        message: format!(
                                                            "query {} orders {} records, more than the scan bound of 10000",
                                                            query.0, def.object.0
                                                        ),
                                                        evidence: vec![
                                                            types::Check { rule : format!("scan-bound:{}", query.0),
                                                            passed : false, detail :
                                                            "the query is not served by a window of the object type"
                                                            .to_string() }
                                                        ],
                                                        missing: None,
                                                    }),
                                                ),
                                            );
                                    } else {
                                        {
                                            let roles = roles_of(t, &context.principal);
                                            {
                                                let kept = {
                                                    let mut acc: Vec<types::Record> =
                                                        Vec::<types::Record>::new();
                                                    for r in window.iter() {
                                                        acc = if !visible_in(
                                                            t,
                                                            coverage,
                                                            &context.principal,
                                                            r,
                                                            context.now,
                                                        )? {
                                                            acc.clone()
                                                        } else {
                                                            {
                                                                let shown = if windowed {
                                                                    r.clone()
                                                                } else {
                                                                    redact(
                                                                        t,
                                                                        coverage,
                                                                        &context.principal,
                                                                        context.now,
                                                                        r,
                                                                    )?
                                                                };
                                                                match &def.filter {
                                                                    None => support::concat(
                                                                        &acc,
                                                                        &[shown.clone()],
                                                                    ),
                                                                    Some(filter) => {
                                                                        let reach = types::RuleReach {
                                                                                tenant: t.clone(),
                                                                                coverage: coverage.clone(),
                                                                                subject: types::Subject {
                                                                                    old: Some(shown.clone()),
                                                                                    new: Some(shown.clone()),
                                                                                },
                                                                            };
                                                                        match support::eval_lookup_tenant_rule_language_expr_env(
                                                                                filter,
                                                                                &types::ExprEnv {
                                                                                    record: Some(record_scope(&shown).map_err(Failure::Fault)?),
                                                                                    old: Some(record_scope(&shown).map_err(Failure::Fault)?),
                                                                                    new: Some(record_scope(&shown).map_err(Failure::Fault)?),
                                                                                    param: params.clone(),
                                                                                    now: types::Value::Time(context.now.0),
                                                                                    principal: principal_value(&context.principal),
                                                                                    has_role: roles
                                                                                        .clone()
                                                                                        .into_iter()
                                                                                        .map(|item_| item_.0)
                                                                                        .collect::<Vec<_>>(),
                                                                                },
                                                                                &rule_lookup(&reach).map_err(Failure::Fault)?,
                                                                            ) {
                                                                                Ok(x) => {
                                                                                    if x == types::Value::Bool(true) {
                                                                                        support::concat(&acc, &[shown.clone()])
                                                                                    } else {
                                                                                        acc.clone()
                                                                                    }
                                                                                }
                                                                                Err(_) => {
                                                                                    match rule_missing(filter, &reach) {
                                                                                        Some(n) => {
                                                                                            return Err(
                                                                                                Failure::Error(types::Rejection::Rejected(insufficient(&n))),
                                                                                            );
                                                                                        }
                                                                                        None => acc.clone(),
                                                                                    }
                                                                                }
                                                                            }
                                                                    }
                                                                }
                                                            }
                                                        };
                                                    }
                                                    acc
                                                };
                                                {
                                                    let sorted = order_rows(&kept, &def.order)
                                                        .map_err(Failure::Fault)?;
                                                    {
                                                        let offset = cursor_offset(cursor);
                                                        if windowed {
                                                            types::ReadResult {
                                                                rows: redact_rows(
                                                                    t,
                                                                    coverage,
                                                                    &context.principal,
                                                                    context.now,
                                                                    &sorted
                                                                        .iter()
                                                                        .take(support::count(
                                                                            i128::from(size),
                                                                        ))
                                                                        .cloned()
                                                                        .collect::<Vec<_>>(),
                                                                )?
                                                                .into_iter()
                                                                .map(|item_| {
                                                                    std::sync::Arc::new(item_)
                                                                })
                                                                .collect::<Vec<_>>(),
                                                                revision: t.revision.clone(),
                                                                schema_version: t
                                                                    .schema
                                                                    .version
                                                                    .clone(),
                                                                next: if i128::from(
                                                                    u64::try_from(sorted.len())
                                                                        .unwrap_or(u64::MAX),
                                                                ) > i128::from(size)
                                                                {
                                                                    match sorted
                                                                            .iter()
                                                                            .take(support::count(i128::from(size)))
                                                                            .cloned()
                                                                            .collect::<Vec<_>>()
                                                                            .iter()
                                                                            .fold(Vec::<types::Record>::new(), |_, r| vec![r.clone()])
                                                                            .get(0)
                                                                        {
                                                                            Some(r) => Some(types::PageCursor::After(r.id.clone())),
                                                                            None => None,
                                                                        }
                                                                } else if u64::try_from(
                                                                    window.len(),
                                                                )
                                                                .unwrap_or(u64::MAX)
                                                                    == 200
                                                                {
                                                                    match window
                                                                            .iter()
                                                                            .fold(Vec::<types::Record>::new(), |_, r| vec![r.clone()])
                                                                            .get(0)
                                                                        {
                                                                            Some(r) => Some(types::PageCursor::After(r.id.clone())),
                                                                            None => None,
                                                                        }
                                                                } else {
                                                                    None
                                                                },
                                                            }
                                                        } else {
                                                            types::ReadResult {
                                                                rows: sorted
                                                                    .iter()
                                                                    .take(support::count(
                                                                        i128::from(
                                                                            offset
                                                                                .checked_add(size)
                                                                                .ok_or(
                                                                                    Failure::Fault(
                                                                                        Fault {
                                                                                            op: "+",
                                                                                        },
                                                                                    ),
                                                                                )?,
                                                                        ),
                                                                    ))
                                                                    .cloned()
                                                                    .collect::<Vec<_>>()
                                                                    .iter()
                                                                    .filter(|&r| {
                                                                        !sorted
                                                                            .iter()
                                                                            .take(support::count(
                                                                                i128::from(offset),
                                                                            ))
                                                                            .cloned()
                                                                            .collect::<Vec<_>>()
                                                                            .iter()
                                                                            .any(|d| {
                                                                                d.id.clone().0
                                                                                    == r.id
                                                                                        .clone()
                                                                                        .0
                                                                            })
                                                                    })
                                                                    .cloned()
                                                                    .collect::<Vec<_>>()
                                                                    .into_iter()
                                                                    .map(|item_| {
                                                                        std::sync::Arc::new(item_)
                                                                    })
                                                                    .collect::<Vec<_>>(),
                                                                revision: t.revision.clone(),
                                                                schema_version: t
                                                                    .schema
                                                                    .version
                                                                    .clone(),
                                                                next: if i128::from(
                                                                    offset
                                                                        .checked_add(size)
                                                                        .ok_or(Failure::Fault(
                                                                            Fault { op: "+" },
                                                                        ))?,
                                                                ) < i128::from(
                                                                    u64::try_from(sorted.len())
                                                                        .unwrap_or(u64::MAX),
                                                                ) {
                                                                    Some(types::PageCursor::Offset(
                                                                        offset
                                                                            .checked_add(size)
                                                                            .ok_or(
                                                                                Failure::Fault(
                                                                                    Fault {
                                                                                        op: "+",
                                                                                    },
                                                                                ),
                                                                            )?,
                                                                    ))
                                                                } else {
                                                                    None
                                                                },
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    })
}

/// rules.rs holds_policy_power, the part that asks the role permissions: whether a grant is the object grant of the object type and the verb that the action names on the resource (an action that is manage, or a resource that is not an object type, has none).
///
/// Specification function `grant-allows`.
pub fn grant_allows(g: &types::Grant, act: &types::Action, res: &types::Resource) -> bool {
    match g {
        types::Grant::Capability(_) => false,
        types::Grant::Object(object, action) => {
            (match res {
                types::Resource::Object(o) => *o == *object,
                _ => false,
            }) && (match act {
                types::Action::Read => *action == types::ObjectAction::Read,
                types::Action::Create => *action == types::ObjectAction::Create,
                types::Action::Update => *action == types::ObjectAction::Update,
                types::Action::Delete => *action == types::ObjectAction::Delete,
                types::Action::Manage => false,
            })
        }
    }
}

/// rules.rs holds_policy_power: whether a principal holds the power one policy of a role confers, the action on the resource under the condition. The owner holds every power. Otherwise it holds it through a permission of one of its roles on the object type (grant-allows), or through a policy of one of its roles that names the action, reaches the resource (AnyObject covers every Object) and is either unconditional or carries the very same condition: two different conditions cannot be compared, so the wider one is not assumed to include the other.
///
/// Specification function `holds-policy-power`.
pub fn holds_policy_power(
    tenant: &types::TenantState,
    principal: &types::Principal,
    act: &types::Action,
    res: &types::Resource,
    cond: &Option<types::Expr>,
) -> bool {
    let roles = roles_of(tenant, principal);
    roles.iter().any(|r| r.0 == "owner")
        || effective_permissions(tenant, principal)
            .iter()
            .any(|g| grant_allows(g, act, res))
        || tenant.schema.policies.values().any(|p| {
            roles.iter().any(|r| *r == p.role)
                && p.actions.iter().any(|a| *a == *act)
                && (match &p.resource {
                    types::Resource::AnyObject => match res {
                        types::Resource::Object(_) => true,
                        _ => p.resource == *res,
                    },
                    _ => p.resource == *res,
                })
                && (p.condition.is_none() || p.condition == *cond)
        })
}

/// transition.rs effective_owners: the principals who hold owner in effect, directly or through a team: every principal of the table of members or of a team whose assigned-roles include owner.
///
/// Specification function `effective-owners`.
pub fn effective_owners(
    members: &std::collections::BTreeMap<
        types::PrincipalId,
        std::collections::BTreeSet<types::RoleId>,
    >,
    schema: &types::TenantSchema,
) -> Vec<types::PrincipalId> {
    principal_set_of(&support::concat(
        &members.keys().cloned().collect::<Vec<_>>(),
        &teams_of(schema)
            .values()
            .fold(Vec::<types::PrincipalId>::new(), |acc, t| {
                support::concat(&acc, &t.members.clone().into_iter().collect::<Vec<_>>())
            }),
    ))
    .iter()
    .filter(|&p| {
        assigned_roles(members, schema, p)
            .iter()
            .any(|r| r.0 == "owner")
    })
    .cloned()
    .collect::<Vec<_>>()
}

/// transition.rs require_an_owner_remains, as a test: whether a change leaves a tenant with no owner that had one. A tenant that has no owner before the change is not made worse by it, so it is not held to this. The members and the schema are the state before and after the change; counting goes through teams as well as direct assignments (effective-owners).
///
/// Specification function `owner-lost`.
pub fn owner_lost(
    before_members: &std::collections::BTreeMap<
        types::PrincipalId,
        std::collections::BTreeSet<types::RoleId>,
    >,
    before_schema: &types::TenantSchema,
    after_members: &std::collections::BTreeMap<
        types::PrincipalId,
        std::collections::BTreeSet<types::RoleId>,
    >,
    after_schema: &types::TenantSchema,
) -> bool {
    u64::try_from(effective_owners(before_members, before_schema).len()).unwrap_or(u64::MAX) > 0
        && u64::try_from(effective_owners(after_members, after_schema).len()).unwrap_or(u64::MAX)
            == 0
}

/// transition.rs refuse_reserved_principals, as a test: the refusal text for the first principal id that starts with a reserved prefix, or none. A person may not hold an id that starts with team: (a team appears in events under team:<id>) or automation: (the principal an automation acts as, automation.rs, WFL-1527). The ids examined are those of the owner a CreateTenant names, the principal an AssignRole or AddTeamMember names, and the caller. The team: prefix is checked first, over all of them in that order; then automation:, for the principal an intent names, and for the caller only when it has a session, since an automation acts without one (reserved_problem).
///
/// Specification function `reserved-principal`.
pub fn reserved_principal(intent: &types::Intent, ctx: &types::Context) -> Option<String> {
    let named = match intent {
        types::Intent::CreateTenant { owner: o, .. } => vec![o.clone()],
        types::Intent::AssignRole { principal: p, .. } => vec![p.clone()],
        types::Intent::AddTeamMember { principal: p, .. } => vec![p.clone()],
        _ => Vec::<types::PrincipalId>::new(),
    };
    let caller = match &ctx.principal {
        types::Principal::User(id) => vec![id.clone()],
        _ => Vec::<types::PrincipalId>::new(),
    };
    let team = support::concat(&named, &caller)
        .iter()
        .find(|&id| id.0.as_str().starts_with("team:"))
        .cloned();
    let automation = named
        .iter()
        .find(|&id| id.0.as_str().starts_with("automation:"))
        .cloned();
    let signed_in = match &ctx.session {
        Some(_) => caller.clone(),
        None => Vec::<types::PrincipalId>::new(),
    };
    let automation_caller = signed_in
        .iter()
        .find(|&id| id.0.as_str().starts_with("automation:"))
        .cloned();
    match &team {
        Some(id) => {
            Some(
                format!(
                    "the principal id {} starts with the reserved prefix team:", id.0
                ),
            )
        }
        None => {
            match &automation {
                Some(id) => {
                    Some(
                        format!(
                            "the principal id {} starts with the reserved prefix automation:",
                            id.0
                        ),
                    )
                }
                None => {
                    match &automation_caller {
                        Some(id) => {
                            Some(
                                format!(
                                    "the principal id {} starts with the reserved prefix automation:, which no signed-in person may hold",
                                    id.0
                                ),
                            )
                        }
                        None => None,
                    }
                }
            }
        }
    }
}

/// transition.rs needs, the schema change arm: the records of the target of each reference field of an object type, whole, as the re-validation of the changed object type looks up every reference of every one of its records (an AllOf need for each target, once each, in field id order). None for an object type the schema does not hold.
///
/// Specification function `ref-needs`.
pub fn ref_needs(schema: &types::TenantSchema, object: &types::ObjectTypeId) -> Vec<types::Need> {
    match schema.objects.get(object) {
        None => Vec::<types::Need>::new(),
        Some(def) => {
            def.fields
                .values()
                .fold(Vec::<types::Need>::new(), |acc, f| {
                    match ref_target(&f.ty) {
                        Some(t) => support::concat(&acc, &[types::Need::AllOf(t.clone())]),
                        None => acc.clone(),
                    }
                })
        }
    }
}

