/// The schema with its tables of mail templates, notice templates, tokens and installed products replaced; a table left empty is none, so a schema that holds none of them hashes as one that never did (D-7341).
///
/// Specification function `schema-with-tables`.
pub fn schema_with_tables(
    schema: &types::TenantSchema,
    mail: &std::collections::BTreeMap<types::TemplateId, types::MailTemplateDecl>,
    notice: &std::collections::BTreeMap<types::TemplateId, types::NoticeTemplateDecl>,
    tokens: &std::collections::BTreeMap<String, types::TokenDecl>,
    products: &std::collections::BTreeMap<types::ProductId, types::InstalledProduct>,
) -> types::TenantSchema {
    types::TenantSchema {
        version: schema.version.clone(),
        objects: schema.objects.clone(),
        roles: schema.roles.clone(),
        role_permissions: schema.role_permissions.clone(),
        teams: schema.teams.clone(),
        invitations: schema.invitations.clone(),
        policies: schema.policies.clone(),
        workflows: schema.workflows.clone(),
        queries: schema.queries.clone(),
        views: schema.views.clone(),
        triggers: schema.triggers.clone(),
        automations: schema.automations.clone(),
        operations: schema.operations.clone(),
        settings: schema.settings.clone(),
        capabilities: schema.capabilities.clone(),
        ledger: schema.ledger.clone(),
        mail_templates: if mail.keys().cloned().collect::<Vec<_>>().is_empty() {
            None
        } else {
            Some(mail.clone())
        },
        notice_templates: if notice.keys().cloned().collect::<Vec<_>>().is_empty() {
            None
        } else {
            Some(notice.clone())
        },
        tokens: if tokens.keys().cloned().collect::<Vec<_>>().is_empty() {
            None
        } else {
            Some(tokens.clone())
        },
        products: if products.keys().cloned().collect::<Vec<_>>().is_empty() {
            None
        } else {
            Some(products.clone())
        },
        ui: schema.ui.clone(),
    }
}

/// An object type with its four declarations replaced: retention, publication, language field and translation group (each none when absent). Its fields, constraints and composite unique constraints are carried on.
///
/// Specification function `object-with`.
pub fn object_with(
    o: &types::ObjectTypeDef,
    retention: &Option<types::RetentionRule>,
    publication: &Option<types::PublicationDef>,
    language_field: &Option<types::FieldId>,
    translation_group: &Option<types::FieldId>,
) -> types::ObjectTypeDef {
    types::ObjectTypeDef {
        id: o.id.clone(),
        label: o.label.clone(),
        fields: o.fields.clone(),
        constraints: o.constraints.clone(),
        retention: retention.clone(),
        publication: publication.clone(),
        language_field: language_field.clone(),
        translation_group: translation_group.clone(),
        unique: o.unique.clone(),
        searchable: None,
    }
}

/// transition.rs apply_change through object_meta::apply, templates::apply and products::apply: the declarations of an object type (set and clear its retention, publication, language field and translation group), the removal of an object type or a role, the templates and tokens, and the ownership record of a product, each applied to a working copy with the line that describes it. A define is define-or-replace; clearing a declaration that is not there, removing what does not exist and removing a built-in role are refused with the problem. A table left empty is none, so the schema hashes as one that never held it (D-7340, D-7341). The records of a removed object type and the principals that hold a removed role are the transition's to look at (change-schema).
///
/// Specification function `apply-meta-change`; fails with `schema-problem`.
pub fn apply_meta_change(
    schema: &types::TenantSchema,
    change: &types::SchemaChange,
) -> Result<types::SchemaStep, types::SchemaProblem> {
    Ok(match change {
        types::SchemaChange::SetRetention { object, retention } => {
            match schema.objects.get(object) {
                None => {
                    return Err(types::SchemaProblem::Problem(format!(
                        "no object type {}",
                        object.0
                    )));
                }
                Some(o) => types::SchemaStep {
                    schema: schema_with_objects(
                        schema,
                        &({
                            let mut map_ = schema.objects.clone();
                            map_.insert(
                                object.clone(),
                                object_with(
                                    o,
                                    &Some(retention.clone()),
                                    &o.publication,
                                    &o.language_field,
                                    &o.translation_group,
                                ),
                            );
                            map_
                        }),
                    ),
                    line: format!("set retention of {}", object.0),
                },
            }
        }
        types::SchemaChange::ClearRetention { object } => match schema.objects.get(object) {
            None => {
                return Err(types::SchemaProblem::Problem(format!(
                    "no object type {}",
                    object.0
                )));
            }
            Some(o) => {
                if o.retention.is_none() {
                    return Err(types::SchemaProblem::Problem(format!(
                        "{} declares no retention",
                        object.0
                    )));
                } else {
                    types::SchemaStep {
                        schema: schema_with_objects(
                            schema,
                            &({
                                let mut map_ = schema.objects.clone();
                                map_.insert(
                                    object.clone(),
                                    object_with(
                                        o,
                                        &None,
                                        &o.publication,
                                        &o.language_field,
                                        &o.translation_group,
                                    ),
                                );
                                map_
                            }),
                        ),
                        line: format!("clear retention of {}", object.0),
                    }
                }
            }
        },
        types::SchemaChange::SetPublication {
            object,
            publication,
        } => match schema.objects.get(object) {
            None => {
                return Err(types::SchemaProblem::Problem(format!(
                    "no object type {}",
                    object.0
                )));
            }
            Some(o) => types::SchemaStep {
                schema: schema_with_objects(
                    schema,
                    &({
                        let mut map_ = schema.objects.clone();
                        map_.insert(
                            object.clone(),
                            object_with(
                                o,
                                &o.retention,
                                &Some(publication.clone()),
                                &o.language_field,
                                &o.translation_group,
                            ),
                        );
                        map_
                    }),
                ),
                line: format!("set publication of {}", object.0),
            },
        },
        types::SchemaChange::ClearPublication { object } => match schema.objects.get(object) {
            None => {
                return Err(types::SchemaProblem::Problem(format!(
                    "no object type {}",
                    object.0
                )));
            }
            Some(o) => {
                if o.publication.is_none() {
                    return Err(types::SchemaProblem::Problem(format!(
                        "{} declares no publication",
                        object.0
                    )));
                } else {
                    types::SchemaStep {
                        schema: schema_with_objects(
                            schema,
                            &({
                                let mut map_ = schema.objects.clone();
                                map_.insert(
                                    object.clone(),
                                    object_with(
                                        o,
                                        &o.retention,
                                        &None,
                                        &o.language_field,
                                        &o.translation_group,
                                    ),
                                );
                                map_
                            }),
                        ),
                        line: format!("clear publication of {}", object.0),
                    }
                }
            }
        },
        types::SchemaChange::SetLanguageField { object, field } => {
            match schema.objects.get(object) {
                None => {
                    return Err(types::SchemaProblem::Problem(format!(
                        "no object type {}",
                        object.0
                    )));
                }
                Some(o) => types::SchemaStep {
                    schema: schema_with_objects(
                        schema,
                        &({
                            let mut map_ = schema.objects.clone();
                            map_.insert(
                                object.clone(),
                                object_with(
                                    o,
                                    &o.retention,
                                    &o.publication,
                                    &Some(field.clone()),
                                    &o.translation_group,
                                ),
                            );
                            map_
                        }),
                    ),
                    line: format!("set language field of {} to {}", object.0, field.0),
                },
            }
        }
        types::SchemaChange::ClearLanguageField { object } => match schema.objects.get(object) {
            None => {
                return Err(types::SchemaProblem::Problem(format!(
                    "no object type {}",
                    object.0
                )));
            }
            Some(o) => {
                if o.language_field.is_none() {
                    return Err(types::SchemaProblem::Problem(format!(
                        "{} declares no language field",
                        object.0
                    )));
                } else {
                    types::SchemaStep {
                        schema: schema_with_objects(
                            schema,
                            &({
                                let mut map_ = schema.objects.clone();
                                map_.insert(
                                    object.clone(),
                                    object_with(
                                        o,
                                        &o.retention,
                                        &o.publication,
                                        &None,
                                        &o.translation_group,
                                    ),
                                );
                                map_
                            }),
                        ),
                        line: format!("clear language field of {}", object.0),
                    }
                }
            }
        },
        types::SchemaChange::SetTranslationGroup { object, field } => {
            match schema.objects.get(object) {
                None => {
                    return Err(types::SchemaProblem::Problem(format!(
                        "no object type {}",
                        object.0
                    )));
                }
                Some(o) => types::SchemaStep {
                    schema: schema_with_objects(
                        schema,
                        &({
                            let mut map_ = schema.objects.clone();
                            map_.insert(
                                object.clone(),
                                object_with(
                                    o,
                                    &o.retention,
                                    &o.publication,
                                    &o.language_field,
                                    &Some(field.clone()),
                                ),
                            );
                            map_
                        }),
                    ),
                    line: format!("set translation group of {} to {}", object.0, field.0),
                },
            }
        }
        types::SchemaChange::ClearTranslationGroup { object } => match schema.objects.get(object) {
            None => {
                return Err(types::SchemaProblem::Problem(format!(
                    "no object type {}",
                    object.0
                )));
            }
            Some(o) => {
                if o.translation_group.is_none() {
                    return Err(types::SchemaProblem::Problem(format!(
                        "{} declares no translation group",
                        object.0
                    )));
                } else {
                    types::SchemaStep {
                        schema: schema_with_objects(
                            schema,
                            &({
                                let mut map_ = schema.objects.clone();
                                map_.insert(
                                    object.clone(),
                                    object_with(
                                        o,
                                        &o.retention,
                                        &o.publication,
                                        &o.language_field,
                                        &None,
                                    ),
                                );
                                map_
                            }),
                        ),
                        line: format!("clear translation group of {}", object.0),
                    }
                }
            }
        },
        types::SchemaChange::RemoveObject { id, .. } => match schema.objects.get(id) {
            None => {
                return Err(types::SchemaProblem::Problem(format!(
                    "no object type {}",
                    id.0
                )));
            }
            Some(_) => types::SchemaStep {
                schema: schema_with_objects(
                    schema,
                    &({
                        let mut map_ = schema.objects.clone();
                        map_.remove(id);
                        map_
                    }),
                ),
                line: format!("remove object {}", id.0),
            },
        },
        types::SchemaChange::RemoveRole(role) => {
            if role.0 == "public" || role.0 == "owner" {
                return Err(types::SchemaProblem::Problem(format!(
                    "{} is built in",
                    role.0
                )));
            } else {
                match schema.roles.get(role) {
                    None => {
                        return Err(types::SchemaProblem::Problem(format!("no role {}", role.0)));
                    }
                    Some(_) => types::SchemaStep {
                        schema: types::TenantSchema {
                            version: schema.version.clone(),
                            objects: schema.objects.clone(),
                            roles: {
                                let mut map_ = schema.roles.clone();
                                map_.remove(role);
                                map_
                            },
                            role_permissions: role_permissions_with(
                                schema,
                                role,
                                &Vec::<types::Permission>::new(),
                            ),
                            teams: schema.teams.clone(),
                            invitations: schema.invitations.clone(),
                            policies: schema.policies.clone(),
                            workflows: schema.workflows.clone(),
                            queries: schema.queries.clone(),
                            views: schema.views.clone(),
                            triggers: schema.triggers.clone(),
                            automations: schema.automations.clone(),
                            operations: schema.operations.clone(),
                            settings: schema.settings.clone(),
                            capabilities: schema.capabilities.clone(),
                            ledger: schema.ledger.clone(),
                            mail_templates: schema.mail_templates.clone(),
                            notice_templates: schema.notice_templates.clone(),
                            tokens: schema.tokens.clone(),
                            products: schema.products.clone(),
                            ui: schema.ui.clone(),
                        },
                        line: format!("remove role {}", role.0),
                    },
                }
            }
        }
        types::SchemaChange::DefineMailTemplate(d) => types::SchemaStep {
            schema: schema_with_tables(
                schema,
                &({
                    let mut map_ = mail_templates_of(schema);
                    map_.insert(d.template.clone(), d.clone());
                    map_
                }),
                &notice_templates_of(schema),
                &tokens_of(schema),
                &products_of(schema),
            ),
            line: format!("define mail template {}", d.template.0),
        },
        types::SchemaChange::RemoveMailTemplate(id) => {
            if mail_templates_of(schema).get(id).is_none() {
                return Err(types::SchemaProblem::Problem(format!(
                    "no mail template {}",
                    id.0
                )));
            } else {
                types::SchemaStep {
                    schema: schema_with_tables(
                        schema,
                        &({
                            let mut map_ = mail_templates_of(schema);
                            map_.remove(id);
                            map_
                        }),
                        &notice_templates_of(schema),
                        &tokens_of(schema),
                        &products_of(schema),
                    ),
                    line: format!("remove mail template {}", id.0),
                }
            }
        }
        types::SchemaChange::DefineNoticeTemplate(d) => types::SchemaStep {
            schema: schema_with_tables(
                schema,
                &mail_templates_of(schema),
                &({
                    let mut map_ = notice_templates_of(schema);
                    map_.insert(d.template.clone(), d.clone());
                    map_
                }),
                &tokens_of(schema),
                &products_of(schema),
            ),
            line: format!("define notice template {}", d.template.0),
        },
        types::SchemaChange::RemoveNoticeTemplate(id) => {
            if notice_templates_of(schema).get(id).is_none() {
                return Err(types::SchemaProblem::Problem(format!(
                    "no notice template {}",
                    id.0
                )));
            } else {
                types::SchemaStep {
                    schema: schema_with_tables(
                        schema,
                        &mail_templates_of(schema),
                        &({
                            let mut map_ = notice_templates_of(schema);
                            map_.remove(id);
                            map_
                        }),
                        &tokens_of(schema),
                        &products_of(schema),
                    ),
                    line: format!("remove notice template {}", id.0),
                }
            }
        }
        types::SchemaChange::DefineToken(d) => types::SchemaStep {
            schema: schema_with_tables(
                schema,
                &mail_templates_of(schema),
                &notice_templates_of(schema),
                &({
                    let mut map_ = tokens_of(schema);
                    map_.insert(d.name.clone(), d.clone());
                    map_
                }),
                &products_of(schema),
            ),
            line: format!("define token {}", d.name),
        },
        types::SchemaChange::RemoveToken(id) => {
            if tokens_of(schema).get(id).is_none() {
                return Err(types::SchemaProblem::Problem(format!("no token {id}")));
            } else {
                types::SchemaStep {
                    schema: schema_with_tables(
                        schema,
                        &mail_templates_of(schema),
                        &notice_templates_of(schema),
                        &({
                            let mut map_ = tokens_of(schema);
                            map_.remove(id);
                            map_
                        }),
                        &products_of(schema),
                    ),
                    line: format!("remove token {id}"),
                }
            }
        }
        types::SchemaChange::RecordProduct(p) => types::SchemaStep {
            schema: schema_with_tables(
                schema,
                &mail_templates_of(schema),
                &notice_templates_of(schema),
                &tokens_of(schema),
                &({
                    let mut map_ = products_of(schema);
                    map_.insert(p.product.clone(), p.clone());
                    map_
                }),
            ),
            line: format!("record product {} {}", p.product.0, p.version),
        },
        types::SchemaChange::RemoveProduct(id) => {
            if products_of(schema).get(id).is_none() {
                return Err(types::SchemaProblem::Problem(format!(
                    "no product {}",
                    id.0
                )));
            } else {
                types::SchemaStep {
                    schema: schema_with_tables(
                        schema,
                        &mail_templates_of(schema),
                        &notice_templates_of(schema),
                        &tokens_of(schema),
                        &({
                            let mut map_ = products_of(schema);
                            map_.remove(id);
                            map_
                        }),
                    ),
                    line: format!("remove product {}", id.0),
                }
            }
        }
        types::SchemaChange::DefineUiElement { id, element } => types::SchemaStep {
            schema: types::TenantSchema {
                version: schema.version.clone(),
                objects: schema.objects.clone(),
                roles: schema.roles.clone(),
                role_permissions: schema.role_permissions.clone(),
                teams: schema.teams.clone(),
                invitations: schema.invitations.clone(),
                policies: schema.policies.clone(),
                workflows: schema.workflows.clone(),
                queries: schema.queries.clone(),
                views: schema.views.clone(),
                triggers: schema.triggers.clone(),
                automations: schema.automations.clone(),
                operations: schema.operations.clone(),
                settings: schema.settings.clone(),
                capabilities: schema.capabilities.clone(),
                ledger: schema.ledger.clone(),
                mail_templates: schema.mail_templates.clone(),
                notice_templates: schema.notice_templates.clone(),
                tokens: schema.tokens.clone(),
                products: schema.products.clone(),
                ui: Some({
                    let mut map_ = ui_of(schema);
                    map_.insert(id.clone(), element.clone());
                    map_
                }),
            },
            line: format!("define interface element {id}"),
        },
        types::SchemaChange::RemoveUiElement(id) => {
            if ui_of(schema).get(id).is_none() {
                return Err(types::SchemaProblem::Problem(format!(
                    "no interface element {id}"
                )));
            } else {
                {
                    let rest = {
                        let mut map_ = ui_of(schema);
                        map_.remove(id);
                        map_
                    };
                    types::SchemaStep {
                        schema: types::TenantSchema {
                            version: schema.version.clone(),
                            objects: schema.objects.clone(),
                            roles: schema.roles.clone(),
                            role_permissions: schema.role_permissions.clone(),
                            teams: schema.teams.clone(),
                            invitations: schema.invitations.clone(),
                            policies: schema.policies.clone(),
                            workflows: schema.workflows.clone(),
                            queries: schema.queries.clone(),
                            views: schema.views.clone(),
                            triggers: schema.triggers.clone(),
                            automations: schema.automations.clone(),
                            operations: schema.operations.clone(),
                            settings: schema.settings.clone(),
                            capabilities: schema.capabilities.clone(),
                            ledger: schema.ledger.clone(),
                            mail_templates: schema.mail_templates.clone(),
                            notice_templates: schema.notice_templates.clone(),
                            tokens: schema.tokens.clone(),
                            products: schema.products.clone(),
                            ui: if rest.keys().cloned().collect::<Vec<_>>().is_empty() {
                                None
                            } else {
                                Some(rest.clone())
                            },
                        },
                        line: format!("remove interface element {id}"),
                    }
                }
            }
        }
        _ => {
            return Err(types::SchemaProblem::Problem(
                "not a change of a declaration, a template, a token or a product".to_string(),
            ));
        }
    })
}

/// Whether the string a is not below the string b in the order of Unicode scalar values, which is the order of the bytes of their UTF-8 encoding (the body language orders strings only through sortBy).
///
/// Specification function `string-at-least`.
pub fn string_at_least(a: &String, b: &String) -> bool {
    support::sorted_by(vec![a.clone(), b.clone()].iter(), |x| x.clone()).get(0) == Some(b)
}

/// The number of bytes of the UTF-8 encoding of one character: 1 below U+0080, 2 below U+0800, 3 below U+10000, 4 above. The body language has no byte length, so it is found by comparing the character with the three bounds (Rust str::len, which limits.rs counts).
///
/// Specification function `utf8-char-len`.
pub fn utf8_char_len(c: &String) -> u64 {
    if string_at_least(c, &"\u{80}".to_string()) {
        if string_at_least(c, &"ࠀ".to_string()) {
            if string_at_least(c, &"𐀀".to_string()) {
                4
            } else {
                3
            }
        } else {
            2
        }
    } else {
        1
    }
}

/// The number of bytes of the UTF-8 encoding of a string: Rust str::len, which limits.rs counts, where length(s) counts characters.
///
/// Specification function `utf8-length`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn utf8_length(s: &String) -> Result<u64, Fault> {
    Ok({
        let mut n: u64 = 0;
        for c in s
            .as_str()
            .chars()
            .map(String::from)
            .collect::<Vec<_>>()
            .iter()
        {
            n = n.checked_add(utf8_char_len(c)).ok_or(Fault { op: "+" })?;
        }
        n
    })
}

/// The bytes of a string written as serde_json writes it (compact, in double quotes, with the escapes of the {:json} placeholder).
///
/// Specification function `json-string-bytes`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn json_string_bytes(s: &String) -> Result<u64, Fault> {
    Ok(utf8_length(&format!(
        "{}",
        serde_json::to_string(s).unwrap_or_default()
    ))?)
}

/// The bytes of the serde_json encoding of a value that is not a list (strata_kernel::Value is externally tagged: {"Int":5}, {"Str":"x"}, "Null"); a list gives 0 here, value-json-bytes counts lists.
///
/// Specification function `value-json-bytes-inner`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn value_json_bytes_inner(x: &types::Value) -> Result<u64, Fault> {
    Ok(match x {
        types::Value::Bool(b) => {
            if *b {
                13
            } else {
                14
            }
        }
        types::Value::Int(n) => 8u64
            .checked_add(u64::try_from(format!("{n}").as_str().chars().count()).unwrap_or(u64::MAX))
            .ok_or(Fault { op: "+" })?,
        types::Value::Str(s) => 8u64
            .checked_add(json_string_bytes(s)?)
            .ok_or(Fault { op: "+" })?,
        types::Value::Time(t) => 9u64
            .checked_add(u64::try_from(format!("{t}").as_str().chars().count()).unwrap_or(u64::MAX))
            .ok_or(Fault { op: "+" })?,
        types::Value::Ref(r) => 8u64
            .checked_add(
                u64::try_from(format!("{}", r.0).as_str().chars().count()).unwrap_or(u64::MAX),
            )
            .ok_or(Fault { op: "+" })?,
        types::Value::List(_) => 0,
        _ => 6,
    })
}

/// The bytes of the serde_json encoding of a value ({"List":[..]} for a list; limits.rs encoded_len, and the size of a record), at any depth: structural recursion, every call of itself on an item of the list matched from x (WG-5133).
///
/// Specification function `value-json-bytes`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn value_json_bytes(x: &types::Value) -> Result<u64, Fault> {
    Ok(match x {
        types::Value::List(items) => 11u64
            .checked_add({
                let mut n: u64 = 0;
                for i in items.iter() {
                    n = n
                        .checked_add(value_json_bytes(i)?)
                        .ok_or(Fault { op: "+" })?;
                }
                n
            })
            .ok_or(Fault { op: "+" })?
            .checked_add(if u64::try_from(items.len()).unwrap_or(u64::MAX) > 0 {
                u64::try_from(items.len())
                    .unwrap_or(u64::MAX)
                    .checked_sub(1)
                    .ok_or(Fault { op: "-" })?
            } else {
                0
            })
            .ok_or(Fault { op: "+" })?,
        _ => value_json_bytes_inner(x)?,
    })
}

/// The bytes of the serde_json encoding of a record, as rules.rs validate_record measures it: {"id":1,"object":"note","version":1,"created_by":null,"created_at":0,"updated_at":0,"fields":{"title":{"Str":"x"}}}. 82 are the fixed text of the seven members.
///
/// Specification function `record-json-bytes`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn record_json_bytes(r: &types::Record) -> Result<u64, Fault> {
    Ok(82u64
        .checked_add(
            u64::try_from(format!("{}", r.id.0).as_str().chars().count()).unwrap_or(u64::MAX),
        )
        .ok_or(Fault { op: "+" })?
        .checked_add(json_string_bytes(&r.object.clone().0)?)
        .ok_or(Fault { op: "+" })?
        .checked_add(
            u64::try_from(format!("{}", r.version).as_str().chars().count()).unwrap_or(u64::MAX),
        )
        .ok_or(Fault { op: "+" })?
        .checked_add(match &r.created_by {
            Some(p) => json_string_bytes(&p.clone().0)?,
            None => 4,
        })
        .ok_or(Fault { op: "+" })?
        .checked_add(
            u64::try_from(format!("{}", r.created_at.0).as_str().chars().count())
                .unwrap_or(u64::MAX),
        )
        .ok_or(Fault { op: "+" })?
        .checked_add(
            u64::try_from(format!("{}", r.updated_at.0).as_str().chars().count())
                .unwrap_or(u64::MAX),
        )
        .ok_or(Fault { op: "+" })?
        .checked_add({
            let mut n: u64 = 0;
            for k in r.fields.keys() {
                n = n
                    .checked_add(json_string_bytes(&k.clone().0)?)
                    .ok_or(Fault { op: "+" })?
                    .checked_add(1)
                    .ok_or(Fault { op: "+" })?;
            }
            n
        })
        .ok_or(Fault { op: "+" })?
        .checked_add({
            let mut n: u64 = 0;
            for v in r.fields.values() {
                n = n
                    .checked_add(value_json_bytes(v)?)
                    .ok_or(Fault { op: "+" })?;
            }
            n
        })
        .ok_or(Fault { op: "+" })?
        .checked_add(
            if u64::try_from(r.fields.keys().cloned().collect::<Vec<_>>().len()).unwrap_or(u64::MAX)
                > 0
            {
                u64::try_from(r.fields.keys().cloned().collect::<Vec<_>>().len())
                    .unwrap_or(u64::MAX)
                    .checked_sub(1)
                    .ok_or(Fault { op: "-" })?
            } else {
                0
            },
        )
        .ok_or(Fault { op: "+" })?)
}

/// limits.rs value_problem for a value that is not a list: a string of more than max-string bytes. A list gives none here; value-limit-problem searches lists.
///
/// Specification function `limit-problem-scalar`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn limit_problem_scalar(
    x: &types::Value,
    max_string: u64,
    _max_list: u64,
) -> Result<String, Fault> {
    Ok(match x {
        types::Value::Str(s) => {
            let n = utf8_length(s)?;
            if n > max_string {
                format!("a string of {n} bytes is longer than the maximum of {max_string}")
            } else {
                "".to_string()
            }
        }
        _ => "".to_string(),
    })
}

/// limits.rs value_problem: the first limit a value breaks, as its description, or the empty string (the kernel gives none). The maximum of a string is in bytes, the maximum of a list in items. A list is searched as deep as there are lists: structural recursion, every call of itself on an item of the list matched from x (WG-5133).
///
/// Specification function `value-limit-problem`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn value_limit_problem(
    x: &types::Value,
    max_string: u64,
    max_list: u64,
) -> Result<String, Fault> {
    Ok(match x {
        types::Value::List(items) => {
            if u64::try_from(items.len()).unwrap_or(u64::MAX) > max_list {
                format!(
                    "a list of {} items is longer than the maximum of {max_list}",
                    u64::try_from(items.len()).unwrap_or(u64::MAX)
                )
            } else {
                {
                    let mut a: String = "".to_string();
                    for i in items.iter() {
                        a = if a != "" {
                            a.clone()
                        } else {
                            value_limit_problem(i, max_string, max_list)?
                        };
                    }
                    a
                }
            }
        }
        _ => limit_problem_scalar(x, max_string, max_list)?,
    })
}

/// rules.rs validate_record, the first check: a record whose JSON encoding is longer than max bytes (262144) is limit:record:<object>, LimitExceeded, before any field is looked at.
///
/// Specification function `record-limit-check`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn record_limit_check(
    acc: &types::ValidationOutcome,
    object: &types::ObjectTypeDef,
    candidate: &types::Record,
    max: u64,
) -> Result<types::ValidationOutcome, Fault> {
    Ok({
        let n = record_json_bytes(candidate)?;
        if n > max {
            outcome_fail(
                acc,
                &types::ErrorKind::LimitExceeded,
                &format!("limit:record:{}", object.id.0),
                &format!("a record of {n} bytes is larger than the maximum of {max}"),
            )
        } else {
            acc.clone()
        }
    })
}

/// rules.rs validate_record, second loop, the limits of one field value that is present: the first limit the value breaks (value-limit-problem) is limit:<object>.<field>; a value of a unique field of more than max-unique encoded bytes is limit:unique:<object>.<field>. Both are LimitExceeded.
///
/// Specification function `limit-step`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn limit_step(
    acc: &types::ValidationOutcome,
    at: &String,
    field: &types::FieldDef,
    x: &types::Value,
    max_string: u64,
    max_list: u64,
    max_unique: u64,
) -> Result<types::ValidationOutcome, Fault> {
    Ok({
        let p = value_limit_problem(x, max_string, max_list)?;
        if p != "" {
            outcome_fail(
                acc,
                &types::ErrorKind::LimitExceeded,
                &format!("limit:{at}"),
                &p,
            )
        } else if field.unique && value_json_bytes(x)? > max_unique {
            outcome_fail(
                acc,
                &types::ErrorKind::LimitExceeded,
                &format!("limit:unique:{at}"),
                &format!("a value in a unique field is at most {max_unique} bytes encoded"),
            )
        } else {
            acc.clone()
        }
    })
}

/// transition.rs delete_record: a record that refers to the deleted record in one or more fields, rewritten once with every one of those fields cleared (removed from a list, removed otherwise), the version one higher and updated now. hits are the referrer fields found for it, in referrer order.
///
/// Specification function `cleared-record`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn cleared_record(
    record: &types::Record,
    hits: &Vec<types::ReferrerHit>,
    target: &types::Value,
    now: crate::prelude::Timestamp,
) -> Result<types::Record, Fault> {
    Ok(types::Record {
        id: record.id.clone(),
        object: record.object.clone(),
        version: record.version.checked_add(1).ok_or(Fault { op: "+" })?,
        created_by: record.created_by.clone(),
        created_at: record.created_at,
        updated_at: now,
        fields: hits
            .iter()
            .filter(|&g| {
                g.record.object == record.object && g.record.id.clone().0 == record.id.clone().0
            })
            .cloned()
            .collect::<Vec<_>>()
            .iter()
            .fold(record.fields.clone(), |fs, g| {
                match fs.get(&g.referrer.field.id) {
                    Some(x) => match x {
                        types::Value::List(items) => {
                            let mut map_ = fs.clone();
                            map_.insert(
                                g.referrer.field.id.clone(),
                                types::Value::List(
                                    items
                                        .iter()
                                        .filter(|&i| *i != *target)
                                        .cloned()
                                        .collect::<Vec<_>>(),
                                ),
                            );
                            map_
                        }
                        _ => {
                            let mut map_ = fs.clone();
                            map_.remove(&g.referrer.field.id);
                            map_
                        }
                    },
                    None => {
                        let mut map_ = fs.clone();
                        map_.remove(&g.referrer.field.id);
                        map_
                    }
                }
            }),
    })
}

/// read.rs redact: the record without the fields whose read condition (FieldDef.read) does not hold for the reader, evaluated with the record as record, old and new, no parameters, the reader and the roles of the reader, and the snapshot's lookup over the record's reference fields (rule-lookup). A condition that does not evaluate to exactly true hides the field, an evaluation error too, unless it failed because the snapshot does not cover a record it follows (rule-missing): that is InsufficientState naming the record, so the shell loads it and asks again (WG-5096). A field the record does not hold is not looked at; the system reads everything, and so does a record of an object type the schema does not declare.
///
/// Specification function `redact`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn redact(
    t: &types::TenantState,
    coverage: &types::Coverage,
    principal: &types::Principal,
    now: crate::prelude::Timestamp,
    r: &types::Record,
) -> Result<types::Record, Failure<types::Rejection>> {
    Ok(match principal {
        types::Principal::System => r.clone(),
        _ => match t.schema.objects.get(&r.object) {
            None => r.clone(),
            Some(def) => {
                let scope = record_scope(r).map_err(Failure::Fault)?;
                {
                    let env = types::ExprEnv {
                        record: Some(scope.clone()),
                        old: Some(scope.clone()),
                        new: Some(scope.clone()),
                        param: std::collections::BTreeMap::<String, types::Value>::new(),
                        now: types::Value::Time(now.0),
                        principal: principal_value(principal),
                        has_role: roles_of(t, principal)
                            .into_iter()
                            .map(|item_| item_.0)
                            .collect::<Vec<_>>(),
                    };
                    {
                        let reach = types::RuleReach {
                            tenant: t.clone(),
                            coverage: coverage.clone(),
                            subject: types::Subject {
                                old: Some(r.clone()),
                                new: Some(r.clone()),
                            },
                        };
                        {
                            let lookup = rule_lookup(&reach).map_err(Failure::Fault)?;
                            {
                                let hidden = {
                                    let mut acc: Vec<types::FieldDef> =
                                        Vec::<types::FieldDef>::new();
                                    for f in def.fields.values() {
                                        acc = match &f.read {
                                            None => acc.clone(),
                                            Some(rule) => {
                                                if r.fields.get(&f.id).is_none() {
                                                    acc.clone()
                                                } else {
                                                    match support::eval_lookup_tenant_rule_language_expr_env(
                                                                rule,
                                                                &env,
                                                                &lookup,
                                                            ) {
                                                                Ok(x) => {
                                                                    if x == types::Value::Bool(true) {
                                                                        acc.clone()
                                                                    } else {
                                                                        support::concat(&acc, &[f.clone()])
                                                                    }
                                                                }
                                                                Err(_) => {
                                                                    match rule_missing(rule, &reach) {
                                                                        Some(n) => {
                                                                            return Err(
                                                                                Failure::Error(types::Rejection::Rejected(insufficient(&n))),
                                                                            );
                                                                        }
                                                                        None => support::concat(&acc, &[f.clone()]),
                                                                    }
                                                                }
                                                            }
                                                }
                                            }
                                        };
                                    }
                                    acc
                                };
                                if hidden.is_empty() {
                                    r.clone()
                                } else {
                                    types::Record {
                                        id: r.id.clone(),
                                        object: r.object.clone(),
                                        version: r.version,
                                        created_by: r.created_by.clone(),
                                        created_at: r.created_at,
                                        updated_at: r.updated_at,
                                        fields: hidden.iter().fold(r.fields.clone(), |m, f| {
                                            let mut map_ = m.clone();
                                            map_.remove(&f.id);
                                            map_
                                        }),
                                    }
                                }
                            }
                        }
                    }
                }
            }
        },
    })
}

/// read.rs read, the last step: every row as the reader receives it (redact), with the snapshot's lookup; the first InsufficientState of a row ends the read.
///
/// Specification function `redact-rows`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn redact_rows(
    t: &types::TenantState,
    coverage: &types::Coverage,
    principal: &types::Principal,
    now: crate::prelude::Timestamp,
    rows: &Vec<types::Record>,
) -> Result<Vec<types::Record>, Failure<types::Rejection>> {
    Ok({
        let mut out_ = Vec::new();
        for r in rows.iter() {
            out_.push(redact(t, coverage, principal, now, r)?);
        }
        out_
    })
}

/// schema.rs TenantSchema::problems, the first loop: a schema that defines more of something than the maximum (object types 200, policies 500, queries 500) is "limit: <count> <what> is more than the maximum of <max>".
///
/// Specification function `limit-count-problem`.
pub fn limit_count_problem(what: &String, count: u64, max: u64) -> Vec<String> {
    if count > max {
        vec![format!(
            "limit: {count} {what} is more than the maximum of {max}"
        )]
    } else {
        Vec::<String>::new()
    }
}

/// schema.rs TenantSchema::problems, the limits (limits.rs): more than 200 object types, 500 policies or 500 queries, in that order, then each query (in id order) whose limit is 0 or more than 200 (the largest page): "limit: query <id> declares a limit outside 1 to 200".
///
/// Specification function `schema-limit-problems`.
pub fn schema_limit_problems(schema: &types::TenantSchema) -> Vec<String> {
    support::concat(
        &support::concat(
            &support::concat(
                &limit_count_problem(
                    &"object types".to_string(),
                    u64::try_from(schema.objects.keys().cloned().collect::<Vec<_>>().len())
                        .unwrap_or(u64::MAX),
                    200,
                ),
                &limit_count_problem(
                    &"policies".to_string(),
                    u64::try_from(schema.policies.keys().cloned().collect::<Vec<_>>().len())
                        .unwrap_or(u64::MAX),
                    500,
                ),
            ),
            &limit_count_problem(
                &"queries".to_string(),
                u64::try_from(schema.queries.keys().cloned().collect::<Vec<_>>().len())
                    .unwrap_or(u64::MAX),
                500,
            ),
        ),
        &schema.queries.values().fold(Vec::<String>::new(), |ps, q| {
            support::concat(
                &ps,
                &(match q.limit {
                    Some(n) => {
                        if n == 0 || n > 200 {
                            vec![format!(
                                "limit: query {} declares a limit outside 1 to 200",
                                q.id.0
                            )]
                        } else {
                            Vec::<String>::new()
                        }
                    }
                    None => Vec::<String>::new(),
                }),
            )
        }),
    )
}

/// schema.rs TenantSchema::problems, the start of an object type: more than 100 fields is "limit: <object> has <count> fields, more than the maximum of 100".
///
/// Specification function `field-count-problem`.
pub fn field_count_problem(object: &types::ObjectTypeDef) -> Vec<String> {
    if u64::try_from(object.fields.keys().cloned().collect::<Vec<_>>().len()).unwrap_or(u64::MAX)
        > 100
    {
        vec![format!(
            "limit: {} has {} fields, more than the maximum of 100",
            object.id.0,
            u64::try_from(object.fields.keys().cloned().collect::<Vec<_>>().len())
                .unwrap_or(u64::MAX)
        )]
    } else {
        Vec::<String>::new()
    }
}

/// schema.rs TenantSchema::problems, the permissions of roles (in role id order): a role that is not declared, the owner role (it holds every permission), and per permission (in order) a capability with a blank name, an object permission on an object type the schema does not declare, and one that names no action. A capability of the product form that is not declared, or that belongs to another product than the role, is a problem too (capability-grant-problem).
///
/// Specification function `role-permission-problems`.
pub fn role_permission_problems(
    schema: &types::TenantSchema,
    roles: &Vec<types::RoleId>,
) -> Vec<String> {
    match &schema.role_permissions {
        None => Vec::<String>::new(),
        Some(table) => table.keys().fold(Vec::<String>::new(), |ps, role| {
            let at = format!("role {}", role.0);
            support::concat(
                &support::concat(
                    &support::concat(
                        &ps,
                        &(if roles.iter().any(|r| *r == *role) {
                            Vec::<String>::new()
                        } else {
                            vec![format!("{at}: permissions of an unknown role")]
                        }),
                    ),
                    &(if role.0 == "owner" {
                        vec![format!("{at}: the owner role holds every permission")]
                    } else {
                        Vec::<String>::new()
                    }),
                ),
                &(match table.get(role) {
                    Some(permissions) => permissions.iter().fold(Vec::<String>::new(), |qs, p| {
                        support::concat(
                            &qs,
                            &(match p {
                                types::Permission::Capability(name) => {
                                    if name.as_str().trim().to_string() == "" {
                                        vec![format!("{at}: a capability needs a name")]
                                    } else {
                                        match capability_grant_problem(schema, role, name) {
                                            Some(problem) => vec![format!("{at}: {problem}")],
                                            None => Vec::<String>::new(),
                                        }
                                    }
                                }
                                types::Permission::Object {
                                    object: o,
                                    actions: acts,
                                } => support::concat(
                                    &(if schema.objects.get(o).is_none() {
                                        vec![format!(
                                            "{at}: permission on unknown object type {}",
                                            o.0
                                        )]
                                    } else {
                                        Vec::<String>::new()
                                    }),
                                    &(if acts.is_empty() {
                                        vec![format!("{at}: permission on {} names no action", o.0)]
                                    } else {
                                        Vec::<String>::new()
                                    }),
                                ),
                            }),
                        )
                    }),
                    None => Vec::<String>::new(),
                }),
            )
        }),
    }
}

/// schema.rs TenantSchema::problems, the teams (in id order): per role of the team (in order) a role that is not declared, and the public role (everyone holds it already).
///
/// Specification function `team-problems`.
pub fn team_problems(schema: &types::TenantSchema, roles: &Vec<types::RoleId>) -> Vec<String> {
    match &schema.teams {
        None => Vec::<String>::new(),
        Some(teams) => teams.values().fold(Vec::<String>::new(), |ps, t| {
            let at = format!("team {}", t.id.0);
            support::concat(
                &ps,
                &t.roles.iter().fold(Vec::<String>::new(), |qs, role| {
                    support::concat(
                        &support::concat(
                            &qs,
                            &(if roles.iter().any(|r| *r == *role) {
                                Vec::<String>::new()
                            } else {
                                vec![format!("{at}: unknown role {}", role.0)]
                            }),
                        ),
                        &(if role.0 == "public" {
                            vec![format!("{at}: everyone already holds public")]
                        } else {
                            Vec::<String>::new()
                        }),
                    )
                }),
            )
        }),
    }
}

/// schema.rs TenantSchema::problems, the invitations (in id order): one that names no address, and per role (in order) a role that is not declared.
///
/// Specification function `invitation-problems`.
pub fn invitation_problems(
    schema: &types::TenantSchema,
    roles: &Vec<types::RoleId>,
) -> Vec<String> {
    match &schema.invitations {
        None => Vec::<String>::new(),
        Some(invitations) => invitations.values().fold(Vec::<String>::new(), |ps, i| {
            let at = format!("invitation {}", i.id.0);
            support::concat(
                &support::concat(
                    &ps,
                    &(if i.address == "" {
                        vec![format!("{at}: names no address")]
                    } else {
                        Vec::<String>::new()
                    }),
                ),
                &i.roles.iter().fold(Vec::<String>::new(), |qs, role| {
                    support::concat(
                        &qs,
                        &(if roles.iter().any(|r| *r == *role) {
                            Vec::<String>::new()
                        } else {
                            vec![format!("{at}: unknown role {}", role.0)]
                        }),
                    )
                }),
            )
        }),
    }
}

/// The setting definitions of a schema by id, none when it holds no table of them (TenantSchema.settings, an optional map; settings.rs definition).
