/// The record a scope of a rule reads in rules.rs authorize: record is the old record, or the new one when there is none; old and new are themselves.
///
/// Specification function `scope-record`.
pub fn scope_record(subject: &types::Subject, s: &types::Scope) -> Option<types::Record> {
    match s {
        types::Scope::Record => {
            if subject.old.is_none() {
                subject.new.clone()
            } else {
                subject.old.clone()
            }
        }
        types::Scope::Old => subject.old.clone(),
        types::Scope::New => subject.new.clone(),
    }
}

/// The object type a single reference field of an object type points at (types.rs FieldType::ref_target with many false); none for a field that is not one, or an object type or field the schema lacks.
///
/// Specification function `single-reference`.
pub fn single_reference(
    schema: &types::TenantSchema,
    object: &types::ObjectTypeId,
    field: &String,
) -> Option<types::ObjectTypeId> {
    match schema.objects.get(object) {
        None => None,
        Some(o) => match o.fields.get(&types::FieldId(field.clone())) {
            None => None,
            Some(d) => match &d.ty {
                types::FieldType::Ref { target, .. } => Some(target.clone()),
                _ => None,
            },
        },
    }
}

/// The record id a field of a record holds when it holds a reference; none for no record, a missing field or another value.
///
/// Specification function `reference-held`.
pub fn reference_held(
    scoped: &Option<types::Record>,
    field: &types::FieldId,
) -> Vec<types::RecordId> {
    match scoped {
        None => Vec::<types::RecordId>::new(),
        Some(r) => match r.fields.get(field) {
            None => Vec::<types::RecordId>::new(),
            Some(v) => match v {
                types::Value::Ref(i) => vec![i.clone()],
                _ => Vec::<types::RecordId>::new(),
            },
        },
    }
}

/// The lookup of eval for a rule of rules.rs authorize (crates/kernel/src/expr.rs Env::follow over a Lookup): for each single reference field of the record's object type whose targets in the old and new records the snapshot covers, the targets that exist, by the decimal text of their id, each as a record scope. A field one of whose targets the snapshot does not cover is left out, so following it is an evaluation error, as Lookup::record refuses a record the snapshot does not cover; a covered target that does not exist is absent, so following it is null, as in the kernel.
///
/// Specification function `rule-lookup`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn rule_lookup(
    reach: &types::RuleReach,
) -> Result<
    std::collections::BTreeMap<
        String,
        std::collections::BTreeMap<String, std::collections::BTreeMap<String, types::Value>>,
    >,
    Fault,
> {
    let scoped = if reach.subject.old.is_none() {
        reach.subject.new.clone()
    } else {
        reach.subject.old.clone()
    };
    Ok(match &scoped {
        None => std::collections::BTreeMap::<
            String,
            std::collections::BTreeMap<String, std::collections::BTreeMap<String, types::Value>>,
        >::new(),
        Some(r) => match reach.tenant.schema.objects.get(&r.object) {
            None => std::collections::BTreeMap::<
                String,
                std::collections::BTreeMap<
                    String,
                    std::collections::BTreeMap<String, types::Value>,
                >,
            >::new(),
            Some(o) => {
                let mut acc: std::collections::BTreeMap<
                    String,
                    std::collections::BTreeMap<
                        String,
                        std::collections::BTreeMap<String, types::Value>,
                    >,
                > = std::collections::BTreeMap::<
                    String,
                    std::collections::BTreeMap<
                        String,
                        std::collections::BTreeMap<String, types::Value>,
                    >,
                >::new();
                for f in o.fields.values() {
                    acc = match &f.ty {
                        types::FieldType::Ref { target, .. } => {
                            let ids = support::concat(
                                &reference_held(&reach.subject.old, &f.id),
                                &reference_held(&reach.subject.new, &f.id),
                            );
                            if ids.iter().all(|i| {
                                covers(
                                    &reach.coverage,
                                    &types::Need::Record {
                                        object: target.clone(),
                                        id: i.clone(),
                                    },
                                )
                            }) {
                                {
                                    let mut map_ = acc.clone();
                                    map_.insert(format!("{}", f.id.0), {
                                        let mut held: std::collections::BTreeMap<
                                            String,
                                            std::collections::BTreeMap<String, types::Value>,
                                        > = std::collections::BTreeMap::<
                                            String,
                                            std::collections::BTreeMap<String, types::Value>,
                                        >::new();
                                        for i in ids.iter() {
                                            held = match reach.tenant.records.get(target) {
                                                Some(rs) => match rs.get(i) {
                                                    Some(t) => {
                                                        let mut map_ = held.clone();
                                                        map_.insert(
                                                            format!("{}", i.0),
                                                            record_scope(std::sync::Arc::as_ref(
                                                                t,
                                                            ))?,
                                                        );
                                                        map_
                                                    }
                                                    None => held.clone(),
                                                },
                                                None => held.clone(),
                                            };
                                        }
                                        held
                                    });
                                    map_
                                }
                            } else {
                                acc.clone()
                            }
                        }
                        _ => acc.clone(),
                    };
                }
                acc
            }
        },
    })
}

/// crates/kernel/src/expr.rs missing / first_missing: the first record, in the order the expression is written, that a reference the expression follows points at and the snapshot does not cover; none when every reference it can follow is covered. A reference is followed as eval follows it: from a single reference field of the scope's record; where eval could not follow it (no record in the scope, a null or non-reference value, a field that is not a single reference) there is no need. rules.rs authorize_needing asks it of a condition that failed to evaluate, so a decision never rests on a record that was merely not loaded. Structural recursion: every call of itself is on a field of a variant matched from e, or an item of a list such a field holds.
///
/// Specification function `rule-missing`.
pub fn rule_missing(e: &types::Expr, reach: &types::RuleReach) -> Option<types::Need> {
    match e {
        types::Expr::Through(s, f, _) => match scope_record(&reach.subject, s) {
            None => None,
            Some(r) => match r.fields.get(&types::FieldId(f.clone())) {
                None => None,
                Some(v) => match v {
                    types::Value::Ref(target) => {
                        match single_reference(
                            std::sync::Arc::as_ref(&reach.tenant.schema),
                            &r.object,
                            f,
                        ) {
                            Some(object) => {
                                if covers(
                                    &reach.coverage,
                                    &types::Need::Record {
                                        object: object.clone(),
                                        id: target.clone(),
                                    },
                                ) {
                                    None
                                } else {
                                    Some(types::Need::Record {
                                        object: object.clone(),
                                        id: target.clone(),
                                    })
                                }
                            }
                            None => None,
                        }
                    }
                    _ => None,
                },
            },
        },
        types::Expr::Not(a) => rule_missing(&(**a), reach),
        types::Expr::IsNull(a) => rule_missing(&(**a), reach),
        types::Expr::Len(a) => rule_missing(&(**a), reach),
        types::Expr::Lower(a) => rule_missing(&(**a), reach),
        types::Expr::IsSlug(a) => rule_missing(&(**a), reach),
        types::Expr::Text(a) => rule_missing(&(**a), reach),
        types::Expr::Duration(_, amount) => rule_missing(&(**amount), reach),
        types::Expr::And(items) => items.iter().fold(None, |found, i| {
            if found.is_some() {
                found.clone()
            } else {
                rule_missing(i, reach)
            }
        }),
        types::Expr::Or(items) => items.iter().fold(None, |found, i| {
            if found.is_some() {
                found.clone()
            } else {
                rule_missing(i, reach)
            }
        }),
        types::Expr::Cmp(_, left, right) => {
            let x = rule_missing(&(**left), reach);
            if x.is_some() {
                x.clone()
            } else {
                rule_missing(&(**right), reach)
            }
        }
        types::Expr::In(item, l) => {
            let x = rule_missing(&(**item), reach);
            if x.is_some() {
                x.clone()
            } else {
                rule_missing(&(**l), reach)
            }
        }
        types::Expr::Contains(haystack, needle) => {
            let x = rule_missing(&(**haystack), reach);
            if x.is_some() {
                x.clone()
            } else {
                rule_missing(&(**needle), reach)
            }
        }
        types::Expr::StartsWith(t, prefix) => {
            let x = rule_missing(&(**t), reach);
            if x.is_some() {
                x.clone()
            } else {
                rule_missing(&(**prefix), reach)
            }
        }
        types::Expr::Arith(_, left, right) => {
            let x = rule_missing(&(**left), reach);
            if x.is_some() {
                x.clone()
            } else {
                rule_missing(&(**right), reach)
            }
        }
        types::Expr::MsBetween(a, b) => {
            let x = rule_missing(&(**a), reach);
            if x.is_some() {
                x.clone()
            } else {
                rule_missing(&(**b), reach)
            }
        }
        types::Expr::Concat(left, right) => {
            let x = rule_missing(&(**left), reach);
            if x.is_some() {
                x.clone()
            } else {
                rule_missing(&(**right), reach)
            }
        }
        types::Expr::If(c, a, b) => {
            let y = rule_missing(&(**c), reach);
            if y.is_some() {
                y.clone()
            } else {
                {
                    let x = rule_missing(&(**a), reach);
                    if x.is_some() {
                        x.clone()
                    } else {
                        rule_missing(&(**b), reach)
                    }
                }
            }
        }
        _ => None,
    }
}

/// crates/kernel/src/rules.rs authorize_needing: authorize with the snapshot's lookup when coverage is given (the coverage of the snapshot the decision is made on), and none when it is not. A condition follows a reference through rule-lookup; a condition that fails to evaluate denies, as in authorize, and the first record such a condition needs that the snapshot does not cover is needed, so the caller answers InsufficientState naming it rather than deny on a record that was merely not loaded. needed is none when the decision is allowed.
///
/// Specification function `authorize-needing`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn authorize_needing(
    tenant: &types::TenantState,
    schema: &types::TenantSchema,
    principal: &types::Principal,
    now: crate::prelude::Timestamp,
    action: &types::Action,
    resource: &types::Resource,
    subject: &types::Subject,
    coverage: &Option<types::Coverage>,
) -> Result<types::PolicyDecision, Fault> {
    let roles = roles_of(tenant, principal);
    let what = request_text(action, resource);
    Ok(if roles.iter().any(|r| r.0 == "owner") {
        types::PolicyDecision {
            allowed: true,
            checks: vec![types::PolicyCheck {
                rule: "policy:builtin_owner".to_string(),
                passed: true,
                what: what.clone(),
                outcome: types::PolicyOutcome::Owner,
                condition: None,
            }],
            needed: None,
        }
    } else if match resource {
        types::Resource::Object(_) => effective_permissions(tenant, principal)
            .iter()
            .any(|g| grant_allows(g, action, resource)),
        _ => false,
    } {
        types::PolicyDecision {
            allowed: true,
            checks: vec![types::PolicyCheck {
                rule: "permission:role".to_string(),
                passed: true,
                what: what.clone(),
                outcome: types::PolicyOutcome::Unconditional,
                condition: None,
            }],
            needed: None,
        }
    } else {
        {
            let env = types::ExprEnv {
                record: scope_of(
                    &(if subject.old.is_none() {
                        subject.new.clone()
                    } else {
                        subject.old.clone()
                    }),
                )?,
                old: scope_of(&subject.old)?,
                new: scope_of(&subject.new)?,
                param: std::collections::BTreeMap::<String, types::Value>::new(),
                now: types::Value::Time(now.0),
                principal: match principal {
                    types::Principal::User(id) => types::Value::Str(id.clone().0),
                    _ => null_value(),
                },
                has_role: roles
                    .clone()
                    .into_iter()
                    .map(|item_| item_.0)
                    .collect::<Vec<_>>(),
            };
            {
                let reach = match coverage {
                    Some(cv) => Some(types::RuleReach {
                        tenant: tenant.clone(),
                        coverage: cv.clone(),
                        subject: subject.clone(),
                    }),
                    None => None,
                };
                {
                    let lookup = match &reach {
                        Some(r) => rule_lookup(r)?,
                        None => std::collections::BTreeMap::<
                            String,
                            std::collections::BTreeMap<
                                String,
                                std::collections::BTreeMap<String, types::Value>,
                            >,
                        >::new(),
                    };
                    {
                        let state = schema.policies.values().fold(
                            types::PolicyProgress {
                                granted: None,
                                checks: Vec::<types::PolicyCheck>::new(),
                                needed: None,
                            },
                            |acc, p| {
                                if acc.granted.is_some()
                                    || !policy_applies(p, &roles, action, resource)
                                {
                                    acc.clone()
                                } else {
                                    policy_step(p, &env, &acc, &what, &lookup, &reach)
                                }
                            },
                        );
                        match &state.granted {
                            Some(c) => types::PolicyDecision {
                                allowed: true,
                                checks: vec![c.clone()],
                                needed: None,
                            },
                            None => types::PolicyDecision {
                                allowed: false,
                                checks: if state.checks.is_empty() {
                                    vec![types::PolicyCheck {
                                        rule: "policy:none".to_string(),
                                        passed: false,
                                        what: what.clone(),
                                        outcome: types::PolicyOutcome::NoPolicy,
                                        condition: None,
                                    }]
                                } else {
                                    state.checks.clone()
                                },
                                needed: state.needed.clone(),
                            },
                        }
                    }
                }
            }
        }
    })
}

/// automation.rs automation_roles: the roles of the principal automation:<workflow-id> under a schema: exactly the run-as roles of its automation, and none when the schema holds no such automation or the automation is suspended (WFL-1527, WFL-1529). The principal id is compared with the text automation:<id> of each automation the schema holds, because the body language has no substring; the automation principal holds no public role and none of the table of members.
///
/// Specification function `automation-roles`.
pub fn automation_roles(
    schema: &types::TenantSchema,
    id: &types::PrincipalId,
) -> std::collections::BTreeSet<types::RoleId> {
    automations_of(schema).values().fold(
        std::collections::BTreeSet::<types::RoleId>::new(),
        |acc, def| {
            if format!("automation:{}", def.id.0) == id.0 && def.suspended_for.is_none() {
                def.run_as.roles.clone()
            } else {
                acc.clone()
            }
        },
    )
}

/// triggers.rs detail: a detail of at most 256 characters (rec-automation-exception.detail).
///
/// Specification function `trigger-detail`.
pub fn trigger_detail(text: &String) -> String {
    if u64::try_from(text.as_str().chars().count()).unwrap_or(u64::MAX) <= 256 {
        text.clone()
    } else {
        text.as_str()
            .chars()
            .map(String::from)
            .collect::<Vec<_>>()
            .iter()
            .take(256)
            .cloned()
            .collect::<Vec<_>>()
            .iter()
            .fold("".to_string(), |a, c| format!("{a}{c}"))
    }
}

/// triggers.rs fired: the workflow transitions a record-updated event says it fired, in workflow id order.
///
/// Specification function `fired-transitions`.
pub fn fired_transitions(
    transitions: &Option<std::collections::BTreeMap<types::WorkflowId, String>>,
) -> Vec<String> {
    match transitions {
        Some(m) => m.values().cloned().collect::<Vec<_>>(),
        None => Vec::<String>::new(),
    }
}

/// triggers.rs matches (D-6522, D-7200): whether the event a trigger subscribes to matches a domain event: the kind and the object type and, for record-updated naming a transition, a transition the update fired (D-7203). The other trigger events come from engines outside the kernel and match no kernel event.
///
/// Specification function `trigger-matches`.
pub fn trigger_matches(on: &types::TriggerEvent, body: &types::EventBody) -> bool {
    match on {
        types::TriggerEvent::RecordCreated { object } => match body {
            types::EventBody::RecordCreated { record } => record.object == *object,
            _ => false,
        },
        types::TriggerEvent::RecordUpdated { object, transition } => match body {
            types::EventBody::RecordUpdated {
                after, transitions, ..
            } => {
                after.object == *object
                    && (match transition {
                        None => true,
                        Some(name) => fired_transitions(transitions).iter().any(|t| *t == *name),
                    })
            }
            _ => false,
        },
        types::TriggerEvent::RecordDeleted { object } => match body {
            types::EventBody::RecordDeleted { before } => before.object == *object,
            _ => false,
        },
        _ => false,
    }
}

/// triggers.rs event_params (D-6523): the parameters an event binds for a trigger: seq, at and hop, and for record-updated transition: the transition the trigger names, else the first the update fired in workflow id order, else null. (event-params lists the names, for the check of a definition.)
///
/// Specification function `event-bound-params`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn event_bound_params(
    event: &types::DomainEvent,
    hop: u32,
    on: &types::TriggerEvent,
) -> Result<std::collections::BTreeMap<String, types::Value>, Fault> {
    Ok({
        let base = {
            let mut map_ = {
                let mut map_ = {
                    let mut map_ = std::collections::BTreeMap::<String, types::Value>::new();
                    map_.insert(
                        "seq".to_string(),
                        types::Value::Int(
                            i64::try_from(event.seq).map_err(|_| Fault { op: "as" })?,
                        ),
                    );
                    map_
                };
                map_.insert("at".to_string(), types::Value::Time(event.at.0));
                map_
            };
            map_.insert("hop".to_string(), types::Value::Int(i64::from(hop)));
            map_
        };
        match &event.body {
            types::EventBody::RecordUpdated { transitions, .. } => {
                let mut map_ = base.clone();
                map_.insert(
                    "transition".to_string(),
                    match match on {
                        types::TriggerEvent::RecordUpdated {
                            transition: named, ..
                        } => match named {
                            Some(n) => Some(n.clone()),
                            None => fired_transitions(transitions).get(0).cloned(),
                        },
                        _ => fired_transitions(transitions).get(0).cloned(),
                    } {
                        Some(n) => types::Value::Str(n.clone()),
                        None => types::Value::Null,
                    },
                );
                map_
            }
            _ => base.clone(),
        }
    })
}

/// canon.rs canonical_json of a value that is not a list: the externally tagged JSON of strata_kernel::Value ("Null", {"Bool":true}, {"Int":5}, {"Str":"x"}, {"Time":5}, {"Ref":7}), a string written as serde_json writes it. A list gives the empty text here.
///
/// Specification function `value-canonical-leaf`.
pub fn value_canonical_leaf(v: &types::Value) -> String {
    match v {
        types::Value::Null => "\"Null\"".to_string(),
        types::Value::Bool(b) => {
            format!("{}}}", format!("{{\"Bool\":{}", format!("{b}")))
        }
        types::Value::Int(n) => format!("{}}}", format!("{{\"Int\":{}", format!("{n}"))),
        types::Value::Str(s) => {
            format!(
                "{}}}",
                format!(
                    "{{\"Str\":{}",
                    format!("{}", serde_json::to_string(s).unwrap_or_default())
                )
            )
        }
        types::Value::Time(t) => {
            format!("{}}}", format!("{{\"Time\":{}", format!("{t}")))
        }
        types::Value::Ref(r) => {
            format!("{}}}", format!("{{\"Ref\":{}", format!("{}", r.0)))
        }
        types::Value::List(_) => "".to_string(),
    }
}

/// canon.rs canonical_json of a value (triggers.rs hashes it for the run key, D-6534): a list is {"List":[item,item]}. A list holding a list is written one level deep only, because the body language has no recursion; a run key is a scalar or a list of scalars.
///
/// Specification function `value-canonical-json`.
pub fn value_canonical_json(v: &types::Value) -> String {
    match v {
        types::Value::List(items) => {
            format!(
                "{}]}}",
                format!(
                    "{{\"List\":[{}",
                    items.iter().fold("".to_string(), |acc, i| if acc == "" {
                        value_canonical_leaf(i)
                    } else {
                        format!("{}{}", format!("{acc},"), value_canonical_leaf(i))
                    })
                )
            )
        }
        _ => value_canonical_leaf(v),
    }
}

/// triggers.rs scopes: the scopes of an event as the automation principal may observe them: none when it may not read the record the event leaves (the record created, the record after an update, the record deleted), so the trigger does not observe the event; the scope old of an update only when it may read the record as it was (D-7201). Visibility is the read decision of visible, which follows no reference (difference 2 of the differential).
///
/// Specification function `trigger-scopes-of`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn trigger_scopes_of(
    t: &types::TenantState,
    principal: &types::Principal,
    now: crate::prelude::Timestamp,
    body: &types::EventBody,
) -> Result<Option<types::TriggerScopes>, Fault> {
    Ok(match body {
        types::EventBody::RecordCreated { record } => {
            if visible(t, principal, std::sync::Arc::as_ref(record), now)? {
                Some(types::TriggerScopes {
                    record: Some(<types::Record as Clone>::clone(record)),
                    old: None,
                    new: Some(<types::Record as Clone>::clone(record)),
                })
            } else {
                None
            }
        }
        types::EventBody::RecordUpdated { before, after, .. } => {
            if visible(t, principal, std::sync::Arc::as_ref(after), now)? {
                Some(types::TriggerScopes {
                    record: None,
                    old: if visible(t, principal, std::sync::Arc::as_ref(before), now)? {
                        Some(<types::Record as Clone>::clone(before))
                    } else {
                        None
                    },
                    new: Some(<types::Record as Clone>::clone(after)),
                })
            } else {
                None
            }
        }
        types::EventBody::RecordDeleted { before } => {
            if visible(t, principal, std::sync::Arc::as_ref(before), now)? {
                Some(types::TriggerScopes {
                    record: None,
                    old: Some(<types::Record as Clone>::clone(before)),
                    new: None,
                })
            } else {
                None
            }
        }
        _ => None,
    })
}

/// The tenant schema with its automations replaced (the other members as they were).
///
/// Specification function `schema-with-automations`.
pub fn schema_with_automations(
    schema: &types::TenantSchema,
    automations: &std::collections::BTreeMap<types::WorkflowId, types::AutomationDef>,
) -> types::TenantSchema {
    types::TenantSchema {
        version: schema.version.clone(),
        objects: schema.objects.clone(),
        roles: schema.roles.clone(),
        role_permissions: schema.role_permissions.clone(),
        teams: schema.teams.clone(),
        invitations: schema.invitations.clone(),
        policies: schema.policies.clone(),
        workflows: schema.workflows.clone(),
        queries: schema.queries.clone(),
        views: schema.views.clone(),
        triggers: schema.triggers.clone(),
        automations: Some(automations.clone()),
        operations: schema.operations.clone(),
        settings: schema.settings.clone(),
        capabilities: schema.capabilities.clone(),
        ledger: schema.ledger.clone(),
        mail_templates: schema.mail_templates.clone(),
        notice_templates: schema.notice_templates.clone(),
        tokens: schema.tokens.clone(),
        products: schema.products.clone(),
        ui: schema.ui.clone(),
    }
}

/// triggers.rs lost_authority: the automations of a tenant (a state after a change) whose definer may no longer confer a role of their run-as under ADM-152, in id order (WFL-1529, CT-798): for each, the first role of the run-as, in id order, that may-confer refuses, and its detail. An automation that is already suspended, or that has no definer, is not checked.
///
/// Specification function `lost-authorities`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn lost_authorities(tenant: &types::TenantState) -> Result<Vec<types::LostAuthority>, Fault> {
    Ok({
        let mut acc: Vec<types::LostAuthority> = Vec::<types::LostAuthority>::new();
        for def in automations_of(std::sync::Arc::as_ref(&tenant.schema)).values() {
            acc = match &def.suspended_for {
                Some(_) => acc.clone(),
                None => match &def.defined_by {
                    None => acc.clone(),
                    Some(definer) => {
                        match {
                            let mut found_ = None;
                            for r in def.run_as.roles.iter() {
                                if !may_confer(tenant, &types::Principal::User(definer.clone()), r)?
                                    .passed
                                {
                                    found_ = Some(r.clone());
                                    break;
                                }
                            }
                            found_
                        } {
                            None => acc.clone(),
                            Some(role) => support::concat(
                                &acc,
                                &[types::LostAuthority {
                                    automation: def.id.clone(),
                                    definer: definer.clone(),
                                    role: role.clone(),
                                    detail: may_confer(
                                        tenant,
                                        &types::Principal::User(definer.clone()),
                                        &role,
                                    )?
                                    .detail,
                                }],
                            ),
                        }
                    }
                },
            };
        }
        acc
    })
}

/// The leading Publish effects of a list of effects, and the others: triggers.rs append_events places the Publish effect of an event it appends after the Publish effects already there.
///
/// Specification function `split-publishes`.
pub fn split_publishes(effects: &Vec<types::Effect>) -> types::LeadEffects {
    effects.iter().fold(
        types::LeadEffects {
            lead: Vec::<types::Effect>::new(),
            rest: Vec::<types::Effect>::new(),
            open: true,
        },
        |acc, e| {
            if acc.open {
                match e {
                    types::Effect::Publish { .. } => types::LeadEffects {
                        lead: support::concat(&acc.lead, &[e.clone()]),
                        rest: Vec::<types::Effect>::new(),
                        open: true,
                    },
                    _ => types::LeadEffects {
                        lead: acc.lead.clone(),
                        rest: vec![e.clone()],
                        open: false,
                    },
                }
            } else {
                types::LeadEffects {
                    lead: acc.lead.clone(),
                    rest: support::concat(&acc.rest, &[e.clone()]),
                    open: false,
                }
            }
        },
    )
}

/// triggers.rs suspend_lost: for every automation whose definer lost the authority to confer a role of its run-as (lost-authority), in the state after the change and in the transition (D-7204, WFL-1529): the automation is marked suspended-for the role; a PutSchema op with the schema, an AutomationSuspended event numbered after the last event of the transition (stamped with the new revision, the time, principal and correlation of the context) and its Publish effect placed after the Publish effects already there, and a passing automation:<id>:suspended check naming the definer, the role and the conferral check. Without a loss it changes nothing.
///
/// Specification function `suspend-lost`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn suspend_lost(
    after: &types::TenantState,
    ctx: &types::Context,
    result: &types::TransitionResult,
    lost: &Vec<types::LostAuthority>,
) -> Result<types::TriggerSuspension, Fault> {
    Ok(if lost.is_empty() {
        types::TriggerSuspension {
            after: after.clone(),
            result: result.clone(),
        }
    } else {
        {
            let schema2 = schema_with_automations(
                std::sync::Arc::as_ref(&after.schema),
                &automations_of(std::sync::Arc::as_ref(&after.schema))
                    .values()
                    .fold(
                        std::collections::BTreeMap::<types::WorkflowId, types::AutomationDef>::new(
                        ),
                        |m, def| {
                            let mut map_ = m.clone();
                            map_.insert(
                                def.id.clone(),
                                match lost.iter().find(|&l| l.automation == def.id) {
                                    Some(l) => types::AutomationDef {
                                        id: def.id.clone(),
                                        label: def.label.clone(),
                                        run_as: def.run_as.clone(),
                                        run_key: def.run_key.clone(),
                                        start: def.start.clone(),
                                        steps: def.steps.clone(),
                                        defined_by: def.defined_by.clone(),
                                        defined_at: def.defined_at,
                                        suspended_for: Some(l.role.clone()),
                                        state: None,
                                    },
                                    None => def.clone(),
                                },
                            );
                            map_
                        },
                    ),
            );
            {
                let numbered = {
                    let mut acc: types::EventNumbering = types::EventNumbering {
                        events: result.events.clone(),
                        next: result
                            .delta
                            .event_seq
                            .checked_add(1)
                            .ok_or(Fault { op: "+" })?,
                    };
                    for l in lost.iter() {
                        acc = types::EventNumbering {
                            events: support::concat(
                                &acc.events,
                                &[types::DomainEvent {
                                    tenant: result.delta.tenant.clone(),
                                    seq: acc.next,
                                    revision: result.delta.new_revision.clone(),
                                    at: ctx.now,
                                    principal: ctx.principal.clone(),
                                    correlation: ctx.correlation.clone(),
                                    body: types::EventBody::AutomationSuspended {
                                        automation: l.automation.clone(),
                                        definer: l.definer.clone(),
                                        role: l.role.clone(),
                                    },
                                }],
                            ),
                            next: acc.next.checked_add(1).ok_or(Fault { op: "+" })?,
                        };
                    }
                    acc
                };
                {
                    let split = split_publishes(&result.effects);
                    types::TriggerSuspension {
                        after: types::TenantState {
                            id: after.id.clone(),
                            name: after.name.clone(),
                            revision: after.revision.clone(),
                            next_record: after.next_record,
                            event_seq: after.event_seq,
                            schema: std::sync::Arc::new(schema2.clone()),
                            members: after.members.clone(),
                            records: after.records.clone(),
                            setting_values: after.setting_values.clone(),
                            ledger: after.ledger.clone(),
                        },
                        result: types::TransitionResult {
                            delta: types::StateDelta {
                                tenant: result.delta.tenant.clone(),
                                base_revision: result.delta.base_revision.clone(),
                                new_revision: result.delta.new_revision.clone(),
                                next_record: result.delta.next_record,
                                event_seq: numbered.next.checked_sub(1).ok_or(Fault { op: "-" })?,
                                ops: support::concat(
                                    &result.delta.ops,
                                    &[types::DeltaOp::PutSchema(std::sync::Arc::new(
                                        schema2.clone(),
                                    ))],
                                ),
                            },
                            events: numbered.events.clone(),
                            effects: support::concat(
                                &support::concat(
                                    &split.lead,
                                    &numbered
                                        .events
                                        .iter()
                                        .filter(|&e| e.seq > result.delta.event_seq)
                                        .cloned()
                                        .collect::<Vec<_>>()
                                        .iter()
                                        .map(|e| types::Effect::Publish { seq: e.seq })
                                        .collect::<Vec<_>>(),
                                ),
                                &split.rest,
                            ),
                            evidence: support::concat(
                                &result.evidence,
                                &lost
                                    .iter()
                                    .map(|l| types::Check {
                                        rule: format!("automation:{}:suspended", l.automation.0),
                                        passed: true,
                                        detail: trigger_detail(&format!(
                                            "definer {} may no longer confer role {}: {}",
                                            l.definer.0, l.role.0, l.detail
                                        )),
                                    })
                                    .collect::<Vec<_>>(),
                            ),
                            output: result.output.clone(),
                        },
                    }
                }
            }
        }
    })
}

/// triggers.rs decide, the decline closure: the effect decline-automation for a trigger that matched an event and starts no run for a recorded reason (SCH-1532), with a detail of at most 256 characters.
///
/// Specification function `trigger-decline`.
pub fn trigger_decline(
    trigger: &types::TriggerDef,
    event: &types::DomainEvent,
    hop: u32,
    reason: &types::AutomationExceptionReason,
    text: &String,
) -> types::Effect {
    types::Effect::DeclineAutomation(types::AutomationDecline {
        trigger: trigger.id.clone(),
        automation: trigger.automation.clone(),
        event_seq: event.seq,
        hop,
        reason: reason.clone(),
        detail: trigger_detail(text),
    })
}

/// triggers.rs decide, the start: the effect start-automation handed to the automation worker for a run to start (D-7200): the trigger and its automation, the event sequence and hop, the automation principal its steps act as (caused-by, WFL-1530), the definer whose authority bounds it, the schema version the run starts on, the canonical JSON of the run key value when the automation declares one (the kernel writes its SHA-256 in hexadecimal, D-6534: the function language has no hash, so the differential hashes this text) and the parameters the event binds.
///
/// Specification function `trigger-start`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn trigger_start(
    after: &types::TenantState,
    a: &types::AutomationDef,
    trigger: &types::TriggerDef,
    event: &types::DomainEvent,
    hop: u32,
    params: &std::collections::BTreeMap<String, types::Value>,
    run_key: &Option<String>,
) -> Result<types::Effect, Fault> {
    Ok(types::Effect::StartAutomation(types::AutomationStart {
        trigger: trigger.id.clone(),
        automation: a.id.clone(),
        event_seq: event.seq,
        hop,
        caused_by: types::PrincipalId::new(format!("automation:{}", a.id.0))
            .map_err(|_| Fault { op: "new" })?,
        on_behalf_of: a.defined_by.clone(),
        definition_version: after.schema.version.clone(),
        run_key: run_key.clone(),
        params: params.clone(),
    }))
}

/// triggers.rs decide, after the checks of the automation: the condition of the trigger, the hop limit and the run key, in that order. A condition that is false appends nothing (D-6530); one that cannot be evaluated declines with condition-failed (the condition of trigger <id> cannot be evaluated); a hop past 8 declines with hop-limit; a run key that is null or cannot be evaluated declines with condition-failed; otherwise the run starts (trigger-start). The condition and the run key are evaluated as the automation principal automation:<id>, with its run-as roles and no others (D-6525, D-7201), over the scopes the event binds and the parameters of event-bound-params. Not mirrored: the check of what the principal may not read (a condition or run key that reads a field whose read rule hides it declines with condition-failed), which walks the expression and so needs a recursion specc refuses, and the InsufficientState of a record a condition follows to (difference 2); the differential guards both.
///
/// Specification function `decide-run`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn decide_run(
    after: &types::TenantState,
    ctx: &types::Context,
    hop: u32,
    event: &types::DomainEvent,
    trigger: &types::TriggerDef,
    a: &types::AutomationDef,
    s: &types::TriggerScopes,
) -> Result<Option<types::Effect>, Fault> {
    let pid = format!("automation:{}", a.id.0);
    let params = event_bound_params(event, hop, &trigger.on)?;
    let env = types::ExprEnv {
        record: match &s.record {
            Some(r) => Some(record_scope(r)?),
            None => None,
        },
        old: match &s.old {
            Some(r) => Some(record_scope(r)?),
            None => None,
        },
        new: match &s.new {
            Some(r) => Some(record_scope(r)?),
            None => None,
        },
        param: params.clone(),
        now: types::Value::Time(ctx.now.0),
        principal: types::Value::Str(pid.clone()),
        has_role: roles_of(
            after,
            &types::Principal::User(
                types::PrincipalId::new(pid.clone()).map_err(|_| Fault { op: "new" })?,
            ),
        )
        .into_iter()
        .map(|item_| item_.0)
        .collect::<Vec<_>>(),
    };
    let cond: i64 = match &trigger.condition {
        None => 1,
        Some(c) => match support::eval_tenant_rule_language_expr_env(c, &env) {
            Ok(v) => {
                if v == types::Value::Bool(true) {
                    1
                } else {
                    0
                }
            }
            Err(_) => 2,
        },
    };
    Ok(if cond == 0 {
        None
    } else {
        Some(if cond == 2 {
            trigger_decline(
                trigger,
                event,
                hop,
                &types::AutomationExceptionReason::ConditionFailed,
                &format!(
                    "the condition of trigger {} cannot be evaluated",
                    trigger.id.0
                ),
            )
        } else if hop > 8 {
            trigger_decline(
                trigger,
                event,
                hop,
                &types::AutomationExceptionReason::HopLimit,
                &format!("hop {hop} is past the hop limit of 8"),
            )
        } else {
            match &a.run_key {
                None => trigger_start(after, a, trigger, event, hop, &params, &None)?,
                Some(key) => match support::eval_tenant_rule_language_expr_env(key, &env) {
                    Ok(v) => match &v {
                        types::Value::Null => trigger_decline(
                            trigger,
                            event,
                            hop,
                            &types::AutomationExceptionReason::ConditionFailed,
                            &format!("the run key of automation {} is null", a.id.0),
                        ),
                        _ => trigger_start(
                            after,
                            a,
                            trigger,
                            event,
                            hop,
                            &params,
                            &Some(value_canonical_json(&v)),
                        )?,
                    },
                    Err(_) => trigger_decline(
                        trigger,
                        event,
                        hop,
                        &types::AutomationExceptionReason::ConditionFailed,
                        &format!("the run key of automation {} cannot be evaluated", a.id.0),
                    ),
                },
            }
        })
    })
}

/// triggers.rs decide: one trigger whose event matches an event, in the state after the transition: the effect it appends, or none (D-7200). In order: a paused trigger appends nothing; a missing automation declines with automation-removed and a suspended one with run-as-suspended, whatever the condition; an event about a record the automation principal may not read appends nothing (trigger-scopes-of); then decide-run.
///
/// Specification function `decide-trigger`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn decide_trigger(
    after: &types::TenantState,
    ctx: &types::Context,
    hop: u32,
    event: &types::DomainEvent,
    trigger: &types::TriggerDef,
) -> Result<Option<types::Effect>, Fault> {
    Ok(
        if match trigger.paused {
            Some(p) => p,
            None => false,
        } {
            None
        } else {
            match automations_of(std::sync::Arc::as_ref(&after.schema)).get(&trigger.automation) {
                None => Some(trigger_decline(
                    trigger,
                    event,
                    hop,
                    &types::AutomationExceptionReason::AutomationRemoved,
                    &format!("automation {} does not exist", trigger.automation.0),
                )),
                Some(a) => match &a.suspended_for {
                    Some(role) => Some(trigger_decline(
                        trigger,
                        event,
                        hop,
                        &types::AutomationExceptionReason::RunAsSuspended,
                        &format!(
                            "automation {} is suspended: its definer may not confer role {}",
                            a.id.0, role.0
                        ),
                    )),
                    None => {
                        match trigger_scopes_of(
                            after,
                            &types::Principal::User(
                                types::PrincipalId::new(format!("automation:{}", a.id.0))
                                    .map_err(|_| Fault { op: "new" })?,
                            ),
                            ctx.now,
                            &event.body,
                        )? {
                            None => None,
                            Some(s) => decide_run(after, ctx, hop, event, trigger, a, &s)?,
                        }
                    }
                },
            }
        },
    )
}

/// triggers.rs after_decision, past the gate: the state after the transition (apply-delta); when the transition changed members or the schema (authority-changed), the suspension of the automations whose definer lost authority (suspend-lost of lost-authorities); then, for each event of the transition in sequence order, the AutomationSuspended events included, and each trigger of the state after the suspension whose event matches it, in trigger id order, the effect decide-trigger gives, appended to the effects (D-7200). The hop of the decisions is the hop of the context, none being zero.
///
/// Specification function `after-decision-run`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn after_decision_run(
    t: &types::TenantState,
    ctx: &types::Context,
    result: &types::TransitionResult,
    authority_changed: bool,
) -> Result<types::TransitionResult, Failure<types::Rejection>> {
    Ok({
        let after0 = apply_delta(&Some(t.clone()), &result.delta).map_err(Failure::Error)?;
        {
            let sus = suspend_lost(
                &after0,
                ctx,
                result,
                &(if authority_changed {
                    lost_authorities(&after0).map_err(Failure::Fault)?
                } else {
                    Vec::<types::LostAuthority>::new()
                }),
            )
            .map_err(Failure::Fault)?;
            {
                let hop = match ctx.hop {
                    Some(h) => h,
                    None => 0,
                };
                {
                    let effects = {
                        let mut acc: Vec<types::Effect> = Vec::<types::Effect>::new();
                        for e in sus.result.events.iter() {
                            acc = support::concat(
                                &acc,
                                &({
                                    let mut found: Vec<types::Effect> = Vec::<types::Effect>::new();
                                    for tr in triggers_of(std::sync::Arc::as_ref(&sus.after.schema))
                                        .values()
                                    {
                                        found = if trigger_matches(&tr.on, &e.body) {
                                            match decide_trigger(&sus.after, ctx, hop, e, tr)
                                                .map_err(Failure::Fault)?
                                            {
                                                Some(f) => support::concat(&found, &[f.clone()]),
                                                None => found.clone(),
                                            }
                                        } else {
                                            found.clone()
                                        };
                                    }
                                    found
                                }),
                            );
                        }
                        acc
                    };
                    types::TransitionResult {
                        delta: sus.result.delta.clone(),
                        events: sus.result.events.clone(),
                        effects: support::concat(&sus.result.effects, &effects),
                        evidence: sus.result.evidence.clone(),
                        output: sus.result.output.clone(),
                    }
                }
            }
        }
    })
}

/// triggers.rs after_decision: what the kernel adds to an accepted transition once its events are final (D-7200, D-7204): the suspensions of automations whose definer lost authority and the effect of each trigger that matches an event of the transition (after-decision-run). A transition that changed neither members nor the schema and matches no trigger that is not paused is returned as it is.
///
/// Specification function `after-decision`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn after_decision(
    t: &types::TenantState,
    ctx: &types::Context,
    result: &types::TransitionResult,
) -> Result<types::TransitionResult, Failure<types::Rejection>> {
    let authority_changed = result.delta.ops.iter().any(|op| match op {
        types::DeltaOp::PutSchema(_) => true,
        types::DeltaOp::PutMember { .. } => true,
        _ => false,
    });
    let triggered = triggers_of(std::sync::Arc::as_ref(&t.schema))
        .values()
        .any(|tr| {
            (match tr.paused {
                Some(p) => !p,
                None => true,
            }) && result
                .events
                .iter()
                .any(|e| trigger_matches(&tr.on, &e.body))
        });
    Ok(if !authority_changed && !triggered {
        result.clone()
    } else {
        after_decision_run(t, ctx, result, authority_changed)?
    })
}

/// triggers.rs stamp_definitions: the changes of a schema change with every definition of a trigger or an automation stamped with who defined it and when, from the context and never from the input (D-7204, WFL-2201): defined-by is the acting person (none for the system or an anonymous caller), defined-at the time of the context. An automation defined again is no longer suspended: the change that defines it checks that its definer may confer every run-as role before it is accepted (WFL-1528), which is what lifts a suspension (D-6526).
///
/// Specification function `stamp-definitions`.
pub fn stamp_definitions(
    changes: &Vec<types::SchemaChange>,
    ctx: &types::Context,
) -> Vec<types::SchemaChange> {
    let definer = match &ctx.principal {
        types::Principal::User(id) => Some(id.clone()),
        _ => None,
    };
    changes
        .iter()
        .map(|c| match c {
            types::SchemaChange::DefineTrigger(t) => {
                types::SchemaChange::DefineTrigger(types::TriggerDef {
                    id: t.id.clone(),
                    on: t.on.clone(),
                    condition: t.condition.clone(),
                    automation: t.automation.clone(),
                    paused: t.paused,
                    defined_by: definer.clone(),
                    defined_at: Some(ctx.now),
                })
            }
            types::SchemaChange::DefineAutomation(a) => {
                types::SchemaChange::DefineAutomation(types::AutomationDef {
                    id: a.id.clone(),
                    label: a.label.clone(),
                    run_as: a.run_as.clone(),
                    run_key: a.run_key.clone(),
                    start: a.start.clone(),
                    steps: a.steps.clone(),
                    defined_by: definer.clone(),
                    defined_at: Some(ctx.now),
                    suspended_for: None,
                    state: None,
                })
            }
            _ => c.clone(),
        })
        .collect::<Vec<_>>()
}

/// settings.rs rank: the place of a level from the least to the most specific.
///
/// Specification function `setting-rank`.
pub fn setting_rank(level: &types::SettingLevel) -> u64 {
    match level {
        types::SettingLevel::Platform => 0,
        types::SettingLevel::Tenant => 1,
        types::SettingLevel::Team => 2,
        types::SettingLevel::Person => 3,
    }
}

/// settings.rs is_open: whether the definition lets a level hold an override that is read: the definition allows the level and no lock closes it. A lock of the platform leaves the platform level and a lock of the tenant leaves the platform and tenant levels (D-5043).
///
/// Specification function `setting-open`.
pub fn setting_open(def: &types::SettingDef, level: &types::SettingLevel) -> bool {
    def.levels.iter().any(|l| *l == *level)
        && (match &def.locked_by {
            None => true,
            Some(lock) => setting_rank(level) <= setting_rank(lock),
        })
}

/// settings.rs override_of: one override, by setting, level and subject (the tenant, a team or a person), keyed "<setting>/<level>/<subject>".
///
/// Specification function `setting-override-at`.
pub fn setting_override_at(
    tenant: &types::TenantState,
    setting: &types::SettingId,
    level: &types::SettingLevel,
    subject: &String,
) -> Option<types::SettingOverride> {
    match &tenant.setting_values {
        None => None,
        Some(v) => v
            .overrides
            .get(&format!("{}/{}/{subject}", setting.0, level.as_str()))
            .cloned(),
    }
}

/// settings.rs tenant_revision: the revision of a setting at the tenant (SET-051): zero until its first change.
///
/// Specification function `setting-revision-of`.
pub fn setting_revision_of(tenant: &types::TenantState, setting: &types::SettingId) -> u64 {
    match &tenant.setting_values {
        None => 0,
        Some(v) => match v.revisions.get(setting) {
            Some(r) => *r,
            None => 0,
        },
    }
}

/// settings.rs type_problem: why a value is not a value of a setting type, or none (D-5046, SET-021). The types held are bool, i64, string and timestamp; f64 has no value in the kernel's value algebra, and the id of a declared type of kind id, scalar or enum is not held, because the kernel knows no declared types. TypeMismatch for a value of another type or a type that is not held, LimitExceeded for a value past the maximums of a record field (65536 bytes of a string).
///
/// Specification function `setting-type-problem`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn setting_type_problem(
    ty: &String,
    value: &types::Value,
) -> Result<Option<types::SettingProblem>, Fault> {
    Ok(
        if *ty == "bool" || *ty == "i64" || *ty == "string" || *ty == "timestamp" {
            if match value {
                types::Value::Bool(_) => *ty == "bool",
                types::Value::Int(_) => *ty == "i64",
                types::Value::Str(_) => *ty == "string",
                types::Value::Time(_) => *ty == "timestamp",
                _ => false,
            } {
                {
                    let p = value_limit_problem(value, 65536, 1000)?;
                    if p == "" {
                        None
                    } else {
                        Some(types::SettingProblem {
                            kind: types::ErrorKind::LimitExceeded,
                            message: p.clone(),
                        })
                    }
                }
            } else {
                Some(types::SettingProblem {
                    kind: types::ErrorKind::TypeMismatch,
                    message: format!("a {} is not a value of type {ty}", value_kind(value)),
                })
            }
        } else {
            Some(types::SettingProblem {
                kind: types::ErrorKind::TypeMismatch,
                message: if *ty == "f64" {
                    "type f64 has no value in the kernel's value algebra, which holds no float"
                        .to_string()
                } else {
                    format!(
                        "type {ty} is not one the kernel holds: bool, i64, string or timestamp (a declared id, scalar or enum type is not held)"
                    )
                },
            })
        },
    )
}

/// settings.rs resolve_definition: the value of a setting for a principal and the level it came from (SET-010 to SET-014): the person's own override, then that of the first team in id order (the ascending byte order of the identifiers, SET-011) that has the person as a member and an override, then the tenant's, then the default. A level the definition does not allow, or that a lock closes, is ignored; its override is kept (SET-024). An anonymous principal and the system have no person and no team, so they are answered from the tenant level and the default (SET-013). The platform level is absent: the control plane holds it (settings.rs, module notes).
///
/// Specification function `setting-found-of`.
pub fn setting_found_of(
    tenant: &types::TenantState,
    def: &types::SettingDef,
    principal: &types::Principal,
) -> types::SettingFound {
    let person_hit = match principal {
        types::Principal::User(id) => {
            if setting_open(def, &types::SettingLevel::Person) {
                match setting_override_at(
                    tenant,
                    &def.id,
                    &types::SettingLevel::Person,
                    &id.clone().0,
                ) {
                    Some(h) => {
                        vec![types::SettingFound {
                            source: types::SettingSource::Person,
                            team: None,
                            value: h.value.clone(),
                        }]
                    }
                    None => Vec::<types::SettingFound>::new(),
                }
            } else {
                Vec::<types::SettingFound>::new()
            }
        }
        _ => Vec::<types::SettingFound>::new(),
    };
    let team_hit = match principal {
        types::Principal::User(id) => {
            if setting_open(def, &types::SettingLevel::Team) {
                teams_of(std::sync::Arc::as_ref(&tenant.schema))
                    .values()
                    .fold(Vec::<types::SettingFound>::new(), |acc, tm| {
                        if !acc.is_empty() || !tm.members.iter().any(|m| *m == *id) {
                            acc.clone()
                        } else {
                            match setting_override_at(
                                tenant,
                                &def.id,
                                &types::SettingLevel::Team,
                                &tm.id.clone().0,
                            ) {
                                Some(h) => {
                                    vec![types::SettingFound {
                                        source: types::SettingSource::Team,
                                        team: Some(tm.id.clone()),
                                        value: h.value.clone(),
                                    }]
                                }
                                None => acc.clone(),
                            }
                        }
                    })
            } else {
                Vec::<types::SettingFound>::new()
            }
        }
        _ => Vec::<types::SettingFound>::new(),
    };
    let tenant_hit = if setting_open(def, &types::SettingLevel::Tenant) {
        match setting_override_at(
            tenant,
            &def.id,
            &types::SettingLevel::Tenant,
            &tenant.id.clone().0,
        ) {
            Some(h) => {
                vec![types::SettingFound {
                    source: types::SettingSource::Tenant,
                    team: None,
                    value: h.value.clone(),
                }]
            }
            None => Vec::<types::SettingFound>::new(),
        }
    } else {
        Vec::<types::SettingFound>::new()
    };
    {
        let candidates = support::concat(&support::concat(&person_hit, &team_hit), &tenant_hit);
        match candidates.get(0) {
            Some(f) => f.clone(),
            None => types::SettingFound {
                source: types::SettingSource::Default,
                team: None,
                value: def.default.clone(),
            },
        }
    }
}

/// settings.rs resolve: the value of a setting for a principal and the level it came from, with the revision of the setting at the tenant (SET-010 to SET-014, SET-051); the platform revision is zero while the platform level is absent. A setting the schema does not define is UnknownObject "no setting <id>" with the failed check setting:is_defined.
///
/// Specification function `resolve-setting`; fails with `rejection`.
pub fn resolve_setting(
    tenant: &types::TenantState,
    principal: &types::Principal,
    setting: &types::SettingId,
) -> Result<types::SettingResolution, types::Rejection> {
    Ok(
        match settings_of(std::sync::Arc::as_ref(&tenant.schema)).get(setting) {
            None => {
                return Err(types::Rejection::Rejected(types::DomainError {
                    kind: types::ErrorKind::UnknownObject,
                    message: format!("no setting {}", setting.0),
                    evidence: vec![types::Check {
                        rule: "setting:is_defined".to_string(),
                        passed: false,
                        detail: format!("no setting {}", setting.0),
                    }],
                    missing: None,
                }));
            }
            Some(def) => {
                let f = setting_found_of(tenant, def, principal);
                types::SettingResolution {
                    setting: def.id.clone(),
                    value: f.value.clone(),
                    source: f.source.clone(),
                    team: f.team.clone(),
                    platform_revision: 0,
                    tenant_revision: setting_revision_of(tenant, &def.id),
                }
            }
        },
    )
}

/// settings.rs refuse: a refusal of a setting write that names the check that failed after the checks that passed; unlike a refusal of the draft it adds no intent:<kind> check.
///
/// Specification function `setting-refusal`.
pub fn setting_refusal(
    passed: &Vec<types::Check>,
    kind: &types::ErrorKind,
    rule: &String,
    message: &String,
) -> types::Rejection {
    types::Rejection::Rejected(types::DomainError {
        kind: kind.clone(),
        message: message.clone(),
        evidence: support::concat(
            passed,
            &[types::Check {
                rule: rule.clone(),
                passed: false,
                detail: message.clone(),
            }],
        ),
        missing: None,
    })
}

/// settings.rs write_setting, the first check: only a signed-in person writes a setting (Unauthorized, setting:caller_is_a_person); the person is the caller.
///
/// Specification function `setting-caller`; fails with `rejection`.
pub fn setting_caller(ctx: &types::Context) -> Result<types::PrincipalId, types::Rejection> {
    Ok(match &ctx.principal {
        types::Principal::User(id) => id.clone(),
        _ => {
            return Err(setting_refusal(
                &Vec::<types::Check>::new(),
                &types::ErrorKind::Unauthorized,
                &"setting:caller_is_a_person".to_string(),
                &"only a signed-in person writes a setting".to_string(),
            ));
        }
    })
}

/// settings.rs write_setting, the capability of the level: the platform level is written by the control plane and refused (InvalidIntent, setting:platform_level_is_the_control_planes); the tenant level needs the capability setting-write-tenant and the team level setting-write-team, which the owner holds; the person level is the caller's own, whatever role the caller holds (SET-034). The check permission:capability:<name> is added when it passes.
///
/// Specification function `setting-capability`; fails with `rejection`.
pub fn setting_capability(
    tenant: &types::TenantState,
    ctx: &types::Context,
    level: &types::SettingLevel,
    evidence: &Vec<types::Check>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok(match level {
        types::SettingLevel::Platform => {
            return Err(setting_refusal(
                evidence,
                &types::ErrorKind::InvalidIntent,
                &"setting:platform_level_is_the_control_planes".to_string(),
                &"the platform level of a setting is written by the control plane".to_string(),
            ));
        }
        types::SettingLevel::Person => evidence.clone(),
        types::SettingLevel::Tenant => setting_capability_check(
            tenant,
            ctx,
            level,
            &"setting-write-tenant".to_string(),
            evidence,
        )?,
        types::SettingLevel::Team => setting_capability_check(
            tenant,
            ctx,
            level,
            &"setting-write-team".to_string(),
            evidence,
        )?,
    })
}

/// settings.rs write_setting: the acting principal holds the capability of a level (the owner holds every one): the check permission:capability:<name> passes with "holds <name>", or the write is Unauthorized "a write at the <level> level needs the capability <name>".
///
/// Specification function `setting-capability-check`; fails with `rejection`.
pub fn setting_capability_check(
    tenant: &types::TenantState,
    ctx: &types::Context,
    level: &types::SettingLevel,
    name: &String,
    evidence: &Vec<types::Check>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok(
        if roles_of(tenant, &ctx.principal)
            .iter()
            .any(|r| r.0 == "owner")
            || effective_permissions(tenant, &ctx.principal)
                .iter()
                .any(|g| *g == types::Grant::Capability(name.clone()))
        {
            support::concat(
                evidence,
                &[types::Check {
                    rule: format!("permission:capability:{name}"),
                    passed: true,
                    detail: format!("holds {name}"),
                }],
            )
        } else {
            return Err(setting_refusal(
                evidence,
                &types::ErrorKind::Unauthorized,
                &format!("permission:capability:{name}"),
                &format!(
                    "a write at the {} level needs the capability {name}",
                    level.as_str()
                ),
            ));
        },
    )
}

/// settings.rs write_setting: the definition of the setting, or UnknownObject "no setting <id>" with the failed check setting:is_defined after the checks that passed.
///
/// Specification function `setting-definition-of`; fails with `rejection`.
pub fn setting_definition_of(
    tenant: &types::TenantState,
    setting: &types::SettingId,
    evidence: &Vec<types::Check>,
) -> Result<types::SettingDef, types::Rejection> {
    Ok(
        match settings_of(std::sync::Arc::as_ref(&tenant.schema)).get(setting) {
            Some(def) => def.clone(),
            None => {
                return Err(setting_refusal(
                    evidence,
                    &types::ErrorKind::UnknownObject,
                    &"setting:is_defined".to_string(),
                    &format!("no setting {}", setting.0),
                ));
            }
        },
    )
}

/// settings.rs write_setting: the level is open (setting-open) or the write is InvalidIntent "setting <id> takes no override at the <level> level: a lock of the definition closes it" when the definition allows the level and "the definition does not allow it" when it does not (setting:level_is_open).
///
/// Specification function `setting-level-check`; fails with `rejection`.
pub fn setting_level_check(
    def: &types::SettingDef,
    setting: &types::SettingId,
    level: &types::SettingLevel,
    evidence: &Vec<types::Check>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok(if setting_open(def, level) {
        support::concat(
            evidence,
            &[types::Check {
                rule: "setting:level_is_open".to_string(),
                passed: true,
                detail: format!("{}", level.as_str()),
            }],
        )
    } else {
        return Err(setting_refusal(
            evidence,
            &types::ErrorKind::InvalidIntent,
            &"setting:level_is_open".to_string(),
            &format!(
                "setting {} takes no override at the {} level: {}",
                setting.0,
                level.as_str(),
                if def.levels.iter().any(|l| *l == *level) {
                    "a lock of the definition closes it".to_string()
                } else {
                    "the definition does not allow it".to_string()
                }
            ),
        ));
    })
}

/// settings.rs write_setting: whose override is written: the tenant's at the tenant level, the caller's own at the person level (no other person's value can be named, SET-034), the named team's at the team level. A team that does not exist is InvalidIntent "no team <id>" (setting:team_exists); the team level without a team is setting:team_named; a team named at another level is setting:team_only_at_team_level.
///
/// Specification function `setting-subject`; fails with `rejection`.
pub fn setting_subject(
    tenant: &types::TenantState,
    caller: &types::PrincipalId,
    level: &types::SettingLevel,
    team: &Option<types::TeamId>,
    evidence: &Vec<types::Check>,
) -> Result<String, types::Rejection> {
    Ok(match level {
        types::SettingLevel::Tenant => match team {
            None => tenant.id.clone().0,
            Some(_) => {
                return Err(setting_refusal(
                    evidence,
                    &types::ErrorKind::InvalidIntent,
                    &"setting:team_only_at_team_level".to_string(),
                    &format!("a write at the {} level names no team", level.as_str()),
                ));
            }
        },
        types::SettingLevel::Person => match team {
            None => caller.clone().0,
            Some(_) => {
                return Err(setting_refusal(
                    evidence,
                    &types::ErrorKind::InvalidIntent,
                    &"setting:team_only_at_team_level".to_string(),
                    &format!("a write at the {} level names no team", level.as_str()),
                ));
            }
        },
        types::SettingLevel::Team => match team {
            Some(id) => {
                if teams_of(std::sync::Arc::as_ref(&tenant.schema))
                    .get(id)
                    .is_none()
                {
                    return Err(setting_refusal(
                        evidence,
                        &types::ErrorKind::InvalidIntent,
                        &"setting:team_exists".to_string(),
                        &format!("no team {}", id.0),
                    ));
                } else {
                    id.clone().0
                }
            }
            None => {
                return Err(setting_refusal(
                    evidence,
                    &types::ErrorKind::InvalidIntent,
                    &"setting:team_named".to_string(),
                    &"a write at the team level names the team".to_string(),
                ));
            }
        },
        types::SettingLevel::Platform => {
            return Err(setting_refusal(
                evidence,
                &types::ErrorKind::InvalidIntent,
                &"setting:team_only_at_team_level".to_string(),
                &format!("a write at the {} level names no team", level.as_str()),
            ));
        }
    })
}

/// settings.rs write_setting: the value of a write has the type of the setting: a null is TypeMismatch "a null is no value of a setting; remove the override instead"; another value is checked by setting-type-problem and refused with its kind as "setting <id>: <problem>" (setting:value_has_the_type); a removal has no value to check.
///
/// Specification function `setting-value-check`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn setting_value_check(
    def: &types::SettingDef,
    setting: &types::SettingId,
    value: &Option<types::Value>,
    evidence: &Vec<types::Check>,
) -> Result<Vec<types::Check>, Failure<types::Rejection>> {
    Ok(match value {
        None => evidence.clone(),
        Some(v) => match v {
            types::Value::Null => {
                return Err(Failure::Error(setting_refusal(
                    evidence,
                    &types::ErrorKind::TypeMismatch,
                    &"setting:value_has_the_type".to_string(),
                    &"a null is no value of a setting; remove the override instead".to_string(),
                )));
            }
            _ => match setting_type_problem(&def.r#type.clone().0, v).map_err(Failure::Fault)? {
                Some(p) => {
                    return Err(Failure::Error(setting_refusal(
                        evidence,
                        &p.kind,
                        &"setting:value_has_the_type".to_string(),
                        &format!("setting {}: {}", setting.0, p.message),
                    )));
                }
                None => support::concat(
                    evidence,
                    &[types::Check {
                        rule: "setting:value_has_the_type".to_string(),
                        passed: true,
                        detail: def.r#type.clone().0,
                    }],
                ),
            },
        },
    })
}

/// settings.rs write_setting: the revision the caller read the override at (zero for an override that does not exist) is the revision it holds, or the write is VersionConflict "the override of <id> is at revision <held>, expected <expected>" (setting:revision_is_current, SET-025).
///
/// Specification function `setting-revision-check`; fails with `rejection`.
pub fn setting_revision_check(
    setting: &types::SettingId,
    held: u64,
    expected: u64,
    evidence: &Vec<types::Check>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok(if expected == held {
        support::concat(
            evidence,
            &[types::Check {
                rule: "setting:revision_is_current".to_string(),
                passed: true,
                detail: format!("{held}"),
            }],
        )
    } else {
        return Err(setting_refusal(
            evidence,
            &types::ErrorKind::VersionConflict,
            &"setting:revision_is_current".to_string(),
            &format!(
                "the override of {} is at revision {held}, expected {expected}",
                setting.0
            ),
        ));
    })
}

/// settings.rs write_setting: a new override past the most a tenant holds is LimitExceeded "<count> overrides is the maximum of <max>" (setting:overrides_within_the_maximum, limits.rs MAX_SETTING_OVERRIDES). write-setting passes the count of the tenant and 100000; the maximum is a parameter so that an example can reach it.
///
/// Specification function `setting-override-count-check`; fails with `rejection`.
pub fn setting_override_count_check(
    count: u64,
    max: u64,
    evidence: &Vec<types::Check>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok(if count >= max {
        return Err(setting_refusal(
            evidence,
            &types::ErrorKind::LimitExceeded,
            &"setting:overrides_within_the_maximum".to_string(),
            &format!("{count} overrides is the maximum of {max}"),
        ));
    } else {
        evidence.clone()
    })
}

/// settings.rs write_setting: removing an override that does not exist is InvalidIntent "there is no override of <id> to remove" (setting:override_exists); writing a new one is checked against the most overrides a tenant holds (setting-override-count-check, 100000).
///
/// Specification function `setting-existence-check`; fails with `rejection`.
pub fn setting_existence_check(
    tenant: &types::TenantState,
    setting: &types::SettingId,
    value: &Option<types::Value>,
    current: &Option<types::SettingOverride>,
    evidence: &Vec<types::Check>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok(match value {
        None => match current {
            None => {
                return Err(setting_refusal(
                    evidence,
                    &types::ErrorKind::InvalidIntent,
                    &"setting:override_exists".to_string(),
                    &format!("there is no override of {} to remove", setting.0),
                ));
            }
            Some(_) => evidence.clone(),
        },
        Some(_) => match current {
            Some(_) => evidence.clone(),
            None => setting_override_count_check(
                match &tenant.setting_values {
                    Some(v) => u64::try_from(v.overrides.keys().cloned().collect::<Vec<_>>().len())
                        .unwrap_or(u64::MAX),
                    None => 0,
                },
                100000,
                evidence,
            )?,
        },
    })
}

/// settings.rs write_setting (D-5044, D-5045, SET-020 to SET-034): set the override of a setting at a level to a value, or remove it when there is none, against the revision the caller read the override at (zero for an override that does not exist). In the order of the kernel: only a signed-in person writes (setting-caller); the capability of the level (setting-capability); the setting is defined (setting-definition-of); the level is open (setting-level-check); whose override it is (setting-subject); the value has the type (setting-value-check); the revision is current (setting-revision-check); a removal removes something and a new override is within the most a tenant holds (setting-existence-check). Accepted, the override or its removal and the new revision of the setting (one higher than at the tenant) are delta operations, one setting-changed event names the setting, the level and the subject and no value (SET-040, SET-1543), and the output is the setting with its new revision. The decision is the caller's own: the person level takes no subject, so no other person's value can be named (SET-034). The refusal is the one the check names, with the checks that passed before it and no intent:<kind> check.
///
/// Specification function `write-setting`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn write_setting(
    d: &types::Draft,
    setting: &types::SettingId,
    level: &types::SettingLevel,
    team: &Option<types::TeamId>,
    value: &Option<types::Value>,
    expected_revision: u64,
) -> Result<types::Decided, Failure<types::Rejection>> {
    let caller = setting_caller(&d.ctx).map_err(Failure::Error)?;
    let e1 = vec![types::Check {
        rule: "setting:caller_is_a_person".to_string(),
        passed: true,
        detail: caller.clone().0,
    }];
    let e2 = setting_capability(&d.tenant, &d.ctx, level, &e1).map_err(Failure::Error)?;
    let def = setting_definition_of(&d.tenant, setting, &e2).map_err(Failure::Error)?;
    let e3 = support::concat(
        &e2,
        &[types::Check {
            rule: "setting:is_defined".to_string(),
            passed: true,
            detail: setting.clone().0,
        }],
    );
    let e4 = setting_level_check(&def, setting, level, &e3).map_err(Failure::Error)?;
    let subject = setting_subject(&d.tenant, &caller, level, team, &e4).map_err(Failure::Error)?;
    let e5 = setting_value_check(&def, setting, value, &e4)?;
    let current = setting_override_at(&d.tenant, setting, level, &subject);
    let e6 = setting_revision_check(
        setting,
        match &current {
            Some(h) => h.revision,
            None => 0,
        },
        expected_revision,
        &e5,
    )
    .map_err(Failure::Error)?;
    let e7 = setting_existence_check(&d.tenant, setting, value, &current, &e6)
        .map_err(Failure::Error)?;
    let revision = setting_revision_of(&d.tenant, setting)
        .checked_add(1)
        .ok_or(Failure::Fault(Fault { op: "+" }))?;
    Ok(types::Decided {
        draft: types::Draft {
            tenant: d.tenant.clone(),
            ctx: d.ctx.clone(),
            coverage: d.coverage.clone(),
            ops: support::concat(
                &d.ops,
                &[
                    match value {
                        Some(v) => types::DeltaOp::PutSettingOverride(types::SettingOverride {
                            setting: setting.clone(),
                            level: level.clone(),
                            subject: subject.clone(),
                            value: v.clone(),
                            revision,
                            set_by: caller.clone(),
                            set_at: d.ctx.now,
                        }),
                        None => types::DeltaOp::DeleteSettingOverride {
                            setting: setting.clone(),
                            level: level.clone(),
                            subject: subject.clone(),
                        },
                    },
                    types::DeltaOp::PutSettingRevision {
                        setting: setting.clone(),
                        revision,
                    },
                ],
            ),
            events: support::concat(
                &d.events,
                &[types::EventBody::SettingChanged {
                    setting: setting.clone(),
                    level: level.clone(),
                    subject: subject.clone(),
                }],
            ),
            effects: d.effects.clone(),
            evidence: support::concat(&d.evidence, &e7),
            next_record: d.next_record,
        },
        output: types::Output::Setting {
            setting: setting.clone(),
            revision,
        },
    })
}

/// The overrides a tenant state holds, by key; none when it holds no setting values.
///
/// Specification function `setting-overrides-of`.
pub fn setting_overrides_of(
    s: &types::TenantState,
) -> std::collections::BTreeMap<String, types::SettingOverride> {
    match &s.setting_values {
        Some(v) => v.overrides.clone(),
        None => std::collections::BTreeMap::<String, types::SettingOverride>::new(),
    }
}

/// The revision of each setting a tenant state holds; none when it holds no setting values.
///
/// Specification function `setting-revisions-of`.
pub fn setting_revisions_of(
    s: &types::TenantState,
) -> std::collections::BTreeMap<types::SettingId, u64> {
    match &s.setting_values {
        Some(v) => v.revisions.clone(),
        None => std::collections::BTreeMap::<types::SettingId, u64>::new(),
    }
}

/// settings.rs apply_op: the tenant state with its overrides and revisions replaced. A state with no override and no revision holds no table of them, so it hashes as a state that never had a setting.
///
/// Specification function `tenant-with-setting-values`.
pub fn tenant_with_setting_values(
    s: &types::TenantState,
    overrides: &std::collections::BTreeMap<String, types::SettingOverride>,
    revisions: &std::collections::BTreeMap<types::SettingId, u64>,
) -> types::TenantState {
    types::TenantState {
        id: s.id.clone(),
        name: s.name.clone(),
        revision: s.revision.clone(),
        next_record: s.next_record,
        event_seq: s.event_seq,
        schema: s.schema.clone(),
        members: s.members.clone(),
        records: s.records.clone(),
        setting_values: (if overrides.keys().cloned().collect::<Vec<_>>().is_empty()
            && revisions.keys().cloned().collect::<Vec<_>>().is_empty()
        {
            None
        } else {
            Some(types::SettingValues {
                overrides: overrides.clone(),
                revisions: revisions.clone(),
            })
        })
        .map(|item_| std::sync::Arc::new(item_)),
        ledger: s.ledger.clone(),
    }
}

/// settings.rs schema_change_effects, one change: a defined setting whose type differs from the one it has (the definition of the tenant, or that of an earlier change) while overrides of it exist is the problem "setting <id>: the type changes from <a> to <b> while overrides of it exist (SET-004)"; a removed setting's overrides are deleted (once, in key order); each change raises the revision of its setting at the tenant by one (from the revision of an earlier change, else the tenant's) and is an event that names the setting, the tenant level and the tenant (SET-051, D-5048). A removal leaves the setting with no type, written as the empty text.
///
/// Specification function `setting-effects-step`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn setting_effects_step(
    tenant: &types::TenantState,
    acc: &types::SettingEffectsAcc,
    id: &types::SettingId,
    after: &String,
    removal: bool,
) -> Result<types::SettingEffectsAcc, Fault> {
    let before = match acc.types.get(id) {
        Some(t) => t.clone(),
        None => match settings_of(std::sync::Arc::as_ref(&tenant.schema)).get(id) {
            Some(d) => d.r#type.clone().0,
            None => "".to_string(),
        },
    };
    let overrides = setting_overrides_of(tenant)
        .values()
        .filter(|&o| o.setting == *id)
        .cloned()
        .collect::<Vec<_>>();
    let held = !acc.emptied.iter().any(|e| *e == *id) && !overrides.is_empty();
    Ok(if !removal && held && before != "" && before != *after {
        types::SettingEffectsAcc {
                ops: acc.ops.clone(),
                events: acc.events.clone(),
                revisions: acc.revisions.clone(),
                types: acc.types.clone(),
                emptied: acc.emptied.clone(),
                problem: Some(
                    format!(
                        "setting {}: the type changes from {before} to {after} while overrides of it exist (SET-004)",
                        id.0
                    ),
                ),
            }
    } else {
        {
            let first = removal && !acc.emptied.iter().any(|e| *e == *id);
            types::SettingEffectsAcc {
                ops: if first {
                    support::concat(
                        &acc.ops,
                        &overrides
                            .iter()
                            .map(|o| types::DeltaOp::DeleteSettingOverride {
                                setting: o.setting.clone(),
                                level: o.level.clone(),
                                subject: o.subject.clone(),
                            })
                            .collect::<Vec<_>>(),
                    )
                } else {
                    acc.ops.clone()
                },
                events: support::concat(
                    &acc.events,
                    &[types::EventBody::SettingChanged {
                        setting: id.clone(),
                        level: types::SettingLevel::Tenant,
                        subject: tenant.id.clone().0,
                    }],
                ),
                revisions: {
                    let mut map_ = acc.revisions.clone();
                    map_.insert(
                        id.clone(),
                        (match acc.revisions.get(id) {
                            Some(r) => *r,
                            None => setting_revision_of(tenant, id),
                        })
                        .checked_add(1)
                        .ok_or(Fault { op: "+" })?,
                    );
                    map_
                },
                types: {
                    let mut map_ = acc.types.clone();
                    map_.insert(
                        id.clone(),
                        if removal {
                            "".to_string()
                        } else {
                            after.clone()
                        },
                    );
                    map_
                },
                emptied: if first {
                    support::concat(&acc.emptied, &[id.clone()])
                } else {
                    acc.emptied.clone()
                },
                problem: None,
            }
        }
    })
}

/// settings.rs schema_change_effects: the overrides, the revisions and the events that a list of schema changes brings with it, or why the changes are refused: the type of a definition does not change while an override of the setting exists (SET-004; refused as InvalidSchema with the evidence so far); removing a definition removes its overrides, because an override without a definition has no type and no level; a change of a definition raises the revision of the setting at the tenant and is an event that names the setting, the tenant level and the tenant (SET-051, D-5048). The operations are the deletions in the order of the changes, then one PutSettingRevision for each setting touched, in setting id order (setting-effects-step).
///
/// Specification function `setting-change-effects`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn setting_change_effects(
    tenant: &types::TenantState,
    changes: &Vec<types::SchemaChange>,
    evidence: &Vec<types::Check>,
) -> Result<types::SettingEffects, Failure<types::Rejection>> {
    let acc = {
        let mut a: types::SettingEffectsAcc = types::SettingEffectsAcc {
            ops: Vec::<types::DeltaOp>::new(),
            events: Vec::<types::EventBody>::new(),
            revisions: std::collections::BTreeMap::<types::SettingId, u64>::new(),
            types: std::collections::BTreeMap::<types::SettingId, String>::new(),
            emptied: Vec::<types::SettingId>::new(),
            problem: None,
        };
        for c in changes.iter() {
            a = if a.problem.is_some() {
                a.clone()
            } else {
                match c {
                    types::SchemaChange::DefineSetting(d) => {
                        setting_effects_step(tenant, &a, &d.id, &d.r#type.clone().0, false)
                            .map_err(Failure::Fault)?
                    }
                    types::SchemaChange::RemoveSetting(id) => {
                        setting_effects_step(tenant, &a, id, &"".to_string(), true)
                            .map_err(Failure::Fault)?
                    }
                    _ => a.clone(),
                }
            };
        }
        a
    };
    Ok(match &acc.problem {
        Some(p) => {
            return Err(Failure::Error(draft_reject(
                evidence,
                &types::ErrorKind::InvalidSchema,
                p,
            )));
        }
        None => types::SettingEffects {
            ops: support::concat(
                &acc.ops,
                &acc.revisions
                    .keys()
                    .map(|s| types::DeltaOp::PutSettingRevision {
                        setting: s.clone(),
                        revision: match acc.revisions.get(s) {
                            Some(r) => *r,
                            None => 0,
                        },
                    })
                    .collect::<Vec<_>>(),
            ),
            events: acc.events.clone(),
        },
    })
}

/// settings.rs definition_problems, one definition: held under another key than its id; allows no level; a lock that is by a team or a person (a lock is by the platform or the tenant); a blank label; a default that is not a value of its type (setting-type-problem, SET-002). The names of platform definitions (SET-003) are none yet.
///
/// Specification function `setting-def-problems`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn setting_def_problems(
    key: &types::SettingId,
    def: &types::SettingDef,
) -> Result<Vec<String>, Fault> {
    let at = format!("setting {}", def.id.0);
    Ok(support::concat(
        &support::concat(
            &support::concat(
                &support::concat(
                    &(if *key != def.id {
                        vec![format!("{at}: held under the key {}", key.0)]
                    } else {
                        Vec::<String>::new()
                    }),
                    &(if def.levels.is_empty() {
                        vec![format!("{at}: a setting allows at least one level")]
                    } else {
                        Vec::<String>::new()
                    }),
                ),
                &(match &def.locked_by {
                    Some(l) => match l {
                        types::SettingLevel::Team => {
                            vec![format!("{at}: a lock is by the platform or the tenant")]
                        }
                        types::SettingLevel::Person => {
                            vec![format!("{at}: a lock is by the platform or the tenant")]
                        }
                        _ => Vec::<String>::new(),
                    },
                    None => Vec::<String>::new(),
                }),
            ),
            &(if def.label.as_str().trim().to_string() == "" {
                vec![format!("{at}: a setting needs a label")]
            } else {
                Vec::<String>::new()
            }),
        ),
        &(match setting_type_problem(&def.r#type.clone().0, &def.default)? {
            Some(p) => vec![format!("{at}: default: {} (SET-002)", p.message)],
            None => Vec::<String>::new(),
        }),
    ))
}

/// settings.rs definition_problems: the problems of the setting definitions of a schema, in the order of their ids: more than 500 settings, then each definition (setting-def-problems).
///
/// Specification function `setting-problems`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn setting_problems(schema: &types::TenantSchema) -> Result<Vec<String>, Fault> {
    Ok(match &schema.settings {
        None => Vec::<String>::new(),
        Some(defs) => support::concat(
            &limit_count_problem(
                &"settings".to_string(),
                u64::try_from(defs.keys().cloned().collect::<Vec<_>>().len()).unwrap_or(u64::MAX),
                500,
            ),
            &({
                let mut ps: Vec<String> = Vec::<String>::new();
                for k in defs.keys() {
                    ps = support::concat(
                        &ps,
                        &({
                            let mut qs: Vec<String> = Vec::<String>::new();
                            for d in defs.values() {
                                qs = if defs.get(k) == Some(d) {
                                    setting_def_problems(k, d)?
                                } else {
                                    qs.clone()
                                };
                            }
                            qs
                        }),
                    );
                }
                ps
            }),
        ),
    })
}

/// capabilities.rs split_once("__"): the text before the first two underscores in a row and the text after them, or none when there are none. The body language has no substring, so the characters are scanned with a lone underscore held back until the next character tells whether it begins the separator.
///
/// Specification function `capability-parts`.
pub fn capability_parts(id: &String) -> Option<types::CapabilitySplit> {
    {
        let scan = id
            .as_str()
            .chars()
            .map(String::from)
            .collect::<Vec<_>>()
            .iter()
            .fold(
                types::SplitScan {
                    before: "".to_string(),
                    after: "".to_string(),
                    held: "".to_string(),
                    seen: false,
                },
                |s, c| {
                    if s.seen {
                        types::SplitScan {
                            before: s.before.clone(),
                            after: format!("{}{c}", s.after),
                            held: "".to_string(),
                            seen: true,
                        }
                    } else if s.held == "_" {
                        if *c == "_" {
                            types::SplitScan {
                                before: s.before.clone(),
                                after: "".to_string(),
                                held: "".to_string(),
                                seen: true,
                            }
                        } else {
                            types::SplitScan {
                                before: format!("{}{c}", format!("{}_", s.before)),
                                after: "".to_string(),
                                held: "".to_string(),
                                seen: false,
                            }
                        }
                    } else if *c == "_" {
                        types::SplitScan {
                            before: s.before.clone(),
                            after: "".to_string(),
                            held: "_".to_string(),
                            seen: false,
                        }
                    } else {
                        types::SplitScan {
                            before: format!("{}{c}", s.before),
                            after: "".to_string(),
                            held: "".to_string(),
                            seen: false,
                        }
                    }
                },
            );
        if scan.seen {
            Some(types::CapabilitySplit {
                namespace: scan.before.clone(),
                name: scan.after.clone(),
            })
        } else {
            None
        }
    }
}

/// capabilities.rs namespace_of: the namespace of an id of the product form (member_tiers__promote is in member_tiers), or none for an id of the platform form or one whose namespace or name is empty.
///
/// Specification function `capability-namespace`.
pub fn capability_namespace(id: &String) -> Option<String> {
    match capability_parts(id) {
        Some(p) => {
            if p.namespace != "" && p.name != "" {
                Some(p.namespace.clone())
            } else {
                None
            }
        }
        None => None,
    }
}

/// capabilities.rs grant_problem: why a role may not grant a capability, or none (D-6590, D-6701): a capability of the product form (its id has two underscores in a row) must be declared in the tenant, and a role that belongs to a product (its id has a namespace) grants only the capabilities of that product. A role of the tenant's own, with no namespace, may grant any declared capability. A name of the platform form is the platform's.
///
/// Specification function `capability-grant-problem`.
pub fn capability_grant_problem(
    schema: &types::TenantSchema,
    role: &types::RoleId,
    name: &String,
) -> Option<String> {
    match capability_parts(name) {
        None => None,
        Some(_) => {
            if capabilities_of(schema)
                .get(&types::CapabilityName(name.clone()))
                .is_none()
            {
                Some(format!(
                    "capability {name} is neither a platform capability nor declared in the tenant"
                ))
            } else {
                match capability_namespace(&role.clone().0) {
                    Some(of_role) => match capability_namespace(name) {
                        Some(of_capability) => {
                            if of_role != of_capability {
                                Some(
                                        format!(
                                            "capability {name} belongs to product {of_capability} and role {} to product {of_role}",
                                            role.0
                                        ),
                                    )
                            } else {
                                None
                            }
                        }
                        None => None,
                    },
                    None => None,
                }
            }
        }
    }
}

/// capabilities.rs declaration_problems (D-6590): the problems of the capabilities a schema declares, in the order of their ids: more than 200, then each: held under another key than its id; an id that is not a namespace and a name of lower-case letters, digits and underscores each starting with a letter, joined by two underscores, of at most 128 bytes; a blank name.
///
/// Specification function `capability-problems`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn capability_problems(schema: &types::TenantSchema) -> Result<Vec<String>, Fault> {
    Ok(match &schema.capabilities {
        None => Vec::<String>::new(),
        Some(declared) => support::concat(
            &limit_count_problem(
                &"capabilities".to_string(),
                u64::try_from(declared.keys().cloned().collect::<Vec<_>>().len())
                    .unwrap_or(u64::MAX),
                200,
            ),
            &({
                let mut ps: Vec<String> = Vec::<String>::new();
                for k in declared.keys() {
                    ps = support::concat(
                        &ps,
                        &({
                            let mut qs: Vec<String> = Vec::<String>::new();
                            for d in declared.values() {
                                qs = if declared.get(k) == Some(d) {
                                    capability_def_problems(k, d)?
                                } else {
                                    qs.clone()
                                };
                            }
                            qs
                        }),
                    );
                }
                ps
            }),
        ),
    })
}

/// capabilities.rs declaration_problems, one declaration: held under another key than its id; an id that is not a namespace and a name of lower-case letters, digits and underscores each starting with a letter, joined by two underscores, of at most 128 bytes (capability-well-formed); a blank name.
///
/// Specification function `capability-def-problems`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn capability_def_problems(
    key: &types::CapabilityName,
    d: &types::CapabilityDef,
) -> Result<Vec<String>, Fault> {
    Ok(support::concat(
        &support::concat(
            &(if *key != d.id {
                vec![format!(
                    "capability {}: held under the key {}",
                    d.id.0, key.0
                )]
            } else {
                Vec::<String>::new()
            }),
            &(if capability_well_formed(&d.id.clone().0)? {
                Vec::<String>::new()
            } else {
                vec![
                        format!("capability {}: an id is a namespace and a name of lower-case letters, digits and underscores, joined by two underscores",
                        d.id.0)
                    ]
            }),
        ),
        &(if d.name.as_str().trim().to_string() == "" {
            vec![format!("capability {}: a capability needs a name", d.id.0)]
        } else {
            Vec::<String>::new()
        }),
    ))
}

/// capabilities.rs well_formed: whether an id is <namespace>__<name>, each part of [a-z][a-z0-9_]*, the namespace not ending in an underscore so that the first two underscores in a row are the separator, at most 128 bytes.
///
/// Specification function `capability-well-formed`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn capability_well_formed(id: &String) -> Result<bool, Fault> {
    Ok(match capability_parts(id) {
        None => false,
        Some(p) => {
            capability_part(&p.namespace)
                && !p.namespace.as_str().ends_with("_")
                && capability_part(&p.name)
                && utf8_length(id)? <= 128
        }
    })
}

/// capabilities.rs well_formed, one part: it starts with a lower-case letter and has only lower-case letters, digits and underscores.
///
/// Specification function `capability-part`.
pub fn capability_part(text: &String) -> bool {
    match text
        .as_str()
        .chars()
        .map(String::from)
        .collect::<Vec<_>>()
        .get(0)
    {
        Some(c) => {
            support::every_char(c.as_str(), char::is_ascii_lowercase)
                && text
                    .as_str()
                    .chars()
                    .map(String::from)
                    .collect::<Vec<_>>()
                    .iter()
                    .all(|x| {
                        support::every_char(x.as_str(), char::is_ascii_lowercase)
                            || support::every_char(x.as_str(), char::is_ascii_digit)
                            || *x == "_"
                    })
        }
        None => false,
    }
}

/// ledger.rs scope_text: the scope of a request or a limit: empty when it names none (D-6551).
///
/// Specification function `ledger-scope-text`.
pub fn ledger_scope_text(scope: &Option<types::LedgerScope>) -> String {
    match scope {
        Some(s) => s.clone().0,
        None => "".to_string(),
    }
}

/// ledger.rs declarations: the declarations of a schema; an empty set when it declares nothing.
///
/// Specification function `ledger-of`.
pub fn ledger_of(schema: &types::TenantSchema) -> types::LedgerDeclarations {
    match &schema.ledger {
        Some(l) => l.clone(),
        None => types::LedgerDeclarations {
            units: std::collections::BTreeMap::<types::LedgerUnit, types::LedgerUnitDecl>::new(),
            pools: std::collections::BTreeMap::<types::LedgerPoolName, types::LedgerPoolDecl>::new(
            ),
            limits: Vec::<types::LedgerLimit>::new(),
        },
    }
}

/// The tenant schema with its ledger declarations replaced (the other members as they were). A table left empty is no table at all, so a schema that declares nothing hashes as one that never did (ledger.rs tidy).
///
/// Specification function `schema-with-ledger`.
pub fn schema_with_ledger(
    schema: &types::TenantSchema,
    ledger: &types::LedgerDeclarations,
) -> types::TenantSchema {
    types::TenantSchema {
        version: schema.version.clone(),
        objects: schema.objects.clone(),
        roles: schema.roles.clone(),
        role_permissions: schema.role_permissions.clone(),
        teams: schema.teams.clone(),
        invitations: schema.invitations.clone(),
        policies: schema.policies.clone(),
        workflows: schema.workflows.clone(),
        queries: schema.queries.clone(),
        views: schema.views.clone(),
        triggers: schema.triggers.clone(),
        automations: schema.automations.clone(),
        operations: schema.operations.clone(),
        settings: schema.settings.clone(),
        capabilities: schema.capabilities.clone(),
        ledger: if ledger.units.keys().cloned().collect::<Vec<_>>().is_empty()
            && ledger.pools.keys().cloned().collect::<Vec<_>>().is_empty()
            && ledger.limits.is_empty()
        {
            None
        } else {
            Some(ledger.clone())
        },
        mail_templates: schema.mail_templates.clone(),
        notice_templates: schema.notice_templates.clone(),
        tokens: schema.tokens.clone(),
        products: schema.products.clone(),
        ui: schema.ui.clone(),
    }
}

/// ledger.rs same_limit: whether a limit is of the same unit, or of the same account: the same unit and owner, and for an owner the same scope.
///
/// Specification function `ledger-same-limit`.
pub fn ledger_same_limit(
    a: &types::LedgerLimit,
    unit: &types::LedgerUnit,
    owner: &Option<types::LedgerOwner>,
    scope: &String,
) -> bool {
    a.unit == *unit
        && a.owner == *owner
        && (owner.is_none() || ledger_scope_text(&a.scope) == *scope)
}

/// ledger.rs declaration_problems: a floor or a cap outside the range of an amount (D-5004), as "<at>: <amount> is outside the range of an amount". The range is a parameter so that an example can reach it: ledger-limit-problems passes 9007199254740991 (2^53 - 1), and a number past it cannot be written in an example.
///
/// Specification function `ledger-amount-problem`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn ledger_amount_problem(
    at: &String,
    amount: &Option<types::LedgerAmount>,
    max: i64,
) -> Result<Vec<String>, Fault> {
    Ok(match amount {
        Some(a) => {
            if a.clone().0 > max || a.clone().0 < max.checked_neg().ok_or(Fault { op: "-" })? {
                vec![format!("{at}: {} is outside the range of an amount", a.0)]
            } else {
                Vec::<String>::new()
            }
        }
        None => Vec::<String>::new(),
    })
}

/// ledger.rs declaration_problems, one limit: a unit that is not declared, a pool owner that is not declared, a limit of a unit that names a scope, a scope of more than 128 bytes, a floor above the cap, a floor or cap outside the range of an amount (D-5004), a cap per period without its period (or the reverse), and a limit that sets nothing (CT-286).
///
/// Specification function `ledger-limit-problems`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn ledger_limit_problems(
    ledger: &types::LedgerDeclarations,
    l: &types::LedgerLimit,
) -> Result<Vec<String>, Fault> {
    let at = format!("ledger limit of {}", l.unit.0);
    Ok(support::concat(
        &support::concat(
            &support::concat(
                &support::concat(
                    &support::concat(
                        &support::concat(
                            &support::concat(
                                &(if ledger.units.get(&l.unit).is_none() {
                                    vec![format!("{at}: unknown ledger unit {}", l.unit.0)]
                                } else {
                                    Vec::<String>::new()
                                }),
                                &(match &l.owner {
                                    Some(o) => match o {
                                        types::LedgerOwner::Pool { pool } => {
                                            if ledger.pools.get(pool).is_none() {
                                                vec![format!(
                                                    "{at}: unknown ledger pool {}",
                                                    pool.0
                                                )]
                                            } else {
                                                Vec::<String>::new()
                                            }
                                        }
                                        _ => Vec::<String>::new(),
                                    },
                                    None => {
                                        if ledger_scope_text(&l.scope) != "" {
                                            vec![format!("{at}: a limit of a unit names no scope")]
                                        } else {
                                            Vec::<String>::new()
                                        }
                                    }
                                }),
                            ),
                            &(if utf8_length(&ledger_scope_text(&l.scope))? > 128 {
                                vec![format!("{at}: a scope is at most 128 bytes")]
                            } else {
                                Vec::<String>::new()
                            }),
                        ),
                        &(match &l.floor {
                            Some(f) => match &l.cap {
                                Some(c) => {
                                    if f.clone().0 > c.clone().0 {
                                        vec![format!(
                                            "{at}: the floor {} is above the cap {}",
                                            f.0, c.0
                                        )]
                                    } else {
                                        Vec::<String>::new()
                                    }
                                }
                                None => Vec::<String>::new(),
                            },
                            None => Vec::<String>::new(),
                        }),
                    ),
                    &ledger_amount_problem(&at, &l.floor, 9007199254740991)?,
                ),
                &ledger_amount_problem(&at, &l.cap, 9007199254740991)?,
            ),
            &(if l.period_cap.is_some() != l.period.is_some() {
                vec![format!(
                    "{at}: a cap per period needs its period, and a period its cap"
                )]
            } else {
                Vec::<String>::new()
            }),
        ),
        &(if l.floor.is_none() && l.cap.is_none() && l.period_cap.is_none() {
            vec![format!("{at}: sets no limit")]
        } else {
            Vec::<String>::new()
        }),
    ))
}

/// ledger.rs declaration_problems: the problems of the ledger declarations of a schema, in a fixed order: the ceilings of LDG-1550 (64 units, 64 pools and 10000 limits of one account), a unit or a pool declared under another name (in id order), then each limit in the order held (ledger-limit-problems).
///
/// Specification function `ledger-problems`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn ledger_problems(schema: &types::TenantSchema) -> Result<Vec<String>, Fault> {
    Ok(match &schema.ledger {
        None => Vec::<String>::new(),
        Some(l) => support::concat(
            &support::concat(
                &support::concat(
                    &support::concat(
                        &support::concat(
                            &limit_count_problem(
                                &"ledger units".to_string(),
                                u64::try_from(l.units.keys().cloned().collect::<Vec<_>>().len())
                                    .unwrap_or(u64::MAX),
                                64,
                            ),
                            &limit_count_problem(
                                &"ledger pools".to_string(),
                                u64::try_from(l.pools.keys().cloned().collect::<Vec<_>>().len())
                                    .unwrap_or(u64::MAX),
                                64,
                            ),
                        ),
                        &limit_count_problem(
                            &"ledger account limits".to_string(),
                            u64::try_from(
                                l.limits
                                    .iter()
                                    .filter(|&x| x.owner.is_some())
                                    .cloned()
                                    .collect::<Vec<_>>()
                                    .len(),
                            )
                            .unwrap_or(u64::MAX),
                            10000,
                        ),
                    ),
                    &l.units.keys().fold(Vec::<String>::new(), |ps, k| {
                        support::concat(
                            &ps,
                            &l.units.values().fold(Vec::<String>::new(), |qs, d| {
                                if l.units.get(k) == Some(d) && d.unit != *k {
                                    vec![format!(
                                        "ledger unit {}: declared under another name",
                                        k.0
                                    )]
                                } else {
                                    qs.clone()
                                }
                            }),
                        )
                    }),
                ),
                &l.pools.keys().fold(Vec::<String>::new(), |ps, k| {
                    support::concat(
                        &ps,
                        &l.pools.values().fold(Vec::<String>::new(), |qs, d| {
                            if l.pools.get(k) == Some(d) && d.pool != *k {
                                vec![format!("ledger pool {}: declared under another name", k.0)]
                            } else {
                                qs.clone()
                            }
                        }),
                    )
                }),
            ),
            &({
                let mut ps: Vec<String> = Vec::<String>::new();
                for x in l.limits.iter() {
                    ps = support::concat(&ps, &ledger_limit_problems(l, x)?);
                }
                ps
            }),
        ),
    })
}

/// ledger.rs schema_change_needs: the needs of the ledger changes of a schema change: whether an account names a unit or a pool being removed (LDG-1549), the limit of the one account a removed account limit names (D-6554), and every limit of single accounts when an account limit is set, to count them against the ceiling (D-7881, LDG-1550).
///
/// Specification function `ledger-change-needs`.
pub fn ledger_change_needs(changes: &Vec<types::SchemaChange>) -> Vec<types::Need> {
    changes
        .iter()
        .fold(Vec::<types::Need>::new(), |acc, c| match c {
            types::SchemaChange::RemoveLedgerDefinition(r) => match r {
                types::LedgerDefinitionRef::Unit { unit } => support::concat(
                    &acc,
                    &[types::Need::Ledger(types::LedgerNeed::UnitUsed {
                        unit: unit.clone(),
                    })],
                ),
                types::LedgerDefinitionRef::Pool { pool } => support::concat(
                    &acc,
                    &[types::Need::Ledger(types::LedgerNeed::PoolUsed {
                        pool: pool.clone(),
                    })],
                ),
                types::LedgerDefinitionRef::Limit { unit, owner, scope } => match owner {
                    Some(o) => support::concat(
                        &acc,
                        &[types::Need::Ledger(types::LedgerNeed::Limit {
                            owner: o.clone(),
                            unit: unit.clone(),
                            scope: match scope {
                                Some(s) => s.clone(),
                                None => types::LedgerScope("".to_string()),
                            },
                        })],
                    ),
                    None => acc.clone(),
                },
            },
            types::SchemaChange::SetLedgerLimit(l) => match &l.owner {
                Some(_) => support::concat(&acc, &[types::Need::Ledger(types::LedgerNeed::Limits)]),
                None => acc.clone(),
            },
            _ => acc.clone(),
        })
}

/// ledger.rs check_limits, one change: the limit of one account that a change sets or removes (LDG-1550, D-6554, WG-5172). Account limits live in the ledger's storage and not in the schema. Setting one: the snapshot must hold the limits of single accounts (the need limits) unless an earlier change loaded them, or the change is InsufficientState naming it; one of a new account when max are held is LimitExceeded "too-many: a tenant holds at most <max> account limits" with the failed check ledger:too-many-limits; otherwise the limit replaces the one of its account among those held and ledger:account-limits passes with "<n> account limit(s) after the change". Removing one: from the limits held when an earlier change loaded them, otherwise the snapshot must hold the limit of that account (the need limit); one that is not held is InvalidSchema "no such limit of ledger unit <unit>" with the failed check ledger:limit-exists. The checks are written after the evidence of the walk. Any other change leaves the walk as it is.
///
/// Specification function `ledger-limit-step`; fails with `rejection`.
pub fn ledger_limit_step(
    d: &types::Draft,
    w: &types::LedgerLimitWalk,
    c: &types::SchemaChange,
    max: u64,
) -> Result<types::LedgerLimitWalk, types::Rejection> {
    let stored_limits = match &d.tenant.ledger {
        Some(s) => match &s.limits {
            Some(ls) => ls.clone(),
            None => Vec::<types::LedgerLimit>::new(),
        },
        None => Vec::<types::LedgerLimit>::new(),
    };
    Ok(match c {
        types::SchemaChange::SetLedgerLimit(l) => match &l.owner {
            Some(_) => {
                let wanted = types::Need::Ledger(types::LedgerNeed::Limits);
                if w.held.is_none() && !covers(&d.coverage, &wanted) {
                    return Err(types::Rejection::Rejected(insufficient(&wanted)));
                } else {
                    {
                        let text = ledger_scope_text(&l.scope);
                        {
                            let all = match &w.held {
                                Some(h) => h.clone(),
                                None => stored_limits
                                    .iter()
                                    .filter(|&x| x.owner.is_some())
                                    .cloned()
                                    .collect::<Vec<_>>(),
                            };
                            if !all
                                .iter()
                                .any(|x| ledger_same_limit(x, &l.unit, &l.owner, &text))
                                && u64::try_from(all.len()).unwrap_or(u64::MAX) >= max
                            {
                                return Err(
                                            types::Rejection::Rejected(types::DomainError {
                                                kind: types::ErrorKind::LimitExceeded,
                                                message: format!(
                                                    "too-many: a tenant holds at most {max} account limits"
                                                ),
                                                evidence: support::concat(
                                                    &w.evidence,
                                                    &[
                                                        types::Check {
                                                            rule: "ledger:too-many-limits".to_string(),
                                                            passed: false,
                                                            detail: format!(
                                                                "too-many: a tenant holds at most {max} account limits"
                                                            ),
                                                        },
                                                    ],
                                                ),
                                                missing: None,
                                            }),
                                        );
                            } else {
                                {
                                    let after = support::concat(
                                        &all.iter()
                                            .filter(|&x| {
                                                !ledger_same_limit(x, &l.unit, &l.owner, &text)
                                            })
                                            .cloned()
                                            .collect::<Vec<_>>(),
                                        &[l.clone()],
                                    );
                                    types::LedgerLimitWalk {
                                        evidence: support::concat(
                                            &w.evidence,
                                            &[types::Check {
                                                rule: "ledger:account-limits".to_string(),
                                                passed: true,
                                                detail: format!(
                                                    "{} account limit(s) after the change",
                                                    u64::try_from(after.len()).unwrap_or(u64::MAX)
                                                ),
                                            }],
                                        ),
                                        held: Some(after.clone()),
                                    }
                                }
                            }
                        }
                    }
                }
            }
            None => w.clone(),
        },
        types::SchemaChange::RemoveLedgerDefinition(r) => match r {
            types::LedgerDefinitionRef::Limit { unit, owner, scope } => match owner {
                Some(o) => {
                    let text = ledger_scope_text(scope);
                    match &w.held {
                        Some(h) => {
                            let kept = h
                                .iter()
                                .filter(|&x| !ledger_same_limit(x, unit, owner, &text))
                                .cloned()
                                .collect::<Vec<_>>();
                            if u64::try_from(kept.len()).unwrap_or(u64::MAX)
                                == u64::try_from(h.len()).unwrap_or(u64::MAX)
                            {
                                return Err(types::Rejection::Rejected(types::DomainError {
                                    kind: types::ErrorKind::InvalidSchema,
                                    message: format!("no such limit of ledger unit {}", unit.0),
                                    evidence: support::concat(
                                        &w.evidence,
                                        &[types::Check {
                                            rule: "ledger:limit-exists".to_string(),
                                            passed: false,
                                            detail: format!(
                                                "no such limit of ledger unit {}",
                                                unit.0
                                            ),
                                        }],
                                    ),
                                    missing: None,
                                }));
                            } else {
                                types::LedgerLimitWalk {
                                    evidence: w.evidence.clone(),
                                    held: Some(kept.clone()),
                                }
                            }
                        }
                        None => {
                            let wanted = types::Need::Ledger(types::LedgerNeed::Limit {
                                owner: o.clone(),
                                unit: unit.clone(),
                                scope: match scope {
                                    Some(q) => q.clone(),
                                    None => types::LedgerScope("".to_string()),
                                },
                            });
                            if !covers(&d.coverage, &wanted) {
                                return Err(types::Rejection::Rejected(insufficient(&wanted)));
                            } else if !stored_limits
                                .iter()
                                .any(|x| ledger_same_limit(x, unit, owner, &text))
                            {
                                return Err(types::Rejection::Rejected(types::DomainError {
                                    kind: types::ErrorKind::InvalidSchema,
                                    message: format!("no such limit of ledger unit {}", unit.0),
                                    evidence: support::concat(
                                        &w.evidence,
                                        &[types::Check {
                                            rule: "ledger:limit-exists".to_string(),
                                            passed: false,
                                            detail: format!(
                                                "no such limit of ledger unit {}",
                                                unit.0
                                            ),
                                        }],
                                    ),
                                    missing: None,
                                }));
                            } else {
                                w.clone()
                            }
                        }
                    }
                }
                None => w.clone(),
            },
            _ => w.clone(),
        },
        _ => w.clone(),
    })
}

/// ledger.rs check_limits: the evidence of the draft with the checks of the limits of single accounts among the changes, in order (ledger-limit-step, at most 10000 held, LDG-1550), or the refusal of the first change that fails. The limits of a unit are not checked here.
///
/// Specification function `ledger-limit-checks`; fails with `rejection`.
pub fn ledger_limit_checks(
    d: &types::Draft,
    changes: &Vec<types::SchemaChange>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok({
        let walk = {
            let mut acc: types::LedgerLimitWalk = types::LedgerLimitWalk {
                evidence: d.evidence.clone(),
                held: None,
            };
            for c in changes.iter() {
                acc = ledger_limit_step(d, &acc, c, 10000)?;
            }
            acc
        };
        walk.evidence.clone()
    })
}

/// ledger.rs limit_ops: the delta operations of the limits of single accounts among the changes, in order (WG-5172): setting one puts it, removing one removes it from the ledger's own storage in the commit of the schema change. The limits of a unit stay in the schema.
///
/// Specification function `ledger-limit-ops`.
pub fn ledger_limit_ops(changes: &Vec<types::SchemaChange>) -> Vec<types::DeltaOp> {
    changes
        .iter()
        .fold(Vec::<types::DeltaOp>::new(), |acc, c| match c {
            types::SchemaChange::SetLedgerLimit(l) => match &l.owner {
                Some(_) => support::concat(
                    &acc,
                    &[types::DeltaOp::Ledger(types::LedgerDelta::PutLimit(
                        l.clone(),
                    ))],
                ),
                None => acc.clone(),
            },
            types::SchemaChange::RemoveLedgerDefinition(r) => match r {
                types::LedgerDefinitionRef::Limit { unit, owner, scope } => match owner {
                    Some(o) => support::concat(
                        &acc,
                        &[types::DeltaOp::Ledger(types::LedgerDelta::RemoveLimit {
                            owner: o.clone(),
                            unit: unit.clone(),
                            scope: match scope {
                                Some(q) => q.clone(),
                                None => types::LedgerScope("".to_string()),
                            },
                        })],
                    ),
                    None => acc.clone(),
                },
                _ => acc.clone(),
            },
            _ => acc.clone(),
        })
}

/// ledger.rs check_removals (LDG-1549, LDG-1550, D-6554, WG-5172): first the limits of single accounts among the changes (ledger-limit-checks), then a unit or a pool that an account names is not removed. For each removal of a unit or a pool, in order: the snapshot must cover the need (unit-used, pool-used), or the change is InsufficientState naming it; an account that names it is StillReferenced "ledger unit <id> is named by an account and is not removed" with the failed check ledger:in-use after the evidence so far (no intent:<kind> check); otherwise ledger:in-use passes with "no account names ledger unit <id>". The accounts are those of the snapshot.
///
/// Specification function `ledger-removal-check`; fails with `rejection`.
pub fn ledger_removal_check(
    d: &types::Draft,
    changes: &Vec<types::SchemaChange>,
) -> Result<types::Draft, types::Rejection> {
    let accounts = match &d.tenant.ledger {
        Some(l) => l.accounts.values().cloned().collect::<Vec<_>>(),
        None => Vec::<types::LedgerAccount>::new(),
    };
    Ok({
        let evidence = ledger_limit_checks(d, changes)?;
        {
            let d1 = types::Draft {
                tenant: d.tenant.clone(),
                ctx: d.ctx.clone(),
                coverage: d.coverage.clone(),
                ops: d.ops.clone(),
                events: d.events.clone(),
                effects: d.effects.clone(),
                evidence: evidence.clone(),
                next_record: d.next_record,
            };
            {
                let mut acc: types::Draft = d1.clone();
                for c in changes.iter() {
                    acc = match c {
                        types::SchemaChange::RemoveLedgerDefinition(r) => match r {
                            types::LedgerDefinitionRef::Unit { unit } => ledger_removal_step(
                                &acc,
                                &types::Need::Ledger(types::LedgerNeed::UnitUsed {
                                    unit: unit.clone(),
                                }),
                                &format!("ledger unit {}", unit.0),
                                accounts.iter().any(|a| a.unit == *unit),
                            )?,
                            types::LedgerDefinitionRef::Pool { pool } => ledger_removal_step(
                                &acc,
                                &types::Need::Ledger(types::LedgerNeed::PoolUsed {
                                    pool: pool.clone(),
                                }),
                                &format!("ledger pool {}", pool.0),
                                accounts.iter().any(|a| match &a.owner {
                                    Some(o) => match o {
                                        types::LedgerOwner::Pool { pool: p } => *p == *pool,
                                        _ => false,
                                    },
                                    None => false,
                                }),
                            )?,
                            types::LedgerDefinitionRef::Limit { .. } => acc.clone(),
                        },
                        _ => acc.clone(),
                    };
                }
                acc
            }
        }
    })
}

/// ledger.rs check_removals, one removal: the snapshot covers the need or the change is InsufficientState; an account that names the unit or the pool (used) is StillReferenced with the failed check ledger:in-use; otherwise the check passes.
///
/// Specification function `ledger-removal-step`; fails with `rejection`.
pub fn ledger_removal_step(
    d: &types::Draft,
    wanted: &types::Need,
    what: &String,
    used: bool,
) -> Result<types::Draft, types::Rejection> {
    Ok(if !covers(&d.coverage, wanted) {
        return Err(types::Rejection::Rejected(insufficient(wanted)));
    } else if used {
        return Err(types::Rejection::Rejected(types::DomainError {
            kind: types::ErrorKind::StillReferenced,
            message: format!("{what} is named by an account and is not removed"),
            evidence: support::concat(
                &d.evidence,
                &[types::Check {
                    rule: "ledger:in-use".to_string(),
                    passed: false,
                    detail: format!("{what} is named by an account and is not removed"),
                }],
            ),
            missing: None,
        }));
    } else {
        types::Draft {
            tenant: d.tenant.clone(),
            ctx: d.ctx.clone(),
            coverage: d.coverage.clone(),
            ops: d.ops.clone(),
            events: d.events.clone(),
            effects: d.effects.clone(),
            evidence: support::concat(
                &d.evidence,
                &[types::Check {
                    rule: "ledger:in-use".to_string(),
                    passed: true,
                    detail: format!("no account names {what}"),
                }],
            ),
            next_record: d.next_record,
        }
    })
}

/// Division that rounds toward negative infinity (Rust i64::div_euclid for a positive divisor); the body language's / truncates toward zero.
///
/// Specification function `floor-div`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn floor_div(a: i64, b: i64) -> Result<i64, Fault> {
    Ok(if a >= 0 {
        a.checked_div(b).ok_or(Fault { op: "/" })?
    } else {
        0i64.checked_sub(
            0i64.checked_sub(a)
                .ok_or(Fault { op: "-" })?
                .checked_add(b)
                .ok_or(Fault { op: "+" })?
                .checked_sub(1)
                .ok_or(Fault { op: "-" })?
                .checked_div(b)
                .ok_or(Fault { op: "/" })?,
        )
        .ok_or(Fault { op: "-" })?
    })
}

/// The remainder that goes with floor-div (Rust i64::rem_euclid for a positive divisor): never negative.
///
/// Specification function `floor-mod`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn floor_mod(a: i64, b: i64) -> Result<i64, Fault> {
    Ok(
        a.checked_sub(floor_div(a, b)?.checked_mul(b).ok_or(Fault { op: "*" })?)
            .ok_or(Fault { op: "-" })?,
    )
}

/// ledger.rs days_from_civil: the days since 1970-01-01 of a civil date (proleptic Gregorian), after H. Hinnant.
///
/// Specification function `ledger-days-from-civil`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn ledger_days_from_civil(year: i64, month: i64, day: i64) -> Result<i64, Fault> {
    let y = if month <= 2 {
        year.checked_sub(1).ok_or(Fault { op: "-" })?
    } else {
        year
    };
    let era = floor_div(y, 400)?;
    let yoe = y
        .checked_sub(era.checked_mul(400).ok_or(Fault { op: "*" })?)
        .ok_or(Fault { op: "-" })?;
    let mp = month
        .checked_add(9)
        .ok_or(Fault { op: "+" })?
        .checked_rem(12)
        .ok_or(Fault { op: "%" })?;
    let doy = 153i64
        .checked_mul(mp)
        .ok_or(Fault { op: "*" })?
        .checked_add(2)
        .ok_or(Fault { op: "+" })?
        .checked_div(5)
        .ok_or(Fault { op: "/" })?
        .checked_add(day)
        .ok_or(Fault { op: "+" })?
        .checked_sub(1)
        .ok_or(Fault { op: "-" })?;
    let doe = yoe
        .checked_mul(365)
        .ok_or(Fault { op: "*" })?
        .checked_add(yoe.checked_div(4).ok_or(Fault { op: "/" })?)
        .ok_or(Fault { op: "+" })?
        .checked_sub(yoe.checked_div(100).ok_or(Fault { op: "/" })?)
        .ok_or(Fault { op: "-" })?
        .checked_add(doy)
        .ok_or(Fault { op: "+" })?;
    Ok(era
        .checked_mul(146097)
        .ok_or(Fault { op: "*" })?
        .checked_add(doe)
        .ok_or(Fault { op: "+" })?
        .checked_sub(719468)
        .ok_or(Fault { op: "-" })?)
}

/// ledger.rs civil_month: the civil year and month of a count of days since 1970-01-01.
///
/// Specification function `ledger-civil-month`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn ledger_civil_month(days: i64) -> Result<types::CivilMonth, Fault> {
    let z = days.checked_add(719468).ok_or(Fault { op: "+" })?;
    let era = floor_div(z, 146097)?;
    let doe = z
        .checked_sub(era.checked_mul(146097).ok_or(Fault { op: "*" })?)
        .ok_or(Fault { op: "-" })?;
    let yoe = doe
        .checked_sub(doe.checked_div(1460).ok_or(Fault { op: "/" })?)
        .ok_or(Fault { op: "-" })?
        .checked_add(doe.checked_div(36524).ok_or(Fault { op: "/" })?)
        .ok_or(Fault { op: "+" })?
        .checked_sub(doe.checked_div(146096).ok_or(Fault { op: "/" })?)
        .ok_or(Fault { op: "-" })?
        .checked_div(365)
        .ok_or(Fault { op: "/" })?;
    let doy = doe
        .checked_sub(
            365i64
                .checked_mul(yoe)
                .ok_or(Fault { op: "*" })?
                .checked_add(yoe.checked_div(4).ok_or(Fault { op: "/" })?)
                .ok_or(Fault { op: "+" })?
                .checked_sub(yoe.checked_div(100).ok_or(Fault { op: "/" })?)
                .ok_or(Fault { op: "-" })?,
        )
        .ok_or(Fault { op: "-" })?;
    let mp = 5i64
        .checked_mul(doy)
        .ok_or(Fault { op: "*" })?
        .checked_add(2)
        .ok_or(Fault { op: "+" })?
        .checked_div(153)
        .ok_or(Fault { op: "/" })?;
    let month = if mp < 10 {
        mp.checked_add(3).ok_or(Fault { op: "+" })?
    } else {
        mp.checked_sub(9).ok_or(Fault { op: "-" })?
    };
    Ok(types::CivilMonth {
        year: yoe
            .checked_add(era.checked_mul(400).ok_or(Fault { op: "*" })?)
            .ok_or(Fault { op: "+" })?
            .checked_add(if month <= 2 { 1 } else { 0 })
            .ok_or(Fault { op: "+" })?,
        month,
    })
}

/// ledger.rs period_start: the start of the calendar period in UTC that contains an instant: the hour, the day, the week starting on Monday, or the month (D-5005, LDG-015). 1970-01-01 was a Thursday, three days after a Monday.
///
/// Specification function `ledger-period-start`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn ledger_period_start(period: &types::LedgerPeriod, at: i64) -> Result<i64, Fault> {
    let days = floor_div(at, 86400000)?;
    Ok(match period {
        types::LedgerPeriod::Hour => floor_div(at, 3600000)?
            .checked_mul(3600000)
            .ok_or(Fault { op: "*" })?,
        types::LedgerPeriod::Day => days.checked_mul(86400000).ok_or(Fault { op: "*" })?,
        types::LedgerPeriod::Week => days
            .checked_sub(floor_mod(days.checked_add(3).ok_or(Fault { op: "+" })?, 7)?)
            .ok_or(Fault { op: "-" })?
            .checked_mul(86400000)
            .ok_or(Fault { op: "*" })?,
        types::LedgerPeriod::Month => ledger_days_from_civil(
            ledger_civil_month(days)?.year,
            ledger_civil_month(days)?.month,
            1,
        )?
        .checked_mul(86400000)
        .ok_or(Fault { op: "*" })?,
    })
}

/// ledger.rs limits_of: a cap per period and its period are one limit: both are set or the limit has none.
///
/// Specification function `ledger-period-cap-of`.
pub fn ledger_period_cap_of(l: &types::LedgerLimit) -> Option<types::LedgerPeriodCap> {
    match l.period_cap {
        Some(c) => match &l.period {
            Some(p) => Some(types::LedgerPeriodCap {
                cap: c,
                period: p.clone(),
            }),
            None => None,
        },
        None => None,
    }
}

/// ledger.rs limits_of: the limits that apply to the account of an owner, unit and scope under a schema: each of the own limits of the account and, for each one the account does not set, the limit of its unit (LDG-012). The limit of the account is the first of the unit with that owner and scope; that of the unit the first with no owner.
///
/// Specification function `ledger-limits-of`.
pub fn ledger_limits_of(
    schema: &types::TenantSchema,
    owner: &types::LedgerOwner,
    unit: &types::LedgerUnit,
    scope: &String,
) -> types::LedgerLimitsApplying {
    let of_unit = ledger_of(schema)
        .limits
        .iter()
        .find(|&l| l.unit == *unit && l.owner.is_none())
        .cloned();
    let of_account = ledger_of(schema)
        .limits
        .iter()
        .find(|&l| {
            l.unit == *unit
                && l.owner.as_ref() == Some(owner)
                && ledger_scope_text(&l.scope) == *scope
        })
        .cloned();
    let acc_floor = match &of_account {
        Some(a) => a.floor.clone(),
        None => None,
    };
    let acc_cap = match &of_account {
        Some(a) => a.cap.clone(),
        None => None,
    };
    let acc_period = match &of_account {
        Some(a) => ledger_period_cap_of(a),
        None => None,
    };
    let unit_floor = match &of_unit {
        Some(u) => u.floor.clone(),
        None => None,
    };
    let unit_cap = match &of_unit {
        Some(u) => u.cap.clone(),
        None => None,
    };
    let unit_period = match &of_unit {
        Some(u) => ledger_period_cap_of(u),
        None => None,
    };
    types::LedgerLimitsApplying {
        floor: if acc_floor.is_some() {
            acc_floor.clone()
        } else {
            unit_floor.clone()
        },
        cap: if acc_cap.is_some() {
            acc_cap.clone()
        } else {
            unit_cap.clone()
        },
        period_cap: if acc_period.is_some() {
            acc_period.clone()
        } else {
            unit_period.clone()
        },
    }
}

/// schema.rs mentions_field: whether an expression reads a field of a record (a scope read of a name that is not a $ system attribute, or any read through a reference), in any branch, whether it runs or not. Structural recursion: every call of itself is on a field of a variant matched from e, or an item of a list such a field holds (WG-5133).
///
/// Specification function `mentions-field`.
pub fn mentions_field(e: &types::Expr) -> bool {
    match e {
        types::Expr::Var(_, f) => !f.as_str().starts_with("$"),
        types::Expr::Through(_, _, _) => true,
        types::Expr::Not(a) => mentions_field(&(**a)),
        types::Expr::IsNull(a) => mentions_field(&(**a)),
        types::Expr::Len(a) => mentions_field(&(**a)),
        types::Expr::Lower(a) => mentions_field(&(**a)),
        types::Expr::IsSlug(a) => mentions_field(&(**a)),
        types::Expr::Text(a) => mentions_field(&(**a)),
        types::Expr::Duration(_, amount) => mentions_field(&(**amount)),
        types::Expr::And(items) => items.iter().any(|i| mentions_field(i)),
        types::Expr::Or(items) => items.iter().any(|i| mentions_field(i)),
        types::Expr::Cmp(_, left, right) => mentions_field(&(**left)) || mentions_field(&(**right)),
        types::Expr::In(item, l) => mentions_field(&(**item)) || mentions_field(&(**l)),
        types::Expr::Contains(haystack, needle) => {
            mentions_field(&(**haystack)) || mentions_field(&(**needle))
        }
        types::Expr::StartsWith(t, prefix) => mentions_field(&(**t)) || mentions_field(&(**prefix)),
        types::Expr::Arith(_, left, right) => {
            mentions_field(&(**left)) || mentions_field(&(**right))
        }
        types::Expr::MsBetween(a, b) => mentions_field(&(**a)) || mentions_field(&(**b)),
        types::Expr::Concat(left, right) => mentions_field(&(**left)) || mentions_field(&(**right)),
        types::Expr::If(c, a, b) => {
            mentions_field(&(**c)) || mentions_field(&(**a)) || mentions_field(&(**b))
        }
        _ => false,
    }
}

/// crates/kernel/src/read.rs visible_in: visible with the snapshot's lookup, the decision read makes per row: authorize Read on the record's object type, against the tenant's own schema, with the record as old and new (authorize-needing with the snapshot's coverage), so a Read policy that follows a reference is decided on the record it reaches. A policy that needs a record the snapshot does not cover is InsufficientState naming it, not a denial (WG-5096).
///
/// Specification function `visible-in`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn visible_in(
    tenant: &types::TenantState,
    coverage: &types::Coverage,
    principal: &types::Principal,
    record: &types::Record,
    now: crate::prelude::Timestamp,
) -> Result<bool, Failure<types::Rejection>> {
    let decision = authorize_needing(
        tenant,
        std::sync::Arc::as_ref(&tenant.schema),
        principal,
        now,
        &types::Action::Read,
        &types::Resource::Object(record.object.clone()),
        &types::Subject {
            old: Some(record.clone()),
            new: Some(record.clone()),
        },
        &Some(coverage.clone()),
    )
    .map_err(Failure::Fault)?;
    Ok(if decision.allowed {
        true
    } else {
        match &decision.needed {
            Some(n) => {
                return Err(Failure::Error(types::Rejection::Rejected(insufficient(n))));
            }
            None => false,
        }
    })
}

/// ledger.rs refused: a refusal after the checks in evidence, naming the rule that failed: the message is "<rule>: <message>" and the failed check is added to the evidence.
///
/// Specification function `ledger-refused`.
pub fn ledger_refused(
    evidence: &Vec<types::Check>,
    kind: &types::ErrorKind,
    rule: &String,
    message: &String,
) -> types::DomainError {
    types::DomainError {
        kind: kind.clone(),
        message: format!("{rule}: {message}"),
        evidence: support::concat(
            evidence,
            &[types::Check {
                rule: rule.clone(),
                passed: false,
                detail: message.clone(),
            }],
        ),
        missing: None,
    }
}

/// ledger.rs post_after, the checks a posting makes before it reads its account (WG-5170): the unit is declared (ledger:unit, else UnknownRecord ledger:unknown-unit), the owner is a member or a declared pool (ledger:owner, else UnknownRecord ledger:unknown-owner), the amount is a whole number from -(2^53-1) to 2^53-1 other than 0 (ledger:invalid-amount), the idempotency key is 1 to 128 bytes and does not start with expiry: (ledger:invalid-key), the reason is at most 256 bytes (ledger:invalid-reason) and the scope at most 128 bytes (ledger:invalid-scope). The evidence given is extended with the checks that passed; a failed check refuses with them. What follows, the account (named by a uuid derived from the SHA-256 of the tenant, owner, unit and scope), is not stated here.
///
/// Specification function `ledger-posting-precheck`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn ledger_posting_precheck(
    tenant: &types::TenantState,
    evidence: &Vec<types::Check>,
    request: &types::LedgerPostingRequest,
) -> Result<Vec<types::Check>, Failure<types::Rejection>> {
    let decl = ledger_of(std::sync::Arc::as_ref(&tenant.schema));
    let key = request.idempotency_key.clone();
    let a = request.amount.clone();
    Ok(if decl.units.get(&request.unit).is_none() {
        return Err(Failure::Error(types::Rejection::Rejected(ledger_refused(
            evidence,
            &types::ErrorKind::UnknownRecord,
            &"ledger:unknown-unit".to_string(),
            &format!("the tenant declares no ledger unit {}", request.unit.0),
        ))));
    } else {
        {
            let e1 = support::concat(
                evidence,
                &[types::Check {
                    rule: "ledger:unit".to_string(),
                    passed: true,
                    detail: format!("unit {} is declared", request.unit.0),
                }],
            );
            {
                let owner_problem = match &request.owner {
                    types::LedgerOwner::Principal { principal: p } => {
                        if tenant.members.get(p).is_none() {
                            format!("the tenant has no principal {}", p.0)
                        } else {
                            "".to_string()
                        }
                    }
                    types::LedgerOwner::Pool { pool: q } => {
                        if decl.pools.get(q).is_none() {
                            format!("the tenant declares no ledger pool {}", q.0)
                        } else {
                            "".to_string()
                        }
                    }
                };
                if owner_problem != "" {
                    return Err(Failure::Error(types::Rejection::Rejected(ledger_refused(
                        &e1,
                        &types::ErrorKind::UnknownRecord,
                        &"ledger:unknown-owner".to_string(),
                        &owner_problem,
                    ))));
                } else {
                    {
                        let e2 = support::concat(
                            &e1,
                            &[types::Check {
                                rule: "ledger:owner".to_string(),
                                passed: true,
                                detail: "the owner exists".to_string(),
                            }],
                        );
                        if a.clone().0 == 0
                            || a.clone().0 > 9007199254740991
                            || a.clone().0 < -9007199254740991
                        {
                            return Err(
                                    Failure::Error(
                                        types::Rejection::Rejected(
                                            ledger_refused(
                                                &e2,
                                                &types::ErrorKind::InvalidIntent,
                                                &"ledger:invalid-amount".to_string(),
                                                &format!(
                                                    "an amount is a whole number from -9007199254740991 to 9007199254740991 other than 0, not {}",
                                                    a.0
                                                ),
                                            ),
                                        ),
                                    ),
                                );
                        } else if key == "" || utf8_length(&key).map_err(Failure::Fault)? > 128 {
                            return Err(Failure::Error(types::Rejection::Rejected(ledger_refused(
                                &e2,
                                &types::ErrorKind::InvalidIntent,
                                &"ledger:invalid-key".to_string(),
                                &"an idempotency key is 1 to 128 bytes".to_string(),
                            ))));
                        } else if key.as_str().starts_with("expiry:") {
                            return Err(Failure::Error(types::Rejection::Rejected(ledger_refused(
                                &e2,
                                &types::ErrorKind::InvalidIntent,
                                &"ledger:invalid-key".to_string(),
                                &"the key prefix expiry: belongs to the expiry of credits"
                                    .to_string(),
                            ))));
                        } else if utf8_length(&request.reason).map_err(Failure::Fault)? > 256 {
                            return Err(Failure::Error(types::Rejection::Rejected(ledger_refused(
                                &e2,
                                &types::ErrorKind::InvalidIntent,
                                &"ledger:invalid-reason".to_string(),
                                &"a reason is at most 256 bytes".to_string(),
                            ))));
                        } else if utf8_length(&ledger_scope_text(&request.scope))
                            .map_err(Failure::Fault)?
                            > 128
                        {
                            return Err(Failure::Error(types::Rejection::Rejected(ledger_refused(
                                &e2,
                                &types::ErrorKind::InvalidIntent,
                                &"ledger:invalid-scope".to_string(),
                                &"a scope is at most 128 bytes".to_string(),
                            ))));
                        } else {
                            e2.clone()
                        }
                    }
                }
            }
        }
    })
}

/// ledger.rs decide_intent, the intent post-ledger (CT-281), as far as it is decided before an account is read (WG-5170): the principal holds ledger-post (the owner holds every capability; else Unauthorized with the failed permission:capability:ledger-post check), the intent names 1 to 8 postings (ledger:postings), and the first posting passes ledger-posting-precheck, whose refusal is the intent's. The result is the checks that passed. What follows reads the first posting's account, which is named by a uuid derived from the SHA-256 of the tenant, owner, unit and scope; the function language has neither (WG-5257, WG-5258), so intent-decision refuses it with ledger:decided_by_the_ledger_module after these checks.
///
/// Specification function `ledger-intent-decision`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn ledger_intent_decision(
    d: &types::Draft,
    postings: &Vec<types::LedgerPostingRequest>,
) -> Result<Vec<types::Check>, Failure<types::Rejection>> {
    let rule = "permission:capability:ledger-post".to_string();
    let holds = roles_of(&d.tenant, &d.ctx.principal)
        .iter()
        .any(|r| r.0 == "owner")
        || effective_permissions(&d.tenant, &d.ctx.principal)
            .iter()
            .any(|g| *g == types::Grant::Capability("ledger-post".to_string()));
    Ok(if !holds {
        return Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::Unauthorized,
                message: "a posting needs the capability ledger-post".to_string(),
                evidence: vec![types::Check {
                    rule: rule.clone(),
                    passed: false,
                    detail: "does not hold ledger-post".to_string(),
                }],
                missing: None,
            },
        )));
    } else {
        {
            let evidence = vec![types::Check {
                rule: rule.clone(),
                passed: true,
                detail: "holds ledger-post".to_string(),
            }];
            if u64::try_from(postings.len()).unwrap_or(u64::MAX) == 0
                || u64::try_from(postings.len()).unwrap_or(u64::MAX) > 8
            {
                return Err(Failure::Error(types::Rejection::Rejected(ledger_refused(
                    &evidence,
                    &types::ErrorKind::InvalidIntent,
                    &"ledger:postings".to_string(),
                    &format!(
                        "a posting change names 1 to 8 postings, not {}",
                        u64::try_from(postings.len()).unwrap_or(u64::MAX)
                    ),
                ))));
            } else {
                {
                    let mut acc: Vec<types::Check> = evidence.clone();
                    for first in postings.iter().take(1).cloned().collect::<Vec<_>>().iter() {
                        acc = ledger_posting_precheck(&d.tenant, &acc, first)?;
                    }
                    acc
                }
            }
        }
    })
}

/// What the functions share: list helpers and the bridges to the languages.
mod support {
    use crate::types;

    /// The items of `a`, then those of `b`.
    pub(super) fn concat<T: Clone>(a: &[T], b: &[T]) -> Vec<T> {
        let mut out = a.to_vec();
        out.extend_from_slice(b);
        out
    }

    /// How many items `take` keeps: none for a count below one.
    pub(super) fn count(n: i128) -> usize {
        if n <= 0 {
            0
        } else {
            usize::try_from(n).unwrap_or(usize::MAX)
        }
    }

    /// Whether a string has a character and every one passes the test (Exegra's
    /// isAscii* operations).
    pub(super) fn every_char(s: &str, test: fn(&char) -> bool) -> bool {
        !s.is_empty() && s.chars().all(|c| test(&c))
    }

    /// The items of `(key, item)` pairs ordered by their keys, stably.
    pub(super) fn sort_keyed<K: Ord + Clone, T>(mut keyed: Vec<(K, T)>) -> Vec<T> {
        keyed.sort_by_key(|pair| pair.0.clone());
        keyed.into_iter().map(|(_, item)| item).collect()
    }

    /// The items ordered by a key, stably.
    pub(super) fn sorted_by<'a, T: Clone + 'a, K: Ord>(
        items: impl Iterator<Item = &'a T>,
        key: impl FnMut(&T) -> K,
    ) -> Vec<T> {
        let mut out: Vec<T> = items.cloned().collect();
        out.sort_by_key(key);
        out
    }

    impl crate::tenant_rule_language::Record for std::collections::BTreeMap<String, types::Value> {
        fn system_attribute(&self, name: &str) -> types::Value {
            self.get(name).cloned().unwrap_or(types::Value::Null)
        }

        fn field(&self, name: &str) -> Result<types::Value, String> {
            Ok(self.get(name).cloned().unwrap_or(types::Value::Null))
        }
    }
    pub(super) fn eval_tenant_rule_language_expr_env(
        expr: &types::Expr,
        env: &types::ExprEnv,
    ) -> Result<types::Value, String> {
        let now = match &env.now {
            types::Value::Time(t) => *t,
            other => return Err(format!("the scope now holds {other:?}, not a time")),
        };
        let principal = match &env.principal {
            types::Value::Str(id) => Some(id.clone()),
            types::Value::Null => None,
            other => {
                return Err(format!(
                    "the scope principal holds {other:?}, not a principal's id or null"
                ));
            }
        };

        struct Scopes<'a> {
            env: &'a types::ExprEnv,
            now: i64,
            principal: Option<String>,
        }

        impl crate::tenant_rule_language::Env for Scopes<'_> {
            fn record(
                &self,
                scope: &types::Scope,
            ) -> Option<&dyn crate::tenant_rule_language::Record> {
                let record = match scope {
                    types::Scope::Record => &self.env.record,
                    types::Scope::Old => &self.env.old,
                    types::Scope::New => &self.env.new,
                };
                record
                    .as_ref()
                    .map(|r| r as &dyn crate::tenant_rule_language::Record)
            }

            fn follow(
                &self,
                _scope: &types::Scope,
                _field: &str,
                _target: &types::RecordId,
            ) -> Result<
                Option<Box<dyn crate::tenant_rule_language::Record + '_>>,
                crate::tenant_rule_language::EvalError,
            > {
                Err(crate::tenant_rule_language::EvalError(
                    "following a reference needs a lookup, and none is available".to_string(),
                ))
            }

            fn param(&self, name: &str) -> Option<types::Value> {
                self.env.param.get(name).cloned()
            }

            fn now(&self) -> i64 {
                self.now
            }

            fn principal(&self) -> Option<String> {
                self.principal.clone()
            }

            fn has_role(&self, role: &str) -> bool {
                self.env.has_role.iter().any(|held| held == role)
            }
        }
        crate::tenant_rule_language::eval(
            expr,
            &Scopes {
                env,
                now,
                principal,
            },
        )
        .map_err(|e| e.0)
    }
    pub(super) fn eval_lookup_tenant_rule_language_expr_env(
        expr: &types::Expr,
        env: &types::ExprEnv,
        lookup: &std::collections::BTreeMap<
            String,
            std::collections::BTreeMap<String, std::collections::BTreeMap<String, types::Value>>,
        >,
    ) -> Result<types::Value, String> {
        let now = match &env.now {
            types::Value::Time(t) => *t,
            other => return Err(format!("the scope now holds {other:?}, not a time")),
        };
        let principal = match &env.principal {
            types::Value::Str(id) => Some(id.clone()),
            types::Value::Null => None,
            other => {
                return Err(format!(
                    "the scope principal holds {other:?}, not a principal's id or null"
                ));
            }
        };

        struct Scopes<'a> {
            env: &'a types::ExprEnv,
            lookup: &'a std::collections::BTreeMap<
                String,
                std::collections::BTreeMap<
                    String,
                    std::collections::BTreeMap<String, types::Value>,
                >,
            >,
            now: i64,
            principal: Option<String>,
        }

        impl crate::tenant_rule_language::Env for Scopes<'_> {
            fn record(
                &self,
                scope: &types::Scope,
            ) -> Option<&dyn crate::tenant_rule_language::Record> {
                let record = match scope {
                    types::Scope::Record => &self.env.record,
                    types::Scope::Old => &self.env.old,
                    types::Scope::New => &self.env.new,
                };
                record
                    .as_ref()
                    .map(|r| r as &dyn crate::tenant_rule_language::Record)
            }

            fn follow(
                &self,
                _scope: &types::Scope,
                field: &str,
                target: &types::RecordId,
            ) -> Result<
                Option<Box<dyn crate::tenant_rule_language::Record + '_>>,
                crate::tenant_rule_language::EvalError,
            > {
                let Some(covered) = self.lookup.get(field) else {
                    return Err(crate::tenant_rule_language::EvalError(format!(
                        "the lookup does not cover {field}"
                    )));
                };
                Ok(covered.get(&target.0.to_string()).map(|found| {
                    Box::new(found.clone()) as Box<dyn crate::tenant_rule_language::Record + '_>
                }))
            }

            fn param(&self, name: &str) -> Option<types::Value> {
                self.env.param.get(name).cloned()
            }

            fn now(&self) -> i64 {
                self.now
            }

            fn principal(&self) -> Option<String> {
                self.principal.clone()
            }

            fn has_role(&self, role: &str) -> bool {
                self.env.has_role.iter().any(|held| held == role)
            }
        }
        crate::tenant_rule_language::eval(
            expr,
            &Scopes {
                env,
                lookup,
                now,
                principal,
            },
        )
        .map_err(|e| e.0)
    }
    pub(super) fn check_tenant_rule_language_expr_check_env(
        expr: &types::Expr,
        env: &types::ExprCheckEnv,
    ) -> Result<String, String> {
        struct Site<'a>(&'a types::ExprCheckEnv);

        impl crate::tenant_rule_language::TypeEnv for Site<'_> {
            fn field_shape(
                &self,
                through: Option<&str>,
                name: &str,
            ) -> Result<crate::tenant_rule_language::Shape, String> {
                if through.is_some() {
                    return Ok(crate::tenant_rule_language::Shape::Any);
                }
                match self.0.fields.get(name).map(String::as_str) {
                    Some("bool") => Ok(crate::tenant_rule_language::Shape::Bool),
                    Some("int") => Ok(crate::tenant_rule_language::Shape::Int),
                    Some("str") => Ok(crate::tenant_rule_language::Shape::Str),
                    Some("time") => Ok(crate::tenant_rule_language::Shape::Time),
                    Some("ref") => Ok(crate::tenant_rule_language::Shape::Ref),
                    Some("list") => Ok(crate::tenant_rule_language::Shape::List),
                    Some("any") => Ok(crate::tenant_rule_language::Shape::Any),
                    Some(other) => Err(format!("the field {name} has the unknown shape {other}")),
                    None => Err(format!("unknown field {name}")),
                }
            }

            fn follow(&self, field: &str) -> Result<(), String> {
                if self.0.fields.contains_key(field) {
                    Ok(())
                } else {
                    Err(format!("unknown field {field}"))
                }
            }

            fn has_param(&self, name: &str) -> bool {
                self.0.params.iter().any(|p| p == name)
            }

            fn has_role(&self, role: &str) -> bool {
                self.0.roles.iter().any(|r| r == role)
            }
        }
        crate::tenant_rule_language::check(expr, &Site(env)).map(|shape| {
            let name = match shape {
                crate::tenant_rule_language::Shape::Bool => "bool",
                crate::tenant_rule_language::Shape::Int => "int",
                crate::tenant_rule_language::Shape::Str => "str",
                crate::tenant_rule_language::Shape::Time => "time",
                crate::tenant_rule_language::Shape::Ref => "ref",
                crate::tenant_rule_language::Shape::List => "list",
                crate::tenant_rule_language::Shape::Any => "any",
            };
            name.to_string()
        })
    }
}
